-- 013_blog.sql — generated, do not edit by hand
CREATE TABLE IF NOT EXISTS blog_posts (
  id          TEXT PRIMARY KEY,
  title       TEXT NOT NULL,
  slug        TEXT UNIQUE NOT NULL,
  category    TEXT NOT NULL,
  excerpt     TEXT,
  content     TEXT NOT NULL,
  author_name TEXT DEFAULT 'Isaya Masika',
  status      TEXT DEFAULT 'published',
  created_at  DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_blog_created ON blog_posts (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_blog_status  ON blog_posts (status);

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('glassmorphism-button', 'How to Create a Glassmorphism Button Using HTML and CSS', 'glassmorphism-button', 'CSS', 'Build a glassmorphism button with backdrop blur, layered transparency and a hover lift that stays readable on any background.', '<p>Glassmorphism looks expensive and costs almost nothing: a translucent fill, a blur behind it, and a hairline border that catches the light. The part most tutorials skip is contrast — on a busy background the label quietly disappears.</p><h2>The markup</h2><pre><code>&lt;button class="glass-btn"&gt;&lt;span&gt;Get the kit&lt;/span&gt;&lt;/button&gt;</code></pre><h2>The styles that matter</h2><pre><code>.glass-btn { position: relative; padding: 14px 26px; border-radius: 14px; font: 600 15px/1 system-ui, sans-serif; color: #111827; background: rgba(255, 255, 255, 0.55); border: 1px solid rgba(255, 255, 255, 0.70); backdrop-filter: blur(14px) saturate(160%); -webkit-backdrop-filter: blur(14px) saturate(160%); box-shadow: 0 10px 30px rgba(17, 24, 39, 0.12), inset 0 1px 0 rgba(255, 255, 255, 0.90); transition: transform 180ms ease, box-shadow 180ms ease, background 180ms ease; } .glass-btn:hover { transform: translateY(-2px); background: rgba(255, 255, 255, 0.72); box-shadow: 0 16px 40px rgba(17, 24, 39, 0.18), inset 0 1px 0 #fff; }</code></pre><p>Three decisions do the work: the fill sits at 55 percent (not 20), the border is lighter than the fill so the edge reads as a highlight, and the inset top shadow fakes a bevel. If your text still washes out, raise the fill before you touch the blur radius — opacity is the free lever, blur is the expensive one.</p><h2>Make it behave</h2><pre><code>@media (max-width: 640px) { .glass-btn { padding: 12px 20px; font-size: 14px; } } @media (prefers-reduced-motion: reduce) { .glass-btn { transition: none; } .glass-btn:hover { transform: none; } }</code></pre><p>On iOS the blur is cheap; on low-end Android it can cost a frame. The rule I use: one blurred surface per screen. A hero button is fine, a grid of nine is not.</p><h2>Ship checklist</h2><ul><li>Test over both light and dark backgrounds — the border vanishes on white.</li><li>Check with reduced motion enabled; the lift should disappear, the contrast should not.</li><li>On dark themes swap the fill to <code>rgba(255,255,255,0.08)</code> and the label to <code>#f9fafb</code>.</li></ul><p>The ready-made version, hover animation included, lives in the <a href="/components">component library</a>.</p>', 'Isaya Masika', 'published', '2026-11-10');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('css-hover-effects', 'Five CSS Hover Effects That Do Not Feel Cheap', 'css-hover-effects', 'CSS', 'Five hover treatments that read as craft rather than gimmick: lift, ink underline, magnetic offset, reveal and restrained tilt — each with the exact CSS.', '<p>Most hover effects feel cheap because they animate the wrong property. Scaling a card to 1.15, stacking three shadows on hover, or transitioning everything with a 400ms ease turns a crisp interface into jelly. The five below all share one rule: <strong>move at most two pixels, or one line.</strong></p><h2>1. The lift</h2><pre><code>.lift { transition: transform 160ms ease, box-shadow 160ms ease; } .lift:hover { transform: translateY(-3px); box-shadow: 0 14px 34px rgba(17,24,39,.09); }</code></pre><p>Three pixels, not ten. The shadow carries the depth; the transform only signals direction.</p><h2>2. Ink underline</h2><pre><code>.ink { position: relative; text-decoration: none; } .ink::after { content: ""; position: absolute; left: 0; bottom: -2px; width: 100%; height: 2px; background: currentColor; transform: scaleX(0); transform-origin: left; transition: transform 220ms cubic-bezier(.2,.8,.2,1); } .ink:hover::after { transform: scaleX(1); }</code></pre><p>Scale a decoration, never the text — scaling type reflows and looks blurry mid-animation.</p><h2>3. Magnetic offset</h2><pre><code>.magnetic { transition: transform 220ms cubic-bezier(.2,.8,.2,1); } .magnetic:hover { transform: translateX(4px); }</code></pre><p>Four pixels in the direction of the arrow inside the button reads as intent. Paired with a chevron, it is the single most convincing “this is clickable” cue there is.</p><h2>4. The reveal</h2><pre><code>.reveal { overflow: hidden; } .reveal span { display: inline-block; transition: transform 260ms ease; } .reveal:hover span { transform: translateY(-2px); }</code></pre><h2>5. Restrained tilt</h2><pre><code>.tilt { transition: transform 200ms ease; } .tilt:hover { transform: rotate(-1.2deg) translateY(-2px); }</code></pre><p>One degree is craft; six degrees is a toy. Keep <code>transform-origin</code> at center and pair it with a <code>--book-depth</code>-style static shadow so the object feels like it has weight.</p><h2>The shared contract</h2><ul><li>Never transition <code>all</code>. List the properties, and keep it under 260ms.</li><li>Wrap every block in <code>@media (prefers-reduced-motion: reduce) { transform: none }</code>.</li><li>Hover states need a keyboard twin: use <code>:focus-visible</code> with the same rules.</li></ul>', 'Isaya Masika', 'published', '2026-11-11');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-localstorage-auth', 'React LocalStorage Auth: Cache the User Without Poking a Hole in Security', 'react-localstorage-auth', 'React', 'Keep the session in an HttpOnly cookie, but paint the avatar from localStorage so returning users never see a Sign in button flicker.', '<p>Every cookie-auth app hits the same 400ms: the header has no idea whether the visitor is signed in until <code>/api/auth/me</code> resolves. For that window you show either a stale “Sign in” or an empty slot. Both look broken.</p><p>The fix is not “trust localStorage”. It is: <strong>use localStorage to paint, use the cookie to decide</strong>.</p><h2>Two states, not one</h2><pre><code>{ email: "a@b.com", verified: false } // optimistic seed, paint only { email: "a@b.com", verified: true } // cookie confirmed by the server</code></pre><p>The optimistic copy renders the avatar and greeting. It must not unlock downloads, paid content, or anything the API would refuse anyway.</p><h2>Reading the seed safely</h2><pre><code>const SEED_KEY = "stea_user"; function readSeed() { try { const raw = localStorage.getItem(SEED_KEY); if (!raw) return null; const p = JSON.parse(raw); return p?.email ? { email: p.email, verified: false } : null; } catch { return null; } }</code></pre><p>Corrupted values must degrade to signed-out. Never let <code>JSON.parse</code> throw inside render.</p><h2>Verify in the background, downgrade only on a definitive answer</h2><pre><code>useEffect(() =&gt; { let dead = false; fetch("/api/auth/me", { credentials: "include" }) .then(async (res) =&gt; { if (dead) return; const body = await res.json().catch(() =&gt; null); if (!body?.email) { localStorage.removeItem(SEED_KEY); setUser(null); return; } localStorage.setItem(SEED_KEY, JSON.stringify({ email: body.email })); setUser({ email: body.email, verified: true }); }) .catch(() =&gt; { /* offline: keep the seed, retry later */ }); return () =&gt; { dead = true; }; }, []);</code></pre><p>That catch is the whole trick. Treating a 500 or a dropped connection as “logged out” is how you kick people out on the subway.</p><h2>Do not mix the two keys</h2><p>Keep <code>stea_user</code> (server truth) and <code>stea_last_email</code> (what the human typed last time) separate. Conflating them means a failed login pre-fills a form with an address that was never verified.</p>', 'Isaya Masika', 'published', '2026-11-12');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('sticky-tailwind-navbar', 'A Sticky Navbar That Survives Mobile Without a Hamburger', 'sticky-tailwind-navbar', 'Tailwind', 'Sticky headers break on small screens because of three things: scroll anchoring, safe-area insets and a menu that fights the layout.', '<p>A sticky header is three lines of CSS. Keeping it usable on a 375px phone is the hard part, and almost every failure traces back to one of the same three causes.</p><h2>Cause 1 — the header scrolls away, then jumps back</h2><pre><code>&lt;header style="position: sticky; top: 0; z-index: 40;"&gt;</code></pre><p><code>position: sticky</code> silently does nothing if any ancestor sets <code>overflow: hidden</code> or <code>overflow: auto</code>. On phones, a card or a hero with <code>overflow-x: hidden</code> (added to kill horizontal scroll) is the usual culprit. Remove the overflow from ancestors, not from the header.</p><h2>Cause 2 — the notch</h2><pre><code>padding-top: env(safe-area-inset-top); padding-left: max(16px, env(safe-area-inset-left)); padding-right: max(16px, env(safe-area-inset-right));</code></pre><p>Without the safe-area insets the logo sits under the notch on landscape. This is a two-line fix that most tutorials skip entirely.</p><h2>Cause 3 — the menu that fights the layout</h2><p>On a phone you rarely have room for six tabs. Two options that actually work:</p><ul><li><strong>Collapse to the three most used</strong> and send the rest to the footer. This is what we do on SteaCode: Icons, Library and Blog stay, everything else lives in the footer.</li><li><strong>Horizontal scroll strip</strong>: <code>overflow-x: auto; scrollbar-width: none;</code> with <code>scroll-snap-type: x mandatory</code>.</li></ul><pre><code>.nav-strip { display: flex; gap: 4px; overflow-x: auto; scrollbar-width: none; scroll-snap-type: x mandatory; -webkit-overflow-scrolling: touch; } .nav-strip::-webkit-scrollbar { display: none; } .nav-strip &gt; * { scroll-snap-align: start; flex: 0 0 auto; }</code></pre>', 'Isaya Masika', 'published', '2026-11-13');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('svg-path-animation', 'Animate an SVG Path Without Shipping a Motion Library', 'svg-path-animation', 'SVG', 'stroke-dasharray is the only trick you need to draw an icon line by line. Here is the exact maths, plus how to make it replay on hover.', '<p>The “drawing” effect you see in good icon sets is not a Lottie file. It is one CSS property pair: <code>stroke-dasharray</code> and <code>stroke-dashoffset</code>.</p><h2>The mechanism</h2><p>Give a path a dash as long as the path itself, then shift the dash out of view. Animating the offset back to zero draws the line from start to end.</p><pre><code>.draw { stroke-dasharray: var(--len); stroke-dashoffset: var(--len); animation: draw 900ms ease-out forwards; } @keyframes draw { to { stroke-dashoffset: 0; } }</code></pre><h2>Where <code>--len</code> comes from</h2><p>Hardcoding <code>1000</code> works because a dash longer than the path still renders fully — but the animation then spends most of its duration doing nothing if the real length is 300. Measure it once:</p><pre><code>const path = document.querySelector("#arc"); const len = path.getTotalLength(); path.style.setProperty("--len", len);</code></pre><h2>Replay on hover</h2><pre><code>.icon:hover .draw { animation: none; stroke-dashoffset: var(--len); animation: draw 900ms ease-out forwards; }</code></pre><p>The <code>animation: none</code> line is the important half — without it, re-adding the same animation name does nothing.</p>', 'Isaya Masika', 'published', '2026-11-14');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('core-web-vitals-lcp', 'Fix Largest Contentful Paint Before You Add Another Dependency', 'core-web-vitals-lcp', 'Performance', 'LCP is usually three things: an unprioritised hero image, a blocking font, and a JavaScript bundle that hydrates before the paint.', '<p>Most “our site is slow” tickets resolve to one of three causes, and none of them is the framework. Measure first — everything below is guesswork until you have the number.</p><h2>Measure in the field, not the lab</h2><pre><code>new PerformanceObserver((list) =&gt; { for (const e of list.getEntries()) console.log(e.startTime, e.element); }).observe({ type: "largest-contentful-paint", buffered: true });</code></pre><p>Lab tools run on fast hardware with a warm cache. A 1.2s lab LCP is routinely 3.5s on a mid-range Android over 4G. Trust the field number.</p><h2>Cause 1 — the hero image is not prioritised</h2><pre><code>&lt;img src="/hero.webp" width="1600" height="900" fetchpriority="high" decoding="async" alt=""&gt;</code></pre><p>Without <code>fetchpriority="high"</code> the image competes with the JS bundle for bandwidth and loses. Convert to WebP/AVIF first: a 240KB JPEG is often 60KB as WebP, which is a bigger win than any code change.</p><h2>Cause 2 — the font blocks the first paint</h2><pre><code>@font-face { font-family: "Inter"; src: url("/inter.woff2") format("woff2"); font-display: swap; unicode-range: U+0000-00FF; }</code></pre><p><code>font-display: swap</code> lets text paint immediately in a fallback face. Pair it with a preload <strong>only for the one weight you actually use</strong>; preloading four weights is slower than not preloading at all.</p><h2>Cause 3 — hydration runs before the paint</h2><p>If the bundle is over ~200KB gzipped, split the route. A 1.2MB single chunk means the browser parses and executes before it can paint anything interactive:</p><pre><code>const Home = lazy(() =&gt; import("./SteaCodeHomeV2"));</code></pre><p>Then confirm the split happened — in the build output, the entry chunk should stay small and the feature chunk should carry the weight.</p>', 'Isaya Masika', 'published', '2026-11-15');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('container-queries-inline-size', 'Container Queries: Style a Component by Its Slot, Not the Viewport', 'container-queries-inline-size', 'CSS', 'A card in a 280px sidebar and the same card on a 1440px hero need different layouts. Container queries let one component answer that.', '<p>Media queries ask "how wide is the browser?". That is the wrong question for a component. A product card in a 280px sidebar and the same card in a 900px hero should not share a breakpoint.</p><h2>Declare a query container</h2><pre><code>.card-slot { container-type: inline-size; container-name: card; }</code></pre><p><code>inline-size</code> makes the element a query container measured on its inline axis. That is the whole setup.</p><h2>Query the container, not the screen</h2><pre><code>@container card (min-width: 420px) { .card { display: grid; grid-template-columns: 160px 1fr; gap: 20px; } } @container card (max-width: 419px) { .card { display: block; } }</code></pre><p>Now the layout follows the slot. Resize the sidebar and the card reflows without a resize listener.</p><h2>Units that make typography honest</h2><pre><code>.card__title { font-size: clamp(13px, 8.6cqi, 22px); }</code></pre><p><code>cqi</code> is one percent of the container''s inline size. This is exactly how the 3D book cards keep their covers readable at 390px.</p>', 'Isaya Masika', 'published', '2026-11-16');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('css-aspect-ratio', 'Replace the Padding-Top Hack With aspect-ratio', 'css-aspect-ratio', 'CSS', 'The 56.25% padding trick has a successor that is one property, works with flex, and does not break when you add a border.', '<p>For a decade the answer to "how do I make a box a 16:9 rectangle" was <code>padding-top: 56.25%</code> plus an absolutely positioned child. It works, and it is awful.</p><h2>The replacement</h2><pre><code>.thumb { aspect-ratio: 16 / 9; width: 100%; }</code></pre><p>One property. The height is derived from the width, content flows normally, and <code>border</code> is included in the box.</p><h2>With images, use the attributes too</h2><pre><code>&lt;img src="/cover.webp" width="800" height="1200" alt=""&gt;</code></pre><p>Always ship <code>width</code> and <code>height</code> attributes: the browser derives the ratio and reserves the box before the bytes arrive.</p><h2>Where it silently fails</h2><ul><li>Flex children with <code>align-items: stretch</code> — add <code>align-self: start</code>.</li><li>Grid tracks with a fixed height — use <code>auto</code> rows.</li><li>Parent <code>min-height</code> overrides the ratio.</li></ul>', 'Isaya Masika', 'published', '2026-11-17');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('css-clamp-fluid-type', 'Fluid Type with clamp(): A Scale That Does Not Break at 200% Zoom', 'css-clamp-fluid-type', 'CSS', 'One clamp() per heading replaces five media queries — if the min and max are in rem and the middle term only moves the middle.', '<p>Fluid typography is one line of <code>clamp()</code> per step. Done wrong it is an accessibility problem: text that only responds to viewport width ignores the user''s zoom setting.</p><h2>The safe formula</h2><pre><code>h1 { font-size: clamp(2rem, 5vw + 1rem, 3.5rem); }</code></pre><ul><li><strong>Minimum in <code>rem</code>.</strong> Respects browser base font size.</li><li><strong>Maximum in <code>rem</code>.</strong> Same reason at the other end.</li><li><strong>Only the middle term uses <code>vw</code>.</strong></li></ul><h2>The zoom trap</h2><p>At 200 percent zoom on a 1440px screen the effective viewport is 720px, so <code>vw</code> shrinks and the type with it. This is why the floor must be in <code>rem</code>.</p><pre><code>html { font-size: 100%; } h1 { font-size: clamp(1.75rem, 4vw + 0.6rem, 3.5rem); }</code></pre>', 'Isaya Masika', 'published', '2026-11-18');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('position-sticky-anatomy', 'Why position: sticky Quietly Does Nothing', 'position-sticky-anatomy', 'CSS', 'Sticky headers fail for exactly four reasons: a clipped ancestor, a missing offset, a self-scrolling parent, or a transform creating a new containing block.', '<p><code>position: sticky</code> is the only CSS feature that fails silently. Four causes cover almost every case.</p><h2>1. An ancestor clips overflow</h2><p>Any ancestor with <code>overflow: hidden</code>, <code>auto</code> or <code>scroll</code> becomes that scrollport. Fix the overflow on the ancestor instead of adding <code>position: sticky</code> to more elements.</p><h2>2. Missing or wrong offset</h2><pre><code>.topbar { position: sticky; top: 0; z-index: 40; }</code></pre><p>Without <code>top</code>, sticky has no threshold and does nothing.</p><h2>3. The parent is taller than the scroll container</h2><p>Sticky is constrained to its parent. Put the sticky element in a container that spans the section it should accompany.</p><h2>4. transform / filter / will-change create a containing block</h2><p>Any of those on an ancestor makes <code>position: fixed</code> behave like absolute and breaks sticky in subtle ways.</p>', 'Isaya Masika', 'published', '2026-11-19');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('dark-mode-semantic-tokens', 'Dark Mode Without Inverting: Semantic Tokens First', 'dark-mode-semantic-tokens', 'Design Systems', 'filter: invert(1) is a party trick that ruins images and brand colour. The durable approach is two layers: raw palette tokens, then semantic tokens.', '<p>Every dark mode attempt that starts with inverting the light theme ends in the same place: photographs turn negative, the gold accent becomes muddy purple.</p><h2>Two layers</h2><pre><code>:root { --grey-0: #ffffff; --grey-900: #111827; --gold-500: #f5b400; --surface: var(--grey-0); --text: var(--grey-900); --accent: var(--gold-500); } [data-theme="dark"] { --surface: #0b0f14; --text: #e5e7eb; --accent: #ffc43d; }</code></pre><p>Components only ever use the second layer: <code>background: var(--surface)</code>, <code>color: var(--text)</code>.</p><h2>Do not use pure black</h2><p><code>#000</code> next to <code>#fff</code> text produces halation. <code>#0b0f14</code> with <code>#e5e7eb</code> text reads calmer and keeps contrast above 12:1.</p><h2>Respect the OS, do not obey it blindly</h2><p>Three states: unset follows the OS, <code>light</code> and <code>dark</code> are explicit choices. Store the choice in <code>localStorage</code> and apply it before first paint.</p>', 'Isaya Masika', 'published', '2026-11-20');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-controlled-vs-uncontrolled', 'Controlled vs Uncontrolled Inputs: The Bug Is Usually a Missing onChange', 'react-controlled-vs-uncontrolled', 'React', 'value without onChange produces an input that cannot be typed into. defaultValue produces one React cannot read. Pick by who owns the state.', '<p>The most common React bug report reads "the input is frozen". Nine times out of ten the JSX is <code>&lt;input value={email} /&gt;</code> with no <code>onChange</code>.</p><h2>The two modes</h2><pre><code>// controlled: React owns the value &lt;input value={q} onChange={(e) =&gt; setQ(e.target.value)} /&gt; // uncontrolled: the DOM owns it &lt;input defaultValue="" ref={inputRef} /&gt;</code></pre><h2>When controlled is correct</h2><ul><li>Validation per keystroke.</li><li>Derived UI — a character counter, a preview.</li><li>Programmatic value rewriting.</li></ul><h2>When uncontrolled is correct</h2><ul><li>Large forms you only read on submit.</li><li>File inputs (cannot be controlled).</li><li>Third-party widget integration.</li></ul>', 'Isaya Masika', 'published', '2026-11-21');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('useeffect-dependencies', 'useEffect Dependencies: Stale Closures, Extra Runs, and the Ref Escape Hatch', 'useeffect-dependencies', 'React', 'A missing dependency gives you yesterday''s props. An extra one gives you an infinite loop. Both come from the same mistake.', '<p><code>useEffect</code> is hard because the dependency array compares by identity, and React hands you a new function or object on almost every render.</p><h2>Failure mode 1 — the missing dependency</h2><pre><code>useEffect(() =&gt; { fetch(''/api/blog?limit='' + limit); }, []); // limit is frozen forever</code></pre><h2>Failure mode 2 — the extra dependency</h2><pre><code>const options = { limit: 20 }; // new object each render useEffect(() =&gt; { fetchList(options); }, [options]); // infinite loop</code></pre><h2>The ref escape hatch</h2><pre><code>const cb = useRef(onAuthenticated); useEffect(() =&gt; { cb.current = onAuthenticated; }, [onAuthenticated]); useEffect(() =&gt; { fetchSession().then((email) =&gt; email &amp;&amp; cb.current({ email })); }, [open]);</code></pre>', 'Isaya Masika', 'published', '2026-11-22');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('custom-fetch-hook', 'A useFetch Hook That Handles Races, Aborts and Errors', 'custom-fetch-hook', 'React', 'The naive useEffect fetch breaks in three ways: two requests resolving out of order, a stale write after unmount, and an error swallowed into silence.', '<p>Copy-pasting <code>fetch(...).then(setData)</code> works until the user changes a filter twice quickly, then the older response lands second and wins.</p><h2>The hook</h2><pre><code>export function useFetch(url) { const [state, setState] = useState({ data: null, error: null, loading: !!url }); useEffect(() =&gt; { if (!url) return; const ctrl = new AbortController(); fetch(url, { signal: ctrl.signal }).then(async (res) =&gt; { const body = await res.json().catch(() =&gt; null); if (!res.ok) throw new Error(body?.error || ''Failed''); return body; }).then((data) =&gt; setState({ data, error: null, loading: false })).catch((err) =&gt; { if (err.name === ''AbortError'') return; setState({ data: null, error: err.message, loading: false }); }); return () =&gt; ctrl.abort(); }, [url]); return state; }</code></pre><p><code>AbortController</code> removes both the race and the write-after-unmount warning without a <code>dead</code> flag.</p>', 'Isaya Masika', 'published', '2026-11-23');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-error-boundaries', 'Error Boundaries: What They Catch and What Silently Slips Through', 'react-error-boundaries', 'React', 'An error boundary catches render errors, not rejected promises, not event handlers, not failed lazy imports at the boundary.', '<p>A single thrown error inside a component unmounts the whole tree and leaves a white screen. An error boundary turns that into a message and keeps the rest alive.</p><h2>Catch</h2><ul><li>Errors during render.</li><li>Lifecycle methods.</li><li>setState callbacks during render.</li></ul><h2>Slipped through</h2><ul><li>Rejected promises.</li><li>Event handlers.</li><li>Async callbacks and timers.</li></ul><h2>Minimal implementation</h2><pre><code>class Boundary extends React.Component { state = { error: null }; static getDerivedStateFromError(error) { return { error }; } render() { if (this.state.error) return &lt;div&gt;Something broke&lt;button onClick={() =&gt; this.setState({ error: null })}&gt;Try again&lt;/button&gt;&lt;/div&gt;; return this.props.children; } }</code></pre>', 'Isaya Masika', 'published', '2026-11-24');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-list-keys-reconciliation', 'List Keys Are Identity, Not an Index', 'react-list-keys-reconciliation', 'React', 'Using the array index as key works until something is removed — then every input below the deleted row loses its value.', '<p>The key warning in the console gets dismissed as pedantry. Then a row is deleted and the text the user typed two rows down disappears.</p><h2>What the key means</h2><p>React reconciles lists by key, not position. A matching key means "same element, update props". A different key means "unmount this, mount that".</p><pre><code>// index as key {rows.map((row, i) =&gt; &lt;Row key={i} data={row} /&gt;)}</code></pre><p>Delete row 2 and every subsequent row keeps its old key with new data. The row component does not remount, so its internal state stays attached to the wrong record.</p><pre><code>{rows.map((row) =&gt; &lt;Row key={row.id} data={row} /&gt;)}</code></pre><h2>The duplicate-key failure</h2><p>Duplicate keys do not throw; React silently reuses the first element, and later items update the wrong card.</p>', 'Isaya Masika', 'published', '2026-11-25');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('css-backdrop-filter-basics', 'How Do I Use backdrop-filter in CSS Without Breaking the Layout?', 'css-backdrop-filter-basics', 'CSS', 'backdrop-filter blurs whatever is behind an element, not the element itself. You need a translucent background on the element or the blur is invisible.', '<p>backdrop-filter is the property behind every glassmorphism demo, and the most common first attempt produces nothing at all. The element blurs what is painted behind it — if the element has an opaque background, you never see the effect.</p><h2>Direct Answer</h2><p>Set a semi-transparent background on the element, then apply backdrop-filter. Always ship the -webkit- prefix for older Safari. If any ancestor creates a containing block or clips overflow, the effect can silently vanish.</p><h2>Full Code Example</h2><pre><code>.panel { background: rgba(255, 255, 255, 0.5); backdrop-filter: blur(12px) saturate(150%); -webkit-backdrop-filter: blur(12px) saturate(150%); border: 1px solid rgba(255, 255, 255, 0.6); border-radius: 12px; padding: 20px; }</code></pre><h2>Why This Works</h2><p>The blur samples the pixels underneath the element''s box. A background alpha of 0.5 lets those blurred pixels show through while keeping text readable. saturate(150%) restores the colour the blur washes out. The border gives the edge a highlight so the panel reads as glass rather than fog.</p><h2>Common Mistakes</h2><ul><li>Using an opaque background — the blur still runs, you just cannot see it, and you pay the GPU cost for nothing.</li><li>Applying it to the element you want blurred instead of the element in front of it.</li><li>Stacking multiple blurred panels — one blurred surface per screen is the safe budget on low-end Android.</li><li>Forgetting the -webkit- prefix, which kills the effect on Safari before version 18.</li></ul><h2>Browser Support / Caveats</h2><p>Supported in every current browser; Firefox enabled it by default in 2022. On devices without GPU compositing it falls back to nothing — the panel just shows its translucent fill, which is why the fill must look acceptable on its own.</p><h2>Related Resources</h2><p>For a production glass treatment with hover states and dark-mode variants, see <a href="/blog/glassmorphism-button">the glassmorphism button guide</a> and the ready-made cards in the <a href="/components">component library</a>.</p>', 'Isaya Masika', 'published', '2026-11-26');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('glass-button-contrast-readability', 'How Do I Keep a Glass Button Readable on Any Background?', 'glass-button-contrast-readability', 'CSS', 'Raise the fill opacity before touching blur radius, keep a hairline border lighter than the fill, and test over the busiest image on the page.', '<p>A glass button that looks perfect over your hero gradient becomes illegible over a photograph. Translucency means the background is a variable you do not control, so the button has to defend itself.</p><h2>Direct Answer</h2><p>Keep the fill at 55 percent opacity or higher, give the label a strong text colour with a subtle text-shadow, and add an inset top shadow that fakes a bevel. Opacity is the free lever — blur is the expensive one, and more blur actually reduces contrast by smearing bright pixels into dark text.</p><h2>Full Code Example</h2><pre><code>.glass-btn { padding: 14px 26px; border-radius: 14px; font: 600 15px/1 system-ui, sans-serif; color: #111827; text-shadow: 0 1px 0 rgba(255, 255, 255, 0.6); background: rgba(255, 255, 255, 0.6); border: 1px solid rgba(255, 255, 255, 0.75); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); box-shadow: 0 10px 30px rgba(17, 24, 39, 0.12), inset 0 1px 0 rgba(255, 255, 255, 0.9); }</code></pre><h2>Why This Works</h2><p>Readability is contrast between glyph and local background. The 0.6 fill guarantees the button''s local background is mostly the fill, not the photo. The text-shadow adds a bright rim that separates the glyph from anything darker behind it. The inset shadow reads as a light source, which is what makes the brain parse the shape as a solid object.</p><h2>Common Mistakes</h2><ul><li>Cranking blur to 30px — the background averages to mid-grey and dark text dies on it.</li><li>Using white text on a white glass fill without a dark scrim behind the label.</li><li>Testing only over the hero image you designed for, not the user-uploaded one that ships later.</li><li>Forgetting the dark-theme variant: rgba(255,255,255,0.08) fill with #f9fafb text.</li></ul><h2>Browser Support / Caveats</h2><p>Where backdrop-filter is unsupported the button degrades to its fill colour — with the 0.6 fill above it still reads fine, which is the point of picking opacity first. Check contrast with a picker over the worst background, not the best.</p><h2>Related Resources</h2><p>The full hover and reduced-motion treatment is in <a href="/blog/glassmorphism-button">How to Create a Glassmorphism Button</a>, and a tested version ships in the <a href="/components">component library</a>.</p>', 'Isaya Masika', 'published', '2026-11-27');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('backdrop-filter-not-working', 'Why Is backdrop-filter Not Working on My Element?', 'backdrop-filter-not-working', 'CSS', 'Four causes cover nearly every case: opaque background, missing -webkit- prefix, an ancestor with overflow or transform, or nothing behind the element to blur.', '<p>backdrop-filter fails silently, which makes it one of the most searched CSS properties. The panel renders, there is just no blur. Four causes account for almost every report.</p><h2>Direct Answer</h2><p>First check the element''s background has alpha below 1. Then check every ancestor for overflow: hidden, transform, filter, or will-change — any of these changes what "behind the element" means. Finally confirm there is actually content behind the element; blurring a solid page background is invisible by definition.</p><h2>Full Code Example</h2><pre><code>/* broken: ancestor clips the backdrop */ .page { overflow-x: hidden; } /* sometimes kills it */ .card { transform: translateZ(0); } /* new containing block above the glass */ /* working structure */ .hero { position: relative; background: url("/hero.webp"); } .glass { position: absolute; inset: 20% 30%; background: rgba(255, 255, 255, 0.5); backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px); }</code></pre><h2>Why This Works</h2><p>The glass must be positioned over painted content inside the same stacking context the browser composites. transform on an ancestor creates a new containing block, and some engines then composite the ancestor separately, so the backdrop sample is empty. overflow: hidden on an ancestor clips the painted region the filter samples from.</p><h2>Common Mistakes</h2><ul><li>Testing on a white page — there is nothing to blur, so a working filter looks broken.</li><li>Dropping the -webkit- prefix and testing only in Chrome.</li><li>Putting the backdrop element inside a transformed carousel or parallax wrapper.</li><li>Expecting it to blur across an iframe boundary — it cannot.</li></ul><h2>Browser Support / Caveats</h2><p>Firefox needs no flags since version 103. Safari needs the prefix before 18. Chrome on low-end Android can disable the effect under memory pressure — always make the translucent fill acceptable as a fallback design.</p><h2>Related Resources</h2><p>The containing-block problem is the same one that breaks sticky positioning — see <a href="/blog/position-sticky-anatomy">Why position: sticky Quietly Does Nothing</a>. The basic recipe is in <a href="/blog/css-backdrop-filter-basics">backdrop-filter basics</a>.</p>', 'Isaya Masika', 'published', '2026-11-28');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('css-transition-properties-list', 'Why You Should Never Write transition: all in CSS', 'css-transition-properties-list', 'CSS', 'transition: all animates layout properties you did not mean to touch, fires on unrelated changes, and costs frames. List two or three properties instead.', '<p>transition: all is the CSS equivalent of SELECT *. It works in the demo and then animates width, padding and font-size in production because something unrelated changed a class.</p><h2>Direct Answer</h2><p>Name the exact properties you animate, keep the list to two or three, and prefer transform and opacity — the only two properties that stay on the compositor and never trigger layout. Under 260ms for hover feedback, under 400ms for anything else.</p><h2>Full Code Example</h2><pre><code>/* before: everything animates, including the padding your JS just toggled */ .card { transition: all 300ms ease; } /* after: only what you designed */ .card { transition: transform 180ms ease, box-shadow 180ms ease; } .card:hover { transform: translateY(-3px); box-shadow: 0 14px 34px rgba(17, 24, 39, 0.09); }</code></pre><h2>Why This Works</h2><p>transform and opacity are handled on the compositor thread, so the animation runs even while the main thread is busy parsing your bundle. box-shadow does trigger paint, which is acceptable on a single card but not on a grid of fifty. The named list also acts as documentation: anyone reading the rule knows exactly what moves.</p><h2>Common Mistakes</h2><ul><li>Animating width or height on hover — every frame triggers layout for the whole subtree.</li><li>transition: all on a component that also receives dynamic classes from JS, causing phantom animations.</li><li>Durations above 400ms on interactive feedback — it reads as lag, not polish.</li><li>No reduced-motion override, which turns a decorative lift into a vestibular trigger.</li></ul><h2>Browser Support / Caveats</h2><p>Transitions are universal; the performance difference between compositor and layout properties is not theoretical — on a mid-range phone an animating width drops a scroll to 20fps while transform holds 60.</p><h2>Related Resources</h2><p>Five hover treatments that follow this contract are in <a href="/blog/css-hover-effects">Five CSS Hover Effects That Do Not Feel Cheap</a>, and the reduced-motion wrapper is covered in <a href="/blog/prefers-reduced-motion-css">prefers-reduced-motion in CSS</a>.</p>', 'Isaya Masika', 'published', '2026-11-29');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('css-focus-visible-hover-states', 'How Do I Give Keyboard Users the Same Hover State as Mouse Users?', 'css-focus-visible-hover-states', 'CSS', 'Pair every :hover rule with :focus-visible. It shows focus rings only for keyboard navigation, so mouse users keep a clean UI and keyboard users keep orientation.', '<p>Every hover effect you ship is invisible to anyone navigating by Tab. If the hover is the only "this is clickable" cue, keyboard users are flying blind. The fix is one selector, not a redesign.</p><h2>Direct Answer</h2><p>Duplicate every :hover rule as :focus-visible with the same declarations. focus-visible matches only when the browser heuristics say the user is navigating by keyboard, so you do not get the ugly persistent ring after a mouse click that plain :focus gives you.</p><h2>Full Code Example</h2><pre><code>.magnetic { transition: transform 220ms cubic-bezier(.2, .8, .2, 1); } .magnetic:hover, .magnetic:focus-visible { transform: translateX(4px); } /* a real focus ring for keyboard users, none for mouse */ .magnetic:focus { outline: none; } .magnetic:focus-visible { outline: 2px solid #4f46e5; outline-offset: 2px; }</code></pre><h2>Why This Works</h2><p>:focus-visible was designed to solve the "outline appears on mouse click" complaint that made developers remove outlines entirely. Grouping :hover and :focus-visible with a comma means one source of truth — change the hover transform and the keyboard state follows automatically. The explicit outline restores what outline: none removed, but only in the keyboard case.</p><h2>Common Mistakes</h2><ul><li>outline: none with no replacement — an instant WCAG failure and a support ticket generator.</li><li>Using :focus instead of :focus-visible, then removing it because it looks wrong on click.</li><li>Grouping :hover with :focus-visible but forgetting the element is a div with no tabindex, so it can never receive focus.</li><li>Relying on colour alone for the focus state — add position or weight so it survives colour-blindness.</li></ul><h2>Browser Support / Caveats</h2><p>:focus-visible is in every current browser. Older Safari versions ignored it and matched nothing, which is a safe degradation — you just lose the keyboard cue there, same as before.</p><h2>Related Resources</h2><p>The hover effects this pairs with are in <a href="/blog/css-hover-effects">Five CSS Hover Effects That Do Not Feel Cheap</a>. Focusable, pre-tested buttons live in the <a href="/components">component library</a>.</p>', 'Isaya Masika', 'published', '2026-11-30');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('prefers-reduced-motion-css', 'How Do I Respect prefers-reduced-motion Without Deleting My Animations?', 'prefers-reduced-motion-css', 'CSS', 'Wrap the transform-based rules in a reduce query that kills motion but keeps state change. Opacity fades are usually acceptable; movement is not.', '<p>prefers-reduced-motion is an accessibility signal, not a preference for boring websites. Users who set it can get vertigo or nausea from parallax and sliding panels — but they still need state feedback like a hover colour change.</p><h2>Direct Answer</h2><p>Wrap every motion rule — transform, keyframe animation, scroll-behavior: smooth — in a media query that neutralises it. Keep instant state changes (background, opacity, border) because those carry information and cause no vestibular response. Do not remove the hover state, remove the movement.</p><h2>Full Code Example</h2><pre><code>.lift { transition: transform 160ms ease, box-shadow 160ms ease; } .lift:hover { transform: translateY(-3px); box-shadow: 0 14px 34px rgba(17, 24, 39, 0.09); } @media (prefers-reduced-motion: reduce) { .lift { transition: box-shadow 0ms; } .lift:hover { transform: none; } html { scroll-behavior: auto; } *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; } }</code></pre><h2>Why This Works</h2><p>The reduced block strips transform but keeps box-shadow, so the hover still visibly responds. The global animation override is the nuclear option for SVG draw effects and keyframe loops you cannot wrap individually — 0.01ms finishes the animation instantly, so end states still apply. scroll-behavior: auto stops smooth scrolling, a known vertigo trigger.</p><h2>Common Mistakes</h2><ul><li>Removing hover feedback entirely — the interface feels dead and users cannot tell what is interactive.</li><li>Only handling CSS and forgetting JS-driven animation (requestAnimationFrame loops need a matchMedia check).</li><li>Using transition: none, which also kills instant colour changes and makes buttons feel broken.</li><li>Testing by toggling the OS setting once — automate it in your visual tests or you will regress it.</li></ul><h2>Browser Support / Caveats</h2><p>The media query is supported everywhere current. In JS, use matchMedia("(prefers-reduced-motion: reduce)").matches and listen for the change event — users can flip the setting mid-session.</p><h2>Related Resources</h2><p>The lifts and tilts this wraps are in <a href="/blog/css-hover-effects">Five CSS Hover Effects That Do Not Feel Cheap</a>, and SVG draw animations are covered in <a href="/blog/svg-path-animation">Animate an SVG Path</a>.</p>', 'Isaya Masika', 'published', '2026-12-01');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('css-underline-animation-scalex', 'How Do I Animate a Link Underline Without Reflowing the Text?', 'css-underline-animation-scalex', 'CSS', 'Draw the underline on a ::after pseudo-element and animate transform: scaleX(0) to scaleX(1). Never animate width — it triggers layout on every frame.', '<p>The classic animated underline — grows from left on hover — is often built by animating width from 0 to 100%. That works and is wrong: every frame runs layout, and on a navigation bar of ten links the cost is visible.</p><h2>Direct Answer</h2><p>Create the underline at full width on a ::after pseudo-element, then animate transform between scaleX(0) and scaleX(1). transform runs on the compositor, the text never reflows, and you get transform-origin control over which end the line grows from.</p><h2>Full Code Example</h2><pre><code>.ink { position: relative; text-decoration: none; } .ink::after { content: ""; position: absolute; left: 0; bottom: -2px; width: 100%; height: 2px; background: currentColor; transform: scaleX(0); transform-origin: left; transition: transform 220ms cubic-bezier(.2, .8, .2, 1); } .ink:hover::after, .ink:focus-visible::after { transform: scaleX(1); }</code></pre><h2>Why This Works</h2><p>The pseudo-element is painted at full width but scaled to zero horizontally, so there is nothing to layout — only a GPU matrix change per frame. currentColor makes the underline inherit the link colour including its hover state, so you never maintain two colour values. transform-origin: left anchors the growth; switch to right for a reverse-wipe effect at zero extra cost.</p><h2>Common Mistakes</h2><ul><li>Animating width — forces synchronous layout per frame and stutters with other work on the main thread.</li><li>Forgetting position: relative on the link, so the absolute underline anchors to the wrong parent.</li><li>Using text-decoration: underline as the base and animating something else on top, producing a double line.</li><li>Scaling the text itself instead of a decoration — type blurs mid-transform.</li></ul><h2>Browser Support / Caveats</h2><p>Works in every browser that supports transforms, which is all of them. For a zero-CSS alternative on plain paragraphs, text-decoration-thickness and text-underline-offset now animate natively in Firefox and Chrome — but the scaleX pattern is still the portable one.</p><h2>Related Resources</h2><p>This is effect number two in <a href="/blog/css-hover-effects">Five CSS Hover Effects That Do Not Feel Cheap</a>. Pair it with the keyboard twin from <a href="/blog/css-focus-visible-hover-states">focus-visible hover states</a>.</p>', 'Isaya Masika', 'published', '2026-12-02');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-localstorage-json-parse-safely', 'How Do I Read JSON from localStorage Without Crashing the Render?', 'react-localstorage-json-parse-safely', 'React', 'Wrap JSON.parse in try/catch, validate the shape, and degrade to your signed-out or default state on any failure. Never parse inside render without a guard.', '<p>localStorage is user-editable and shared across tabs, so anything you wrote yesterday can be garbage today — a half-written value from a killed tab, a stale schema from two versions ago, or hand-edited junk. A single JSON.parse throw inside render white-screens the app.</p><h2>Direct Answer</h2><p>Read through one function that try/catches the parse, checks the parsed value has the fields you need, and returns null on any failure. Callers treat null as the empty state. Validate shape, not just parseability — {} parses fine and still breaks your avatar render.</p><h2>Full Code Example</h2><pre><code>const SEED_KEY = "stea_user"; function readSeed() { try { const raw = localStorage.getItem(SEED_KEY); if (!raw) return null; const p = JSON.parse(raw); return p &amp;&amp; typeof p.email === "string" ? { email: p.email, verified: false } : null; } catch { return null; } } function writeSeed(email) { try { localStorage.setItem(SEED_KEY, JSON.stringify({ email })); } catch { /* storage full or blocked: paint from memory instead */ } }</code></pre><h2>Why This Works</h2><p>getItem itself can throw in Safari private mode, so the try wraps the whole read. The typeof check is the schema validation — a string email is the only contract the rest of the app relies on. writeSeed catches quota errors, which happen in the wild on iOS more often than you would expect, and the app silently falls back to in-memory state.</p><h2>Common Mistakes</h2><ul><li>JSON.parse(localStorage.getItem(key)) inline in a component — one corrupt value kills the tree.</li><li>Trusting the shape because "only my code writes it" — extensions and other tabs write too.</li><li>Removing the key on parse failure without logging, which makes debugging a heisenbug.</li><li>Storing tokens next to the paint data, mixing the security and presentation layers.</li></ul><h2>Browser Support / Caveats</h2><p>Storage is per-origin and roughly 5MB. Private browsing in older Safari allowed reads but threw on writes — the pattern above survives both. Never store anything the server would not hand out publicly.</p><h2>Related Resources</h2><p>The full paint-versus-verify pattern is in <a href="/blog/react-localstorage-auth">React LocalStorage Auth</a>, and the server round-trip is in <a href="/blog/fetch-credentials-include-cookies">fetch with credentials</a>.</p>', 'Isaya Masika', 'published', '2026-12-03');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('fetch-credentials-include-cookies', 'Why Is My Cookie Not Sent with fetch? (credentials: ''include'')', 'fetch-credentials-include-cookies', 'React', 'fetch omits cookies on cross-origin requests by default. Pass credentials: ''include'' and fix the server CORS headers, or the session cookie never leaves the browser.', '<p>You log in, the Set-Cookie arrives, and the very next /api/auth/me comes back 401. The cookie exists — document.cookie might even show it — but fetch is not sending it. This is default behaviour, not a bug in your code.</p><h2>Direct Answer</h2><p>fetch uses credentials: "same-origin" by default, so cross-origin requests carry no cookies. Set credentials: "include" on the request, then on the server answer with Access-Control-Allow-Origin naming your exact origin (never *) and Access-Control-Allow-Credentials: true. Browsers reject wildcard origins on credentialed requests.</p><h2>Full Code Example</h2><pre><code>// client fetch("/api/auth/me", { credentials: "include" }).then(async (res) =&gt; { const body = await res.json().catch(() =&gt; null); if (!body?.email) { setUser(null); return; } setUser({ email: body.email, verified: true }); }); // server (Express) app.use(cors({ origin: "https://steacode.com", credentials: true }));</code></pre><h2>Why This Works</h2><p>The browser performs a credentialed request only when both sides opt in: the client asks with include, the server consents with the two headers. The preflight OPTIONS for non-simple requests also needs those headers or the real request never fires. res.json().catch guards against an empty 401 body, which would otherwise throw and mask the real status.</p><h2>Common Mistakes</h2><ul><li>Access-Control-Allow-Origin: * with credentials — the browser blocks the response and you see a CORS error that mentions neither.</li><li>Setting credentials on same-origin requests and debugging CORS headers that were never the problem.</li><li>Forgetting the SameSite attribute: cross-site cookies need SameSite=None; Secure, or Chrome drops them silently.</li><li>Testing with curl, which ignores CORS entirely, so the bug only appears in the browser.</li></ul><h2>Browser Support / Caveats</h2><p>credentials: "include" is universal. Safari''s Intelligent Tracking Prevention can block third-party cookies even with correct headers — if you control both origins, prefer same-site subdomains over cross-site cookie sharing.</p><h2>Related Resources</h2><p>This is the verification half of <a href="/blog/react-localstorage-auth">React LocalStorage Auth</a>; the safe JSON handling of the response is in <a href="/blog/react-localstorage-json-parse-safely">reading localStorage safely</a>.</p>', 'Isaya Masika', 'published', '2026-12-04');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-async-setstate-after-unmount', 'How Do I Avoid setState After a Component Unmounts?', 'react-async-setstate-after-unmount', 'React', 'Cancel the work in the effect cleanup — AbortController for fetch, a dead flag for everything else. React 18 removed the warning but the wasted write still costs you.', '<p>The old "Can''t perform a React state update on an unmounted component" warning disappeared in React 18, but the underlying problem did not: an async callback fires after the user navigated away and you pay for a state update nobody will see — or worse, a stale write lands on a remounted component.</p><h2>Direct Answer</h2><p>Return a cleanup function from useEffect and cancel the async work there. AbortController is the right tool for fetch; for timers, promises without abort support, and subscriptions, use a boolean flag checked before every setState.</p><h2>Full Code Example</h2><pre><code>useEffect(() =&gt; { const ctrl = new AbortController(); fetch("/api/auth/me", { credentials: "include", signal: ctrl.signal }) .then(async (res) =&gt; { const body = await res.json().catch(() =&gt; null); if (!body?.email) setUser(null); else setUser({ email: body.email, verified: true }); }) .catch((err) =&gt; { if (err.name === "AbortError") return; setError(err.message); }); return () =&gt; ctrl.abort(); }, []); // flag version, for anything without AbortSignal useEffect(() =&gt; { let dead = false; loadScript("/widget.js").then(() =&gt; { if (!dead) initWidget(); }); return () =&gt; { dead = true; }; }, []);</code></pre><h2>Why This Works</h2><p>The cleanup runs synchronously at unmount, before the component is gone. AbortController rejects the in-flight fetch immediately, the promise chain short-circuits, and no setState executes. The dead flag pattern covers the cases AbortController cannot reach — dynamic imports, third-party loaders, setTimeout chains.</p><h2>Common Mistakes</h2><ul><li>Catching AbortError and calling setError — always early-return on aborts.</li><li>Creating the AbortController inside the then callback, where cleanup cannot reach it.</li><li>Guarding only setState but not side effects like initWidget() that touch the DOM.</li><li>Fixing it with a global "mounted" ref in a context — the cleanup belongs next to the effect that started the work.</li></ul><h2>Browser Support / Caveats</h2><p>AbortController is universal. In React 18 StrictMode, effects mount-unmount-remount in development, which is exactly where you will catch a missing cleanup — do not silence that double-invoke, fix the cleanup.</p><h2>Related Resources</h2><p>A production hook wrapping this pattern is in <a href="/blog/custom-fetch-hook">A useFetch Hook That Handles Races, Aborts and Errors</a>, and the auth flow that uses it is in <a href="/blog/react-localstorage-auth">React LocalStorage Auth</a>.</p>', 'Isaya Masika', 'published', '2026-12-05');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('safe-area-inset-css-notch', 'How Do I Stop My Header Hiding Under the iPhone Notch?', 'safe-area-inset-css-notch', 'CSS', 'Set viewport-fit=cover in the meta tag, then pad the header with env(safe-area-inset-top). Without the meta change, the env() values are always zero.', '<p>On an iPhone in landscape your sticky header sits flush under the notch and half the logo disappears. The env(safe-area-inset-*) variables exist to fix this, but they all resolve to zero until you opt in with one meta attribute.</p><h2>Direct Answer</h2><p>Change the viewport meta to viewport-fit=cover so the page renders edge to edge, then add padding using env(safe-area-inset-top) — plus max() with your normal padding so the fallback on notch-free devices stays correct.</p><h2>Full Code Example</h2><pre><code>&lt;meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"&gt; &lt;style&gt; .topbar { position: sticky; top: 0; z-index: 40; padding-top: env(safe-area-inset-top); padding-left: max(16px, env(safe-area-inset-left)); padding-right: max(16px, env(safe-area-inset-right)); } &lt;/style&gt;</code></pre><h2>Why This Works</h2><p>viewport-fit=cover tells WebKit to paint under the sensor housing instead of letterboxing the page. Only then do the safe-area variables hold real values — on a notched iPhone in landscape, inset-left and inset-right jump to roughly 47px. max(16px, env(...)) means you never lose your baseline padding on devices reporting zero. The constant() function was the old syntax; env() replaced it and constant() only exists for iOS 11.0-11.2.</p><h2>Common Mistakes</h2><ul><li>Adding env() padding without viewport-fit=cover — the values stay zero and nothing changes.</li><li>Applying the inset as margin instead of padding — the background then stops at the notch and looks broken.</li><li>Hardcoding 44px — the inset differs between portrait, landscape and device generation.</li><li>Forgetting the bottom inset on fixed footers, where the home indicator overlaps your buttons.</li></ul><h2>Browser Support / Caveats</h2><p>env() and max() are supported in every current browser. Android devices with display cutouts expose the same variables. Test in landscape — that is where the side insets actually bite.</p><h2>Related Resources</h2><p>This is cause two of <a href="/blog/sticky-tailwind-navbar">the sticky navbar that survives mobile</a>; why sticky itself fails is in <a href="/blog/position-sticky-anatomy">the sticky anatomy post</a>.</p>', 'Isaya Masika', 'published', '2026-12-06');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('horizontal-scroll-strip-css', 'How Do I Build a Horizontal Scroll Strip That Hides Its Scrollbar?', 'horizontal-scroll-strip-css', 'CSS', 'flex with overflow-x: auto, scrollbar-width: none plus the ::-webkit-scrollbar rule, and scroll-snap so items land cleanly. Keep items at flex: 0 0 auto.', '<p>When a navbar has more items than a 375px screen fits, a horizontally scrolling strip beats a hamburger: everything stays visible, one thumb-swipe away. The trick is hiding the scrollbar without killing the scroll.</p><h2>Direct Answer</h2><p>Make the container a flex row with overflow-x: auto, hide the scrollbar with both scrollbar-width: none (Firefox/standard) and ::-webkit-scrollbar { display: none } (WebKit/Blink), and give children flex: 0 0 auto with scroll-snap-align: start so they do not shrink and they stop on item boundaries.</p><h2>Full Code Example</h2><pre><code>.nav-strip { display: flex; gap: 4px; overflow-x: auto; scrollbar-width: none; scroll-snap-type: x mandatory; -webkit-overflow-scrolling: touch; } .nav-strip::-webkit-scrollbar { display: none; } .nav-strip &gt; * { scroll-snap-align: start; flex: 0 0 auto; }</code></pre><h2>Why This Works</h2><p>flex: 0 0 auto is the line everyone misses — without it, flex items shrink below their content width and the strip never overflows, so nothing scrolls. scroll-snap-type: x mandatory makes each swipe settle on an item edge instead of a half-clipped label. The two scrollbar rules are both required; each engine only understands one.</p><h2>Common Mistakes</h2><ul><li>Hiding the scrollbar but leaving overflow-x: hidden — now the extra items are unreachable.</li><li>Letting items shrink (the flex default) so labels wrap into two lines instead of scrolling.</li><li>scroll-snap-type: x mandatory with margins on children — snap points land inside the margin and clip text; use gap instead.</li><li>No visual affordance that more items exist — a fade gradient on the trailing edge fixes this.</li></ul><h2>Browser Support / Caveats</h2><p>scroll-snap and scrollbar-width are universal; -webkit-overflow-scrolling is legacy iOS and harmless. Hidden scrollbars still scroll with Shift+wheel and keyboard focus — keep focus outlines visible for accessibility.</p><h2>Related Resources</h2><p>This strip is option two in <a href="/blog/sticky-tailwind-navbar">A Sticky Navbar That Survives Mobile</a>. The icons that keep labels compact at small widths are in the <a href="/icons">icon library</a>.</p>', 'Isaya Masika', 'published', '2026-12-07');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('svg-gettotallength-path-length', 'How Do I Get the Exact Length of an SVG Path for a Draw Animation?', 'svg-gettotallength-path-length', 'SVG', 'Call getTotalLength() on the path element, store it in a CSS custom property, and use it for both stroke-dasharray and the starting dashoffset.', '<p>Every SVG line-drawing tutorial hardcodes stroke-dasharray: 1000. It works because an over-long dash still covers the path — but the animation timing is then fiction: if the real path is 300 units, 70 percent of your 900ms animation moves an invisible dash and the line appears to pause.</p><h2>Direct Answer</h2><p>Measure the path once with getTotalLength() and inject the result as a custom property. The CSS then references the real number for both the dash and the starting offset, so the draw runs exactly the path''s length in exactly the declared duration.</p><h2>Full Code Example</h2><pre><code>const path = document.querySelector("#arc"); const len = path.getTotalLength(); path.style.setProperty("--len", String(len));</code></pre><pre><code>.draw { stroke-dasharray: var(--len); stroke-dashoffset: var(--len); animation: draw 900ms ease-out forwards; } @keyframes draw { to { stroke-dashoffset: 0; } }</code></pre><h2>Why This Works</h2><p>stroke-dasharray: L makes one dash exactly the path length, followed by an equal gap. stroke-dashoffset: L shifts that dash fully into the gap — the path looks empty. Animating the offset to zero slides the dash along the path, and because both numbers equal the true length, the easing curve maps honestly onto drawing speed. The forwards fill keeps the end state after the animation finishes.</p><h2>Common Mistakes</h2><ul><li>Hardcoding 1000 and wondering why the draw "hangs" at the start or end.</li><li>Calling getTotalLength() before the SVG is in the DOM — it throws or returns 0 on detached nodes.</li><li>Animating a path that is display: none at measure time; the geometry API returns 0.</li><li>Using a percentage dasharray on the keyframes — dashoffset percentages are relative to path length but mixing units between dasharray and offset produces gaps.</li></ul><h2>Browser Support / Caveats</h2><p>getTotalLength() is on SVGGeometryElement in every browser and works on path, circle, rect, line and polyline. Text elements do not have it — convert lettering to outlines first. The measurement costs microseconds; do it once at mount, not per animation frame.</p><h2>Related Resources</h2><p>The full effect, including hover replay, is in <a href="/blog/svg-path-animation">Animate an SVG Path Without Shipping a Motion Library</a>. Icons tuned for this treatment are in the <a href="/icons">icon library</a>.</p>', 'Isaya Masika', 'published', '2026-12-08');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('svg-replay-css-animation-hover', 'How Do I Restart a CSS Animation on Hover Without It Ignoring Me?', 'svg-replay-css-animation-hover', 'SVG', 'Set animation: none first, reset the state, then re-add the animation. Re-assigning the same animation name alone does nothing — the browser sees no change.', '<p>You want the icon to redraw every time the user hovers it, so you write .icon:hover .draw { animation: draw 900ms; } — and nothing happens after the first run. The animation already completed; assigning the same name again is not a change the browser reacts to.</p><h2>Direct Answer</h2><p>In the hover rule, first set animation: none and restore the starting stroke-dashoffset, then re-declare the animation. The none forces the animation to be removed and re-added in the same style flush, which restarts it from zero.</p><h2>Full Code Example</h2><pre><code>.draw { stroke-dasharray: var(--len); stroke-dashoffset: var(--len); animation: draw 900ms ease-out forwards; } @keyframes draw { to { stroke-dashoffset: 0; } } .icon:hover .draw { animation: none; stroke-dashoffset: var(--len); animation: draw 900ms ease-out forwards; }</code></pre><h2>Why This Works</h2><p>CSS animations restart when the computed animation-name list changes. none then draw within one declaration block still serialises to a name change because the none resets the running animation before the second declaration re-adds it. Resetting stroke-dashoffset to the path length restores the "empty" starting state, so the redraw begins from a blank icon instead of a finished one.</p><h2>Common Mistakes</h2><ul><li>Re-declaring only animation: draw — identical computed value, no restart.</li><li>Forgetting the forwards fill on the base rule, so the icon snaps to invisible when the animation ends.</li><li>Restarting on hover with no pointer leave handling — moving the mouse across rapidly retriggers mid-draw; add a short transition on the offset as a buffer if that bothers you.</li><li>Doing this on a :hover that also moves the element, so the pointer leaves mid-animation and cancels your own trigger.</li></ul><h2>Browser Support / Caveats</h2><p>The two-declaration restart works in every engine. For programmatic restarts, element.getAnimations() plus cancel()/play() is cleaner than toggling classes with a reflow read in between.</p><h2>Related Resources</h2><p>The base draw mechanism and where --len comes from are in <a href="/blog/svg-path-animation">Animate an SVG Path</a> and <a href="/blog/svg-gettotallength-path-length">measuring path length</a>.</p>', 'Isaya Masika', 'published', '2026-12-09');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('measure-lcp-performanceobserver', 'How Do I Measure LCP in the Browser with PerformanceObserver?', 'measure-lcp-performanceobserver', 'Performance', 'Observe the largest-contentful-paint entry type with buffered: true. The last candidate before user input is your LCP — log e.startTime and e.element.', '<p>Lighthouse gives you an LCP number on your MacBook with a warm cache. Your users get 3.5 seconds on a mid-range Android over 4G. If you optimise against the lab number you will fix the wrong thing — measure in the field.</p><h2>Direct Answer</h2><p>Create a PerformanceObserver for type "largest-contentful-paint" with buffered: true. The browser emits a new candidate every time something larger paints; the final one before the first user interaction is the official LCP. entry.startTime is milliseconds since navigation start, entry.element is the actual DOM node.</p><h2>Full Code Example</h2><pre><code>let lcp; new PerformanceObserver((list) =&gt; { for (const e of list.getEntries()) { lcp = e; console.log(e.startTime, e.element); } }).observe({ type: "largest-contentful-paint", buffered: true }); addEventListener("visibilitychange", () =&gt; { if (document.visibilityState === "hidden" &amp;&amp; lcp) { navigator.sendBeacon("/metrics", JSON.stringify({ lcp: lcp.startTime, el: lcp.element?.tagName })); } });</code></pre><h2>Why This Works</h2><p>buffered: true replays entries that happened before your script ran, so a late-loading analytics bundle still sees the paint. LCP candidates keep updating as larger elements appear, which is why you keep overwriting lcp and only report on visibilitychange to hidden — the moment the user leaves, the value is final. sendBeacon survives page unload, where fetch does not.</p><h2>Common Mistakes</h2><ul><li>Reporting on the first entry — that is usually a tiny text node, not the hero.</li><li>Forgetting buffered: true and missing paints that happened during script load.</li><li>Logging e.element for an image and seeing null in cross-origin iframes — guard with optional chaining.</li><li>Comparing lab LCP to field LCP as if they measure the same thing.</li></ul><h2>Browser Support / Caveats</h2><p>The entry type is Chrome/Edge/Opera; Safari and Firefox do not emit it, so treat missing data as a segment, not an error. For production, web-vitals onCLS/onLCP wrap all of this including the edge cases.</p><h2>Related Resources</h2><p>What to do with the number is in <a href="/blog/core-web-vitals-lcp">Fix Largest Contentful Paint</a>, and the usual first fix is <a href="/blog/fetchpriority-hero-image">prioritising the hero image</a>.</p>', 'Isaya Masika', 'published', '2026-12-10');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('fetchpriority-hero-image', 'How Do I Tell the Browser My Hero Image Is More Important Than the Bundle?', 'fetchpriority-hero-image', 'Performance', 'Add fetchpriority=''high'' to the img, set width and height, and use decoding=''async''. Without it the image queues behind your JavaScript and loses.', '<p>The hero image is your LCP element and the browser treats it as background noise. Images discovered in the body start at low priority; your render-blocking bundle and fonts go first. fetchpriority is the one-attribute fix.</p><h2>Direct Answer</h2><p>Put fetchpriority="high" on the LCP img, keep width and height attributes so the box is reserved before bytes arrive, and add decoding="async" so decoding does not block the main thread. Do not add lazy to the hero — that is the single most common self-inflicted LCP bug.</p><h2>Full Code Example</h2><pre><code>&lt;img src="/hero.webp" width="1600" height="900" fetchpriority="high" decoding="async" alt=""&gt; &lt;!-- everything below the fold gets the opposite treatment --&gt; &lt;img src="/card-1.webp" width="400" height="300" loading="lazy" decoding="async" alt=""&gt;</code></pre><h2>Why This Works</h2><p>fetchpriority overrides the network scheduler''s guess: the hero now competes with the JS bundle instead of queueing after it. The width/height pair lets the browser compute the aspect ratio and reserve layout space, killing the CLS that usually accompanies a fast LCP. Converting the asset matters more than any attribute — a 240KB JPEG is often 60KB as WebP.</p><h2>Common Mistakes</h2><ul><li>loading="lazy" on the hero — Chrome even warns about this in DevTools.</li><li>fetchpriority="high" on five images — if everything is high priority, nothing is.</li><li>Using a CSS background for the hero; background-image has no fetchpriority and is discovered late — use a real img.</li><li>Preloading the hero and also setting fetchpriority — pick one; the preload already wins.</li></ul><h2>Browser Support / Caveats</h2><p>fetchpriority is supported in Chrome, Edge, Safari and Firefox (since 132); unsupported engines ignore the attribute harmlessly. Verify in the Network panel: the hero should show High priority and start before the deferred scripts.</p><h2>Related Resources</h2><p>This is cause one in <a href="/blog/core-web-vitals-lcp">Fix Largest Contentful Paint Before You Add Another Dependency</a>; why width and height matter is in <a href="/blog/css-aspect-ratio">the aspect-ratio post</a>.</p>', 'Isaya Masika', 'published', '2026-12-11');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('font-display-swap-preload', 'How Do I Stop Web Fonts from Blocking the First Paint?', 'font-display-swap-preload', 'Performance', 'font-display: swap paints text immediately in a fallback face. Preload only the one weight you actually use — preloading four weights is slower than none.', '<p>A web font without a display strategy blocks text rendering for up to three seconds on a cold connection. Your LCP element is often a headline, so the font decision is an LCP decision.</p><h2>Direct Answer</h2><p>Add font-display: swap to every @font-face and serve woff2 only. Text paints instantly in the fallback and swaps when the real face arrives. If the swap flash bothers you, preload exactly one file — the weight used above the fold — with crossorigin, because font fetches are always CORS-mode.</p><h2>Full Code Example</h2><pre><code>&lt;link rel="preload" href="/inter-600.woff2" as="font" type="font/woff2" crossorigin&gt; &lt;style&gt; @font-face { font-family: "Inter"; src: url("/inter-600.woff2") format("woff2"); font-weight: 600; font-display: swap; unicode-range: U+0000-00FF; } body { font-family: "Inter", system-ui, -apple-system, sans-serif; } &lt;/style&gt;</code></pre><h2>Why This Works</h2><p>swap gives the font a zero-second block period and an infinite swap period — text never waits. unicode-range limits the download to Latin glyphs, so the file is smaller and the browser skips it entirely on pages without matching characters. The preload promotes the one critical weight to high priority; system-ui in the stack makes the fallback metrics close enough that the swap does not reflow dramatically.</p><h2>Common Mistakes</h2><ul><li>Preloading four weights — each preload competes with the hero image and CSS, so total time gets worse than with no preload.</li><li>Forgetting crossorigin on the preload — the font downloads twice, once for the preload and once for the CSS request.</li><li>Using font-display: block for "brand consistency" — that is invisible text on slow connections.</li><li>Serving ttf or otf; woff2 is roughly 30 percent smaller and universal.</li></ul><h2>Browser Support / Caveats</h2><p>font-display is universal. For near-zero swap shift, look at size-adjust and ascent-override to match fallback metrics — supported in Chrome, Edge and Firefox, ignored elsewhere.</p><h2>Related Resources</h2><p>This is cause two in <a href="/blog/core-web-vitals-lcp">Fix Largest Contentful Paint</a>; measure the result with <a href="/blog/measure-lcp-performanceobserver">PerformanceObserver</a>.</p>', 'Isaya Masika', 'published', '2026-12-12');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-lazy-route-splitting', 'How Do I Code-Split a React Route with lazy() and Suspense?', 'react-lazy-route-splitting', 'React', 'Wrap the page in React.lazy with a dynamic import, render it inside Suspense with a real fallback, and confirm the split in the build output.', '<p>A 1.2MB single chunk means the browser parses and executes everything before it can paint anything interactive. Route-level splitting is the highest-leverage bundle fix because users on page A never pay for page B''s code.</p><h2>Direct Answer</h2><p>Replace the static import of the page component with lazy(() =&gt; import(...)) and render the route inside a Suspense boundary. The bundler moves the page and everything only it imports into a separate chunk, fetched on first navigation.</p><h2>Full Code Example</h2><pre><code>import { lazy, Suspense } from "react"; const Home = lazy(() =&gt; import("./SteaCodeHomeV2")); const Library = lazy(() =&gt; import("./LibraryPage")); function App() { return ( &lt;Suspense fallback={&lt;div className="route-skeleton" /&gt;}&gt; &lt;Routes&gt; &lt;Route path="/" element={&lt;Home /&gt;} /&gt; &lt;Route path="/library" element={&lt;Library /&gt;} /&gt; &lt;/Routes&gt; &lt;/Suspense&gt; ); }</code></pre><h2>Why This Works</h2><p>The dynamic import is the bundler''s split point — Rollup, esbuild and webpack all emit a separate chunk per dynamic import and wire up the loading automatically. Suspense catches the pending state of the lazy component and shows the fallback. One boundary around the Routes means a single skeleton design instead of a spinner per page.</p><h2>Common Mistakes</h2><ul><li>Importing the lazy component statically somewhere else — the chunk collapses back into the entry and you split nothing.</li><li>A blank fallback; users on slow networks see a white screen and assume the site broke.</li><li>Splitting every component instead of every route — dozens of tiny chunks cost more in requests than they save in bytes.</li><li>Never checking the build output — the entry chunk should stay small and the feature chunk should carry the weight.</li></ul><h2>Browser Support / Caveats</h2><p>Dynamic import is native in every current browser. Failed chunk loads (a deploy mid-session) reject the import — catch that with an error boundary and offer a reload, because lazy failures are render errors.</p><h2>Related Resources</h2><p>This is cause three in <a href="/blog/core-web-vitals-lcp">Fix Largest Contentful Paint</a>. The boundary for failed chunks is in <a href="/blog/react-error-boundaries">Error Boundaries</a>.</p>', 'Isaya Masika', 'published', '2026-12-13');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('container-type-inline-size-setup', 'How Do I Set Up a Container Query in Plain CSS?', 'container-type-inline-size-setup', 'CSS', 'Declare container-type: inline-size on the parent, then write @container rules against its width. The component inside styles itself by its slot, not the viewport.', '<p>Media queries answer "how wide is the browser". A reusable component needs "how wide is my slot" — a card in a 280px sidebar and the same card in a 900px hero should not share a breakpoint. Container queries close that gap.</p><h2>Direct Answer</h2><p>Put container-type: inline-size on the wrapper that owns the width, optionally name it, then write @container (min-width: ...) rules for the children. That is the entire API — no JavaScript, no resize listener.</p><h2>Full Code Example</h2><pre><code>.card-slot { container-type: inline-size; container-name: card; } .card { display: block; } @container card (min-width: 420px) { .card { display: grid; grid-template-columns: 160px 1fr; gap: 20px; } }</code></pre><h2>Why This Works</h2><p>inline-size makes the wrapper a query container measured on its inline axis — its height stays content-driven, which avoids the circularity of querying your own size. The name scopes the query, so nested containers never cross-match: @container card only ever sees the nearest ancestor named card. Resize the sidebar and the card reflows instantly, with zero JS on the main thread.</p><h2>Common Mistakes</h2><ul><li>Putting container-type on the component you are styling — an element cannot query its own width, only an ancestor''s.</li><li>container-type: size when you only need width — size also queries height and forces the container to be sized independently, collapsing empty parents to zero.</li><li>Querying without a name in a page with multiple containers and hitting the wrong ancestor.</li><li>Expecting it to work inside display: contents wrappers — there is no box to measure.</li></ul><h2>Browser Support / Caveats</h2><p>Supported in Chrome, Edge, Safari and Firefox since 2023. There is no graceful in-browser fallback syntax, so for legacy support ship the media-query layout as the base and layer @container on top.</p><h2>Related Resources</h2><p>The full pattern is in <a href="/blog/container-queries-inline-size">Container Queries: Style a Component by Its Slot</a>, and the typography half is in <a href="/blog/container-query-units-cqi">container query units</a>.</p>', 'Isaya Masika', 'published', '2026-12-14');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('container-query-units-cqi', 'What Are cqi, cqw and Container Query Units, and When Should I Use Them?', 'container-query-units-cqi', 'CSS', 'cqi is one percent of the container''s inline size. Use it in clamp() for component typography: font-size: clamp(13px, 8.6cqi, 22px) scales with the slot.', '<p>vw scales type with the viewport, which breaks the moment a component lives in a sidebar. Container query units scale with the component''s own slot — the unit vw always should have been for component work.</p><h2>Direct Answer</h2><p>cqi is one percent of the query container''s inline size; cqw is the same for small-viewport-agnostic width, cqb for block axis. Use cqi as the fluid middle term of a clamp() with rem floor and ceiling, so type scales with the card and still respects user zoom.</p><h2>Full Code Example</h2><pre><code>.card-slot { container-type: inline-size; } .card__title { font-size: clamp(13px, 8.6cqi, 22px); line-height: 1.2; } .card__meta { font-size: clamp(11px, 4cqi, 13px); }</code></pre><h2>Why This Works</h2><p>At a 256px sidebar, 8.6cqi is 22px clamped to the 13px floor — wait, no: 8.6 percent of 256 is 22px, so the title hits its ceiling exactly when the card is wide enough to carry it. At 150px the middle term is 12.9px and the 13px floor takes over. This is exactly how dense card grids keep covers readable at 390px viewports without a single media query.</p><h2>Common Mistakes</h2><ul><li>Using cqi without a declared container ancestor — the unit falls back to the small viewport size, which silently works in testing and breaks in a grid.</li><li>A pure cqi font-size with no clamp — at a 1200px container your title becomes 103px.</li><li>Mixing vw and cqi in one clamp; the two axes disagree and the middle term stops being monotonic.</li><li>Using cqi for margins that must align across containers — percentage-of-different-boxes never lines up.</li></ul><h2>Browser Support / Caveats</h2><p>Container units shipped with container queries in 2023 across all engines. cqmin and cqmax resolve against the smaller or larger axis — handy for square-ish components, noise for everything else.</p><h2>Related Resources</h2><p>The setup these units depend on is in <a href="/blog/container-queries-inline-size">Container Queries</a>, and the clamp formula rationale is in <a href="/blog/css-clamp-fluid-type">Fluid Type with clamp()</a>.</p>', 'Isaya Masika', 'published', '2026-12-15');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('aspect-ratio-flex-grid-fails', 'Why Does aspect-ratio Stop Working Inside Flexbox and Grid?', 'aspect-ratio-flex-grid-fails', 'CSS', 'aspect-ratio loses to three layout defaults: flex align-items: stretch, grid rows with fixed heights, and a parent min-height that wins over the ratio.', '<p>You add aspect-ratio: 16 / 9, the box renders square — or tall — and the property looks broken. It is not. aspect-ratio is a weak input to the sizing algorithm: it only applies when the box has a free axis to size, and flexbox and grid love to fix both axes for you.</p><h2>Direct Answer</h2><p>Inside flex, add align-self: start (or change the container''s align-items) so the cross axis is free. Inside grid, keep rows auto so the track can grow from the ratio. Remove any parent min-height or height that overrides the derived size. One free axis plus width is the whole recipe.</p><h2>Full Code Example</h2><pre><code>/* flex: stretch fixes the height, ratio is ignored */ .row { display: flex; } .thumb { aspect-ratio: 16 / 9; width: 240px; } /* broken: height comes from the tallest sibling */ /* fixed: let the item size its own cross axis */ .row { display: flex; align-items: flex-start; } /* or .thumb { align-self: start; } */ /* grid: fixed track height beats the ratio */ .grid { display: grid; grid-template-rows: auto; /* not 200px */ }</code></pre><h2>Why This Works</h2><p>aspect-ratio computes one axis from the other during layout. align-items: stretch — the flex default — sets the cross size from the line, so the ratio has no free axis to influence and silently loses. A fixed grid row does the same. auto rows and align-self: start return the axis to content sizing, which is when the ratio is consulted.</p><h2>Common Mistakes</h2><ul><li>Debugging for an hour when align-self: start is the entire fix.</li><li>Putting height: 100% on the element itself — same failure from the other direction.</li><li>Combining aspect-ratio with max-height and being surprised the max wins.</li><li>Expecting the ratio to survive object-fit: none on an img with both dimensions set in CSS.</li></ul><h2>Browser Support / Caveats</h2><p>aspect-ratio is universal since 2021. For images, prefer the width/height attributes — the browser derives the ratio from the attribute map before CSS even loads, which also prevents layout shift.</p><h2>Related Resources</h2><p>The base property is in <a href="/blog/css-aspect-ratio">Replace the Padding-Top Hack With aspect-ratio</a>, and the image attribute pattern is in <a href="/blog/fetchpriority-hero-image">prioritising the hero image</a>.</p>', 'Isaya Masika', 'published', '2026-12-16');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('fluid-type-200-percent-zoom', 'Why Does My Fluid Typography Shrink When Users Zoom to 200 Percent?', 'fluid-type-200-percent-zoom', 'CSS', 'Zoom shrinks the CSS viewport, so a pure vw font-size gets smaller as the user zooms in — the opposite of what they asked for. Floor the clamp in rem.', '<p>Fluid type built on a bare vw unit has a nasty accessibility failure: at 200 percent browser zoom the effective viewport is half as wide, vw halves, and your heading gets smaller while the user is asking for bigger text. WCAG 1.4.4 requires text to survive 200 percent zoom, and a vw-only size fails it.</p><h2>Direct Answer</h2><p>Never use vw as the whole value. Use clamp() with the minimum and maximum in rem and only the middle term mixing vw with rem. The rem floor guarantees zoom always increases the rendered size, because rem scales with the browser''s base font and zoom factor.</p><h2>Full Code Example</h2><pre><code>/* broken: at 200% zoom on a 1440px screen, vw halves and type shrinks */ h1 { font-size: 4vw; } /* fixed: floor and ceiling in rem, only the slope uses vw */ h1 { font-size: clamp(1.75rem, 4vw + 0.6rem, 3.5rem); } html { font-size: 100%; }</code></pre><h2>Why This Works</h2><p>Zoom multiplies rem-derived sizes directly — 1.75rem at 200 percent zoom renders at exactly double the px. vw is computed from the zoomed viewport''s CSS width, which shrinks under zoom. By clamping, the rem floor takes over precisely when vw collapses, so the rendered size never drops below the zoom-scaled minimum. html { font-size: 100% } keeps rem honest against users who raise their default font size in settings.</p><h2>Common Mistakes</h2><ul><li>Testing zoom with the browser''s pinch zoom on mobile — that is visual zoom and scales everything; the failure shows with desktop page zoom.</li><li>A px floor in clamp, which ignores the user''s base font size preference.</li><li>Setting html font-size in px, which breaks every rem in the stylesheet under user settings.</li><li>Checking 200 percent on a 4K monitor, where the zoomed viewport is still enormous and vw never hits the floor.</li></ul><h2>Browser Support / Caveats</h2><p>clamp() is universal. The cleanest test: 1280px window, 200 percent zoom, and confirm the h1 measures at least double its unzoomed px size.</p><h2>Related Resources</h2><p>The full scale formula is in <a href="/blog/css-clamp-fluid-type">Fluid Type with clamp()</a>; for component-scoped fluid type see <a href="/blog/container-query-units-cqi">container query units</a>.</p>', 'Isaya Masika', 'published', '2026-12-17');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('tailwind-safe-area-insets', 'How Do I Use Safe-Area Insets in Tailwind CSS?', 'tailwind-safe-area-insets', 'Tailwind', 'Tailwind has no built-in safe-area utilities — use arbitrary values like pt-[env(safe-area-inset-top)] or pl-[max(16px,env(safe-area-inset-left))], plus viewport-fit=cover.', '<p>Tailwind''s spacing scale stops at 96 and knows nothing about the iPhone notch. The env() variables still work — you just have to write them yourself with arbitrary values, and the same viewport-fit=cover requirement from raw CSS applies.</p><h2>Direct Answer</h2><p>Set viewport-fit=cover in your viewport meta, then use arbitrary-value utilities: pt-[env(safe-area-inset-top)] on the sticky header and pb-[env(safe-area-inset-bottom)] on a fixed footer. Where you need a minimum, embed max() inside the bracket and use underscores for spaces.</p><h2>Full Code Example</h2><pre><code>&lt;meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"&gt; &lt;header class="sticky top-0 z-40 pt-[env(safe-area-inset-top)] pl-[max(1rem,env(safe-area-inset-left))] pr-[max(1rem,env(safe-area-inset-right))] bg-white/80 backdrop-blur"&gt; &lt;nav&gt;...&lt;/nav&gt; &lt;/header&gt; &lt;footer class="fixed bottom-0 inset-x-0 pb-[env(safe-area-inset-bottom)]"&gt; ... &lt;/footer&gt;</code></pre><h2>Why This Works</h2><p>Tailwind compiles pt-[env(safe-area-inset-top)] verbatim to padding-top: env(safe-area-inset-top). Underscores inside brackets become spaces, which is why the max() expression is written max(1rem,env(...)). If you use the values in more than two places, extend the theme instead: spacing: { "safe-t": "env(safe-area-inset-top)" } gives you pt-safe-t and keeps the markup readable.</p><h2>Common Mistakes</h2><ul><li>Spaces instead of underscores inside arbitrary values — the class silently fails to generate.</li><li>Skipping viewport-fit=cover, so every env() resolves to zero and the utilities appear broken.</li><li>Using margin instead of padding — the header background then stops short of the notch.</li><li>Adding the utilities to Tailwind''s safelist unnecessarily; arbitrary values in markup are picked up by the content scan like any other class.</li></ul><h2>Browser Support / Caveats</h2><p>The utilities are just CSS — support equals env() support, which is universal. In Tailwind v4 the same arbitrary syntax works; theme extension moved to the CSS-first @theme block but the markup classes are unchanged.</p><h2>Related Resources</h2><p>The underlying CSS mechanics are in <a href="/blog/safe-area-inset-css-notch">stopping the notch overlap</a>, and the full mobile header is in <a href="/blog/sticky-tailwind-navbar">A Sticky Navbar That Survives Mobile</a>.</p>', 'Isaya Masika', 'published', '2026-12-18');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('sticky-parent-container-height', 'Why Does My Sticky Element Stop Sticking Halfway Down the Page?', 'sticky-parent-container-height', 'CSS', 'Sticky is constrained to its parent''s box. If the parent ends, the sticky element scrolls away with it — stretch the parent to the full section height.', '<p>The sidebar sticks for the first 600px and then scrolls away with the rest of the page, as if the stickiness ran out. It did — sticky elements can only move within their parent''s box, and your parent ended.</p><h2>Direct Answer</h2><p>Make the sticky element''s parent span the full height of the section the element should accompany. In a two-column layout that means the column wrapper gets height: 100% (or stretch via grid/flex defaults), not height: fit-content — and the sticky child then has room to travel.</p><h2>Full Code Example</h2><pre><code>/* broken: the wrapper hugs the short sidebar, sticky has nowhere to go */ .layout { display: grid; grid-template-columns: 280px 1fr; } .sidebar-wrap { height: fit-content; } .sidebar { position: sticky; top: 16px; } /* fixed: the wrapper stretches to the row height */ .sidebar-wrap { align-self: stretch; /* grid default, removed by the height above */ } .sidebar { position: sticky; top: 16px; }</code></pre><h2>Why This Works</h2><p>position: sticky offsets an element within its nearest scrolling ancestor but never outside its parent''s content box. With align-self: stretch the wrapper is as tall as the long article column, so the sidebar can ride down the full article. height: fit-content collapsed the wrapper to the sidebar''s own height — a sticky element in a box its own size can never move.</p><h2>Common Mistakes</h2><ul><li>Debugging overflow and z-index when the parent is simply too short.</li><li>align-items: start on the grid — same collapse as fit-content.</li><li>Making the parent taller with an arbitrary min-height: 200vh, which leaves dead space after the article ends.</li><li>Expecting sticky to escape into a sibling''s space — it cannot cross the parent boundary, ever.</li></ul><h2>Browser Support / Caveats</h2><p>Sticky is universal. If the parent still will not stretch, check for an ancestor with overflow: hidden, which redefines the scrollport — that is cause one in the anatomy post below.</p><h2>Related Resources</h2><p>The other three failure modes are in <a href="/blog/position-sticky-anatomy">Why position: sticky Quietly Does Nothing</a>, and the mobile header case is in <a href="/blog/sticky-tailwind-navbar">the sticky navbar post</a>.</p>', 'Isaya Masika', 'published', '2026-12-19');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('transform-creates-containing-block', 'Why Does position: fixed Act Like absolute Inside a Transformed Parent?', 'transform-creates-containing-block', 'CSS', 'transform, filter, perspective and will-change on an ancestor make it the containing block for fixed descendants — your modal now positions against the card, not the viewport.', '<p>Your modal has position: fixed; inset: 0 and it covers one card instead of the screen. Somewhere up the tree an ancestor has a transform — often an innocent hover lift — and that silently redefined what fixed means.</p><h2>Direct Answer</h2><p>A transformed element becomes the containing block for all positioned descendants, including fixed ones. filter, perspective, contain: paint and will-change: transform do the same. The fix is structural: render overlays through a portal at the document root, or audit ancestors and remove the property while the overlay is open.</p><h2>Full Code Example</h2><pre><code>/* the bug: modal is fixed, but the card lifts on hover */ .card { transition: transform 180ms ease; } .card:hover { transform: translateY(-3px); } /* .modal inside .card is now relative to the card */ /* the fix: portal to document.body */ import { createPortal } from "react-dom"; function Modal({ children }) { return createPortal( &lt;div className="modal-overlay"&gt;{children}&lt;/div&gt;, document.body ); }</code></pre><h2>Why This Works</h2><p>The CSS spec defines transform as establishing a containing block for fixed and absolute descendants — intentional, so transformed subtrees stay self-contained. createPortal mounts the overlay''s DOM under body, where no transformed ancestor exists, so fixed once again means viewport. This is also why every mature modal, toast and tooltip library portals by default.</p><h2>Common Mistakes</h2><ul><li>Hunting z-index values when the element is positioned inside the wrong box entirely.</li><li>Removing the transform and breaking the hover effect the designer wanted.</li><li>will-change: transform left on a container "for performance" — it creates the containing block even with no visible transform.</li><li>Animating a parent with a keyframe that ends at translateY(0) — the animation fill keeps the containing block alive.</li></ul><h2>Browser Support / Caveats</h2><p>The behaviour is spec-mandated and identical across engines. backdrop-filter has the same containing-block side effect, which is why glass wrappers swallow fixed children too.</p><h2>Related Resources</h2><p>The same mechanism breaks sticky in subtler ways — see <a href="/blog/position-sticky-anatomy">Why position: sticky Quietly Does Nothing</a> and <a href="/blog/backdrop-filter-not-working">why backdrop-filter stops working</a>.</p>', 'Isaya Masika', 'published', '2026-12-20');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('dark-mode-avoid-pure-black', 'Why Should Dark Mode Backgrounds Avoid Pure Black?', 'dark-mode-avoid-pure-black', 'Design Systems', 'Pure #000 with white text causes halation and eye strain, and gives shadows nowhere to go. A dark blue-grey like #0b0f14 keeps contrast high and depth readable.', '<p>The instinct for dark mode is #000000 background, #ffffff text. The result is harsh: bright glyphs bloom into the black (halation), elevation shadows disappear into the void, and OLED smear makes scrolling text ghost.</p><h2>Direct Answer</h2><p>Use a desaturated dark blue-grey for surfaces — #0b0f14 is a solid default — and an off-white like #e5e7eb for primary text. You keep contrast comfortably above 12:1 while giving elevation, borders and shadows tonal room to exist.</p><h2>Full Code Example</h2><pre><code>[data-theme="dark"] { --surface: #0b0f14; --surface-raised: #151b24; --text: #e5e7eb; --text-dim: #9ca3af; --border: rgba(255, 255, 255, 0.08); } .card { background: var(--surface-raised); border: 1px solid var(--border); box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4); }</code></pre><h2>Why This Works</h2><p>Halation is worst at maximum contrast with thin strokes — dropping the text to #e5e7eb trims the bloom while staying far above the 4.5:1 floor. The raised surface at #151b24 is only a few steps lighter than the base, which is enough for the eye to read layering. On pure black, every elevated surface needs a border or it is invisible; on #0b0f14 the shadow still does its job.</p><h2>Common Mistakes</h2><ul><li>Pure white text on pure black — the harshest possible combination and the default in most quick dark modes.</li><li>Reusing light-theme shadows; a light grey shadow on a dark surface glows instead of grounding the element.</li><li>Keeping saturated brand colours at full chroma — they vibrate on dark backgrounds; lighten them slightly.</li><li>Forgetting images: photos with white edges need a 1px border token in dark mode.</li></ul><h2>Browser Support / Caveats</h2><p>Nothing browser-specific — this is perceptual design. On OLED screens true black does save power, so if you ship #000 anywhere, reserve it for full-bleed media backgrounds, not reading surfaces.</p><h2>Related Resources</h2><p>The token structure this lives in is in <a href="/blog/dark-mode-semantic-tokens">Dark Mode Without Inverting</a>, and the toggle logic is in <a href="/blog/dark-mode-triple-state-toggle">the triple-state theme toggle</a>.</p>', 'Isaya Masika', 'published', '2026-12-21');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('dark-mode-triple-state-toggle', 'How Do I Build a Light / Dark / System Theme Toggle Without a Flash?', 'dark-mode-triple-state-toggle', 'Design Systems', 'Three states — light, dark, unset — stored in localStorage, resolved in a blocking inline script before first paint, and applied as a data-theme attribute.', '<p>A theme toggle that respects the OS has three states, not two: explicit light, explicit dark, and unset (follow the OS). Get the order wrong and the user sees a white flash on every load before your React app hydrates.</p><h2>Direct Answer</h2><p>Store only the explicit choice in localStorage; absent means system. Run a tiny synchronous script in the head that reads the stored value, falls back to matchMedia, and sets data-theme on the html element before any CSS paints. React then treats the attribute as read-only and only writes through the toggle.</p><h2>Full Code Example</h2><pre><code>&lt;script&gt; (function () { var t = null; try { t = localStorage.getItem("theme"); } catch (e) {} if (t !== "light" &amp;&amp; t !== "dark") { t = matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light"; } document.documentElement.setAttribute("data-theme", t); })(); &lt;/script&gt; // the toggle (React) function setTheme(next) { if (next === "system") localStorage.removeItem("theme"); else localStorage.setItem("theme", next); const t = next === "system" ? (matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light") : next; document.documentElement.setAttribute("data-theme", t); }</code></pre><h2>Why This Works</h2><p>The inline script runs before the body renders, so the first paint already has the right tokens — no flash, no hydration mismatch, because React never owns the attribute. Removing the key for "system" keeps the storage honest: absence is the unset state, so an OS change is picked up on next load without any listener. Three states in one attribute keeps CSS simple: [data-theme="dark"] is the only selector you need.</p><h2>Common Mistakes</h2><ul><li>Applying the theme in useEffect — the first paint already happened, that is the flash.</li><li>Two states stored as a boolean, so "follow the OS" is impossible to express.</li><li>Toggling a class on body in React and fighting hydration warnings on every load.</li><li>Not listening to matchMedia changes while in system mode — add a change listener if your app stays open for days.</li></ul><h2>Browser Support / Caveats</h2><p>matchMedia and localStorage are universal. The try/catch matters: in blocked-storage environments the script must still resolve to a working default rather than throwing before first paint.</p><h2>Related Resources</h2><p>The tokens this attribute switches are in <a href="/blog/dark-mode-semantic-tokens">Semantic Tokens First</a>, and palette choices in <a href="/blog/dark-mode-avoid-pure-black">why not pure black</a>.</p>', 'Isaya Masika', 'published', '2026-12-22');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('design-tokens-two-layer-architecture', 'How Do I Structure Design Tokens So Theming Does Not Break Components?', 'design-tokens-two-layer-architecture', 'Design Systems', 'Two layers: raw palette tokens (--grey-900) that themes override, and semantic tokens (--text) that components consume. Components never touch the palette directly.', '<p>The dark mode that "mostly works" always traces back to the same shortcut: components referencing raw colours. The button uses --grey-900, the card uses --grey-900, and now you cannot darken text without also darkening the card.</p><h2>Direct Answer</h2><p>Define the palette once as primitive tokens, then alias them into semantic tokens — --surface, --text, --accent, --border. Themes only redefine the semantic layer. Components only reference the semantic layer. Neither ever crosses the boundary.</p><h2>Full Code Example</h2><pre><code>:root { /* layer 1: palette, never used by components */ --grey-0: #ffffff; --grey-100: #f3f4f6; --grey-900: #111827; --gold-500: #f5b400; /* layer 2: semantic, the only layer components see */ --surface: var(--grey-0); --surface-sunken: var(--grey-100); --text: var(--grey-900); --accent: var(--gold-500); } [data-theme="dark"] { --surface: #0b0f14; --surface-sunken: #06090d; --text: #e5e7eb; --accent: #ffc43d; } .button { background: var(--accent); color: var(--text); }</code></pre><h2>Why This Works</h2><p>The indirection is the entire value: dark mode is a 4-line override instead of a 400-selector audit. Semantic names also document intent — --text-dim tells the next engineer what the colour is for, #6b7280 does not. When the brand adds a third theme, you add a third block and touch zero components.</p><h2>Common Mistakes</h2><ul><li>Components reaching into layer 1 "just this once" — that instance is invisible to theming forever.</li><li>One layer only, so every theme re-declares 60 variables and drifts out of sync.</li><li>Naming semantics after appearance (--blue-background) instead of role (--accent-surface); appearance names rot on the first rebrand.</li><li>Overriding primitives per theme — the palette should be theme-independent facts about your brand.</li></ul><h2>Browser Support / Caveats</h2><p>Custom properties are universal. Keep the layers in one stylesheet or enforce order with cascade layers; a semantic token defined before its primitive resolves to the inherited value and fails silently.</p><h2>Related Resources</h2><p>The dark-mode application of this pattern is in <a href="/blog/dark-mode-semantic-tokens">Dark Mode Without Inverting</a>, and the components consuming these tokens live in the <a href="/components">component library</a>.</p>', 'Isaya Masika', 'published', '2026-12-23');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-input-frozen-value-onchange', 'Why Is My React Input Frozen and Impossible to Type Into?', 'react-input-frozen-value-onchange', 'React', 'You set value without onChange, so React re-renders the input with the same value on every keystroke. Add onChange or switch to defaultValue.', '<p>The most common React bug report reads "the input is frozen". Nine times out of ten the JSX is &lt;input value={email} /&gt; with no onChange — React owns the DOM value and dutifully restores it after every keystroke you type.</p><h2>Direct Answer</h2><p>value makes an input controlled: React is the source of truth and must be updated via onChange on every keystroke. If you do not need per-keystroke state, drop value entirely and use defaultValue with a ref — the DOM owns the value and React reads it on submit.</p><h2>Full Code Example</h2><pre><code>// controlled: correct pairing const [q, setQ] = useState(""); &lt;input value={q} onChange={(e) =&gt; setQ(e.target.value)} /&gt; // uncontrolled: no state at all const inputRef = useRef(null); &lt;input defaultValue="" ref={inputRef} /&gt; // read later: inputRef.current.value</code></pre><h2>Why This Works</h2><p>Controlled inputs round-trip every change through state: keystroke, setState, re-render, DOM value updated. Miss the onChange and the round-trip restores the old value — the freeze. Uncontrolled inputs skip the loop entirely; the DOM node holds the text and defaultValue only seeds the first render. Both are correct; the bug is the half-controlled middle.</p><h2>Common Mistakes</h2><ul><li>value={q} with onChange={() =&gt; {}} — compiles, still frozen, and harder to spot.</li><li>Passing value={maybeUndefined} — React flips the input between uncontrolled and controlled and warns loudly in the console.</li><li>Calling setState with the event instead of e.target.value in a async handler after the event pooled — read the value synchronously.</li><li>Using controlled inputs for a 40-field form and re-rendering the whole form per keystroke.</li></ul><h2>Browser Support / Caveats</h2><p>Pure React behaviour, no browser variance. File inputs are the exception: they are always uncontrolled, because JS cannot set a file path for security reasons.</p><h2>Related Resources</h2><p>The decision framework for which mode to pick is in <a href="/blog/react-controlled-vs-uncontrolled">Controlled vs Uncontrolled Inputs</a>, and the ref pattern is in <a href="/blog/uncontrolled-inputs-defaultvalue-ref">uncontrolled inputs with refs</a>.</p>', 'Isaya Masika', 'published', '2026-12-24');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('uncontrolled-inputs-defaultvalue-ref', 'When Should I Use defaultValue and a Ref Instead of State for an Input?', 'uncontrolled-inputs-defaultvalue-ref', 'React', 'When you only read the value on submit, per-keystroke state is pure overhead: defaultValue seeds the input, a ref reads it back, and nothing re-renders.', '<p>A search page with twelve filter inputs in controlled mode re-renders the entire filter panel on every keystroke. If you only need the values when the user hits Apply, that state is buying you nothing.</p><h2>Direct Answer</h2><p>Use uncontrolled inputs — defaultValue plus a ref, or FormData on submit — whenever there is no per-keystroke validation, no derived UI, and no programmatic rewriting of the value. Read everything at submit time in one shot.</p><h2>Full Code Example</h2><pre><code>function FilterForm({ onApply }) { const minRef = useRef(null); const maxRef = useRef(null); function handleSubmit(e) { e.preventDefault(); onApply({ min: minRef.current.value, max: maxRef.current.value }); } return ( &lt;form onSubmit={handleSubmit}&gt; &lt;input defaultValue="" ref={minRef} inputMode="numeric" /&gt; &lt;input defaultValue="" ref={maxRef} inputMode="numeric" /&gt; &lt;button&gt;Apply&lt;/button&gt; &lt;/form&gt; ); }</code></pre><h2>Why This Works</h2><p>Keystrokes stay in the DOM; React renders once at mount and once at submit. defaultValue seeds the initial text without taking ownership, and the ref is a stable handle to the node — no state, no effects, no re-render cost. A FormData read of e.currentTarget achieves the same thing with zero refs if every input has a name.</p><h2>Common Mistakes</h2><ul><li>Mixing modes: setting value later to "reset" an uncontrolled input — use a key change to remount it instead.</li><li>Trying to validate per keystroke on an uncontrolled field; at that point the field wants to be controlled.</li><li>Reading refs during render instead of in an event handler — the node may not match what is on screen yet.</li><li>Integrating a third-party widget by forcing it into controlled mode; let the widget own its DOM and sync via callbacks.</li></ul><h2>Browser Support / Caveats</h2><p>Uncontrolled inputs behave identically everywhere — they are just DOM inputs. IME composition (Chinese, Japanese, Korean input) still fires onChange normally if you later add one, so you can upgrade a field to controlled without breaking IME.</p><h2>Related Resources</h2><p>The full comparison table is in <a href="/blog/react-controlled-vs-uncontrolled">Controlled vs Uncontrolled Inputs</a>, and the frozen-input failure is dissected in <a href="/blog/react-input-frozen-value-onchange">why inputs freeze</a>.</p>', 'Isaya Masika', 'published', '2026-12-25');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('useeffect-stale-closure-fix', 'How Do I Fix a Stale Closure in useEffect?', 'useeffect-stale-closure-fix', 'React', 'The effect captured the props from its first render. Either add the value to the dependency array or read it through a ref that always points at the latest render.', '<p>Your effect fetches with limit=20 forever, even after the user changes the filter to 50. The closure captured the limit variable from the render where the effect was created — and with an empty dependency array, that render was the first one.</p><h2>Direct Answer</h2><p>Two honest fixes. If the effect should re-run when the value changes, put the value in the dependency array. If the effect should run once but always see the latest value, mirror the value into a ref every render and read ref.current inside the effect. The wrong fix is disabling the lint rule.</p><h2>Full Code Example</h2><pre><code>// fix 1: depend on it — the effect re-runs when limit changes useEffect(() =&gt; { fetch("/api/blog?limit=" + limit); }, [limit]); // fix 2: ref mirror — run once, always call the latest callback const cb = useRef(onAuthenticated); useEffect(() =&gt; { cb.current = onAuthenticated; }, [onAuthenticated]); useEffect(() =&gt; { fetchSession().then((email) =&gt; email &amp;&amp; cb.current({ email })); }, [open]);</code></pre><h2>Why This Works</h2><p>Closures capture values, not variables — the limit inside your effect is a snapshot. The dependency array tells React to tear down and re-create the effect when the snapshot is outdated. The ref pattern sidesteps re-creation entirely: ref.current is mutable and shared across renders, so the one-time effect always invokes the freshest callback without re-subscribing.</p><h2>Common Mistakes</h2><ul><li>eslint-disable-next-line exhaustive-deps — the stale closure is still there, you just cannot see it.</li><li>Adding the dependency when the effect must not re-run (a WebSocket subscribe), then wondering why it reconnects on every keystroke — that is the ref case.</li><li>Reading state directly in a setInterval inside [] — the interval ticks with the mount-time state forever.</li><li>Mutating a module-level variable as a "ref" — breaks with multiple component instances.</li></ul><h2>Browser Support / Caveats</h2><p>React semantics, engine-independent. In React 19 the compiler auto-memoises values, which reduces how often you need the ref pattern — but closures still capture, so the mental model stays.</p><h2>Related Resources</h2><p>Both failure modes with the dependency array are in <a href="/blog/useeffect-dependencies">useEffect Dependencies</a>, and the infinite-loop twin is in <a href="/blog/useeffect-infinite-loop-objects">object dependencies</a>.</p>', 'Isaya Masika', 'published', '2026-12-26');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('useeffect-infinite-loop-objects', 'Why Does My useEffect Run Forever When I Depend on an Object?', 'useeffect-infinite-loop-objects', 'React', 'Object literals get a new identity every render, so the effect sees a ''changed'' dependency each time and re-runs — often setting state and re-rendering again.', '<p>const options = { limit: 20 } inside your component body creates a brand-new object on every render. useEffect compares dependencies by Object.is, so [options] is a different dependency every single time — the effect runs, sets state, re-renders, and loops.</p><h2>Direct Answer</h2><p>Three exits, in order of preference: inline the primitive values into the dependency array (depend on limit, not options), hoist the object outside the component if it is static, or memoise it with useMemo when it genuinely derives from props.</p><h2>Full Code Example</h2><pre><code>// the loop const options = { limit: 20 }; useEffect(() =&gt; { fetchList(options); }, [options]); // infinite // fix 1: depend on primitives const limit = 20; useEffect(() =&gt; { fetchList({ limit }); }, [limit]); // fix 2: hoist static config outside the component const OPTIONS = { limit: 20 }; useEffect(() =&gt; { fetchList(OPTIONS); }, []); // fix 3: memoise derived config const opts = useMemo(() =&gt; ({ limit: page.size }), [page.size]); useEffect(() =&gt; { fetchList(opts); }, [opts]);</code></pre><h2>Why This Works</h2><p>React''s dependency check is identity-based for objects and value-based for primitives. Depend on a number or string and the check does what you meant. Hoisting moves the object to module scope, where one identity lives for the app''s lifetime. useMemo pins the identity to the inputs that actually define it — page.size changes, new object; anything else re-renders, same object.</p><h2>Common Mistakes</h2><ul><li>useMemo around every object "just in case" — memoisation has its own cost and most objects are cheap to rebuild.</li><li>JSON.stringify(options) as a dependency — works, but it stringifies on every render and hides the real fix.</li><li>Depending on a function defined in the component body — same identity problem; wrap it in useCallback or move the logic inside the effect.</li><li>Assuming StrictMode''s double-invoke is your bug — that is development-only and intentional.</li></ul><h2>Browser Support / Caveats</h2><p>React semantics, no browser variance. If the loop only appears in production, check for a context provider value={{...}} — the same identity trap one level up.</p><h2>Related Resources</h2><p>The mirror-image failure (missing dependency) is in <a href="/blog/useeffect-dependencies">useEffect Dependencies</a>, and the stale-closure fix patterns are in <a href="/blog/useeffect-stale-closure-fix">fixing stale closures</a>.</p>', 'Isaya Masika', 'published', '2026-12-27');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('fetch-race-conditions-abortcontroller', 'How Do I Stop an Older fetch Response from Overwriting a Newer One?', 'fetch-race-conditions-abortcontroller', 'React', 'Two requests resolving out of order is a race condition: the slow old response lands last and wins. AbortController cancels the stale request outright.', '<p>The user switches a filter twice quickly. Request A is slow, request B is fast — B resolves first, the UI shows the right data, then A lands and clobbers it with stale results. Nothing in fetch promises ordering.</p><h2>Direct Answer</h2><p>Create a new AbortController per effect run and pass its signal to fetch. In the cleanup, call ctrl.abort(). When the URL changes and the effect re-runs, the previous request is cancelled mid-flight; its promise rejects with AbortError, which you ignore. Only the latest request can write state.</p><h2>Full Code Example</h2><pre><code>export function useFetch(url) { const [state, setState] = useState({ data: null, error: null, loading: !!url }); useEffect(() =&gt; { if (!url) return; const ctrl = new AbortController(); setState((s) =&gt; ({ ...s, loading: true })); fetch(url, { signal: ctrl.signal }).then(async (res) =&gt; { const body = await res.json().catch(() =&gt; null); if (!res.ok) throw new Error(body?.error || "Failed"); return body; }).then((data) =&gt; setState({ data, error: null, loading: false })).catch((err) =&gt; { if (err.name === "AbortError") return; setState({ data: null, error: err.message, loading: false }); }); return () =&gt; ctrl.abort(); }, [url]); return state; }</code></pre><h2>Why This Works</h2><p>The cleanup runs before the next effect run, so every URL change immediately kills the in-flight request. An aborted fetch rejects synchronously enough that its .then never fires — the stale data physically cannot reach setState. The catch filter for AbortError is essential: an abort is a normal control-flow event, not a failure to surface.</p><h2>Common Mistakes</h2><ul><li>Comparing response URLs manually to detect staleness — works, but you still download the stale payload and pay for it.</li><li>Ignoring AbortError and showing an error flash on every filter change.</li><li>Sharing one controller across requests — aborting cancels everything including the fresh request.</li><li>Keeping a dead flag instead of aborting; the flag hides the symptom but the network cost and cache pressure remain.</li></ul><h2>Browser Support / Caveats</h2><p>AbortController is universal. Note that aborting does not guarantee the server stops work — it frees the client. If you debounce the input too, most races never happen in the first place.</p><h2>Related Resources</h2><p>The full hook including error states is in <a href="/blog/custom-fetch-hook">A useFetch Hook That Handles Races, Aborts and Errors</a>, and the unmount half of the problem is in <a href="/blog/react-async-setstate-after-unmount">setState after unmount</a>.</p>', 'Isaya Masika', 'published', '2026-12-28');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('error-boundaries-async-errors', 'Why Doesn''t My Error Boundary Catch Async Errors?', 'error-boundaries-async-errors', 'React', 'Boundaries catch errors during render only. Rejected promises, event handlers and timers run outside render — re-throw them into render state or handle them locally.', '<p>You wrapped the app in an error boundary, a fetch rejects, and the screen still goes white. The boundary did nothing wrong — the error never happened during render, so React never had a chance to hand it to the boundary.</p><h2>Direct Answer</h2><p>Error boundaries catch errors thrown synchronously during rendering, lifecycle methods and constructors. For async code, catch the error yourself and either render an error state locally, or store the error in state and re-throw it during the next render — which does reach the boundary.</p><h2>Full Code Example</h2><pre><code>function Profile() { const [error, setError] = useState(null); if (error) throw error; // re-thrown during render: the boundary catches this useEffect(() =&gt; { fetch("/api/profile", { credentials: "include" }).then((r) =&gt; r.json()).catch((err) =&gt; setError(err)); // boundary-safe delivery }, []); return &lt;div&gt;...&lt;/div&gt;; } // event handlers: same story, handle locally function handleClick() { try { riskyThing(); } catch (err) { setError(err); } }</code></pre><h2>Why This Works</h2><p>React''s error boundary protocol (getDerivedStateFromError) only runs when the renderer unwinds from a throw. A promise rejection unwinds through the microtask queue, nowhere near React''s render loop — so it hits window.onunhandledrejection instead. Storing the error and throwing on the next render re-enters the render path, where the boundary''s contract applies.</p><h2>Common Mistakes</h2><ul><li>Expecting boundaries to catch event handler throws — they never have; wrap handlers in try/catch.</li><li>Throwing inside .then directly and assuming the nearest boundary gets it.</li><li>Catching a lazy() chunk failure with the boundary inside the lazy component — the boundary must be outside the Suspense/lazy pair.</li><li>Swallowing async errors into console.error, which looks identical to a healthy app in a support screenshot.</li></ul><h2>Browser Support / Caveats</h2><p>This is React semantics, not browser behaviour. For truly global async failures, also listen to unhandledrejection at the window level and report it — that catches what no component owned.</p><h2>Related Resources</h2><p>What boundaries do catch is in <a href="/blog/react-error-boundaries">Error Boundaries</a>, and the lazy-import case is in <a href="/blog/react-lazy-route-splitting">route splitting with lazy()</a>.</p>', 'Isaya Masika', 'published', '2026-12-29');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-index-key-delete-bug', 'Why Does Deleting a Row Scramble the Rows Below It in React?', 'react-index-key-delete-bug', 'React', 'Index keys make React match rows by position. Delete row 2 and every row after keeps its old key with new data — internal state lands on the wrong record.', '<p>The classic bug: a list of todo rows with inputs, you delete the second row, and the third row''s half-typed text now sits in the second row''s slot. You used key={i} and React reconciled by position.</p><h2>Direct Answer</h2><p>Keys are identity. Use a stable id from the data — key={row.id} — so React unmounts the deleted row''s component and shifts the survivors, state intact. Index keys only survive lists that are append-only and never reordered.</p><h2>Full Code Example</h2><pre><code>// broken: positional identity {rows.map((row, i) =&gt; &lt;Row key={i} data={row} /&gt;)} // fixed: real identity {rows.map((row) =&gt; &lt;Row key={row.id} data={row} /&gt;)} // if rows have no id, mint one at creation, not at render: const addRow = (text) =&gt; setRows((r) =&gt; [...r, { id: crypto.randomUUID(), text }]);</code></pre><h2>Why This Works</h2><p>Reconciliation matches old and new children by key. With index keys, deleting index 1 renames every later key: the component that was row 2 becomes row 1, keeps its state and receives row 1''s props — the scramble. With data ids, React sees that key "b" vanished and unmounts exactly that subtree; every other key-data pairing survives untouched.</p><h2>Common Mistakes</h2><ul><li>Generating ids during render (Math.random() as key) — new identity every render, so every row remounts and loses focus.</li><li>Assuming stateless rows are safe — they are, until someone adds a controlled input or an expanded flag six months later.</li><li>Duplicate keys from a non-unique field like email — React silently reuses the first element.</li><li>Fixing it with key={JSON.stringify(row)} — changes identity on every data edit.</li></ul><h2>Browser Support / Caveats</h2><p>crypto.randomUUID() is universal in current browsers; for older targets, a monotonic counter at creation time is fine — the id only needs to be unique within the list.</p><h2>Related Resources</h2><p>The reconciliation model is in <a href="/blog/react-list-keys-reconciliation">List Keys Are Identity, Not an Index</a>, and the duplicate-key failure is in <a href="/blog/react-duplicate-keys-silent-bug">duplicate keys</a>.</p>', 'Isaya Masika', 'published', '2026-12-30');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-duplicate-keys-silent-bug', 'What Happens When Two React List Items Share the Same Key?', 'react-duplicate-keys-silent-bug', 'React', 'No error is thrown. React reuses the first matching element for the duplicate key, so the second item''s props update the first item''s component and one row renders stale.', '<p>Duplicate keys are the nasty sibling of index keys: no console error in production, no crash — just one card showing another card''s data, or a list that refuses to update its second half.</p><h2>Direct Answer</h2><p>Keys must be unique among siblings. When React encounters a duplicate, reconciliation matches the first element with that key; the second collides with the same identity and its props flow into the first''s component instance. Fix the data — the id you chose is not an id.</p><h2>Full Code Example</h2><pre><code>// broken: authors repeat across books {books.map((b) =&gt; &lt;Card key={b.author} book={b} /&gt;)} // two "Murakami" cards share one identity // fixed: unique per item {books.map((b) =&gt; &lt;Card key={b.isbn} book={b} /&gt;)} // composite when no natural id exists: key={`${b.author}-${b.title}`}</code></pre><h2>Why This Works</h2><p>During reconciliation React builds a map from key to element. A duplicate key overwrites the map entry — the second element is treated as an update of the first. State, DOM node and effects belong to whichever element claimed the key first, and the real second item never mounts. Uniqueness is only required among siblings, so scoping keys per list is fine.</p><h2>Common Mistakes</h2><ul><li>Keying by a display field (name, email, slug) that data does not guarantee unique.</li><li>Keying paginated results by position in the page — page 2''s first row collides with page 1''s first row when pages merge.</li><li>Dev mode hides it: React logs a warning only in development, and production builds stay silent.</li><li>Concatenating two non-unique fields and declaring victory without checking the combination is unique.</li></ul><h2>Browser Support / Caveats</h2><p>React behaviour, engine-independent. If the API truly has no unique field, mint ids client-side at fetch time and cache them by reference — do not mint during render.</p><h2>Related Resources</h2><p>The identity model is in <a href="/blog/react-list-keys-reconciliation">List Keys Are Identity, Not an Index</a>, and the positional variant is in <a href="/blog/react-index-key-delete-bug">the index-key delete bug</a>.</p>', 'Isaya Masika', 'published', '2026-12-31');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('css-grid-vs-flexbox', 'CSS Grid vs Flexbox: When to Use Which', 'css-grid-vs-flexbox', 'CSS', 'Flexbox for one dimension — items sized by content along a line. Grid for two dimensions — tracks you design first, then place items into.', '<p>Every front-end team relitigates this question on every project. Pick wrong and you fight the browser for a week; pick right and the CSS writes itself. The rule fits in one sentence and holds in about 95 percent of cases.</p><h2>Direct Answer</h2><p>Use Flexbox when the layout is one-dimensional: a single row or column of items whose sizes come from their content. Use Grid when the layout is two-dimensional: you design the rows and columns first, then drop items into the tracks. If the question is "how do I line these things up?", that is flexbox. If it is "how do I arrange these things on the page?", that is grid.</p><h2>Full Code Example</h2><pre><code>/* Flexbox: a toolbar. Items size from content outward. */ .toolbar { display: flex; align-items: center; gap: 12px; } .toolbar .spacer { flex: 1; } /* pushes everything after it to the far end */ /* Grid: a page shell. You declare the tracks first. */ .shell { display: grid; grid-template-columns: 240px 1fr; grid-template-rows: 56px 1fr; min-height: 100dvh; } .shell &gt; header { grid-column: 1 / -1; } /* Grid: a gallery that wraps itself with zero media queries. */ .gallery { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 20px; }</code></pre><h2>Why This Works</h2><p>Flexbox sizes from the content out: each item is measured, then free space is distributed along one axis. That is why it excels at navbars, toolbars and button groups, where the content is in charge. Grid sizes from the container in: you declare the tracks and items stretch to fit them, which is why it excels at page shells and card galleries, where the structure is in charge. The <code>repeat(auto-fill, minmax(220px, 1fr))</code> line is grid''s killer feature — a fully responsive gallery with no breakpoints, something flexbox cannot do without wrapping hacks that never align across rows. A useful tiebreaker: if you are setting percentage widths on flex children and backing them with media queries, you have quietly reinvented grid tracks — switch to grid and delete the breakpoints.</p><h2>Common Mistakes</h2><ul><li>Nesting five flex containers to fake a page shell — one grid replaces the entire tree.</li><li>Using grid for a simple centered row; <code>display: flex; justify-content: center</code> is two lines and done.</li><li>Expecting wrapped flex items to align into columns — each wrapped row is independent, so nothing lines up. That alignment is grid''s job.</li><li>Reaching for <code>flex: 1</code> on every child when <code>gap</code> plus natural widths was the actual intent.</li></ul><h2>Browser Support / Caveats</h2><p>Both are universal in every browser that matters. The one version-sensitive feature is <code>gap</code> in flexbox, which needs Safari 14.1 or newer; older Safari required margin workarounds. Grid''s <code>subgrid</code> value is newer again and lets children align to a parent''s tracks — without it, cards in the same row drift out of alignment the moment one grows taller than its siblings. Flexbox''s alignment properties (<code>justify-content</code>, <code>align-items</code>) are safe in every browser where <code>gap</code> works, so the two can be adopted together.</p><h2>Related Resources</h2><p>Once the layout is right, make components respond to their slot instead of the viewport with <a href="/blog/container-queries-inline-size">container queries</a>, and pull ready-made grid and flex patterns from the <a href="/components">component library</a>.</p>', 'Isaya Masika', 'published', '2027-01-01');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('tailwind-center-div', 'How Do I Center a Div in Tailwind CSS?', 'tailwind-center-div', 'Tailwind', 'flex items-center justify-center on the parent, or grid place-items-center. Horizontal only: mx-auto plus a width. The parent needs a height or there is nothing to center within.', '<p>"How do I center a div" is the most searched CSS question of all time for a reason: there are five correct answers and the right one depends on which axis and which parent you have. In Tailwind it collapses to three patterns worth memorising. Learn them once and they transfer to every modal, hero and empty state you will ever build.</p><h2>Direct Answer</h2><p>Both axes: <code>flex items-center justify-center</code> on the parent, or <code>grid place-items-center</code>. Horizontal only: <code>mx-auto</code> on the child, which needs a width constraint (<code>max-w-md</code>, <code>w-64</code>) to have any effect. Vertical only: <code>flex items-center</code> on the parent. In every case the parent needs a height — <code>h-screen</code>, <code>min-h-screen</code>, or a flex column with <code>flex-1</code> — or there is nothing to center within. Watch the flex direction: inside <code>flex-col</code>, <code>items-center</code> centers horizontally and <code>justify-center</code> vertically, because the axes swap with the direction.</p><h2>Full Code Example</h2><pre><code>&lt;!-- Both axes, the everyday answer --&gt; &lt;div class="flex min-h-screen items-center justify-center"&gt; &lt;div class="w-64 rounded-xl bg-white p-6 shadow"&gt;Centered&lt;/div&gt; &lt;/div&gt; &lt;!-- Both axes, the two-word version --&gt; &lt;div class="grid min-h-screen place-items-center"&gt; &lt;div class="w-64"&gt;Centered&lt;/div&gt; &lt;/div&gt; &lt;!-- Horizontal only: centering a block, not its text --&gt; &lt;div class="mx-auto max-w-md"&gt;Centered column&lt;/div&gt; &lt;!-- Vertical only, inside a fixed-height bar --&gt; &lt;div class="flex h-16 items-center"&gt; &lt;span&gt;Vertically centered&lt;/span&gt; &lt;/div&gt; &lt;!-- Overlay centering: the pattern every modal uses --&gt; &lt;div class="fixed inset-0 grid place-items-center bg-black/40"&gt; &lt;div class="w-80 rounded-xl bg-white p-6"&gt;Modal&lt;/div&gt; &lt;/div&gt;</code></pre><h2>Why This Works</h2><p><code>items-center</code> aligns on the cross axis (vertical in a row flex), <code>justify-center</code> on the main axis (horizontal). Confusing the two is the single most common Tailwind mistake, and the fix is memorising one rule: justify follows the flex direction. <code>mx-auto</code> works differently: it sets both horizontal margins to auto, and auto margins only absorb free space when the element is narrower than its parent — hence the mandatory width class on the child. The grid version is the sturdiest of the three: <code>place-items</code> is shorthand for <code>align-items</code> plus <code>justify-items</code>, and it centers a single child regardless of that child''s size. Note that none of these patterns touches the child beyond a width — centering is always the parent''s job.</p><h2>Common Mistakes</h2><ul><li>Forgetting the parent height, then wondering why vertical centering does nothing — a block parent''s height collapses to its content.</li><li><code>mx-auto</code> on a full-width child; with no free space, auto margins compute to zero.</li><li>Using <code>text-center</code> to center a block element; it only centers inline content.</li><li>Wrapping in three nested divs when the parent could have carried both classes itself — utility-first means fewer wrappers, not more.</li></ul><h2>Browser Support / Caveats</h2><p>All three patterns compile to plain flexbox, grid and margin CSS — no caveats beyond what those carry. <code>place-items</code> needs grid support, universal since 2017. On mobile prefer <code>min-h-screen</code> over <code>h-screen</code> so content taller than the viewport can still scroll instead of clipping.</p><h2>Related Resources</h2><p>Grab pre-centered modals, hero sections and empty states from the <a href="/components">component library</a>, and see the same centering logic inside <a href="/blog/sticky-tailwind-navbar">the sticky navbar writeup</a>.</p>', 'Isaya Masika', 'published', '2027-01-02');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-usestate-not-updating-immediately', 'Why Does useState Not Update Immediately After I Call the Setter?', 'react-usestate-not-updating-immediately', 'React', 'State variables are snapshots of one render. The setter schedules a re-render; it does not mutate the variable you are holding. Use the updater form or compute the next value yourself.', '<p>You call <code>setCount(count + 1)</code>, log <code>count</code> on the next line, and see the old number. This is not a bug and it is not "async" in the promise sense — it is how React''s render model works, and once the model clicks, the fix is obvious.</p><h2>Direct Answer</h2><p>State variables are snapshots of a single render. Calling the setter does not mutate the variable you are holding; it schedules a re-render with the new value. Any code running after the setter — the next line, a log, a fetch — still sees the old snapshot. If you need the new value, you already have it: it is the value you passed to the setter. If you need to react to the change, do it in a <code>useEffect</code> keyed on that state.</p><h2>Full Code Example</h2><pre><code>const [count, setCount] = useState(0); function increment() { setCount(count + 1); console.log(count); // old value — this render''s snapshot never changes } // When next state depends on previous state, use the updater form: function incrementTwice() { setCount((c) =&gt; c + 1); setCount((c) =&gt; c + 1); // +2 — each call receives the freshest value } // Need the new value for a side effect? Compute it yourself: function save() { const next = count + 1; setCount(next); localStorage.setItem("count", String(next)); } // Or react after the commit, in an effect: useEffect(() =&gt; { document.title = "Count: " + count; }, [count]);</code></pre><h2>Why This Works</h2><p>Each render captures its own props and state as constants. The updater form <code>setCount((c) =&gt; c + 1)</code> bypasses the snapshot problem entirely because React hands the queued latest value to your function during processing — which is why two updater calls in one handler produce +2 while two <code>setCount(count + 1)</code> calls produce +1. Effects run after the commit, so <code>[count]</code> in the dependency array guarantees the body sees the settled value, never a half-updated one. The same snapshot logic explains stale closures elsewhere: a timer or subscription created during render N reads render N''s state forever, no matter how many updates arrive later.</p><h2>Common Mistakes</h2><ul><li>Logging state right after the setter and concluding state is broken.</li><li>Calling <code>setCount(count + 1)</code> twice in one handler expecting +2 — both read the same snapshot.</li><li>Building a fetch with the old value immediately after setting state — compute <code>next</code> first and use it for both.</li><li>Chaining setters to derive one state from another; derive during render instead, no extra state needed.</li></ul><h2>Browser Support / Caveats</h2><p>Since React 18, updates are batched everywhere — inside promises, timeouts and native event handlers — so even a <code>setTimeout</code> callback sees batched behaviour. The rare escape hatch is <code>flushSync</code> from <code>react-dom</code>, needed only when you must measure the DOM synchronously after an update; reach for it never, then once. Class components never had this confusion because <code>this.state</code> was one mutable object — the snapshot model is the price of hooks being plain functions, and it buys you renders that can be interrupted safely.</p><h2>Related Resources</h2><p>The dependency rules for the effect-based fix are in <a href="/blog/useeffect-dependencies">useEffect Dependencies</a>, and state-driven form patterns live in the <a href="/components">component library</a>.</p>', 'Isaya Masika', 'published', '2027-01-03');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('css-z-index-not-working', 'Why Is My z-index Not Working?', 'css-z-index-not-working', 'CSS', 'z-index needs a positioned element (or flex/grid child), and it only competes inside its stacking context. transform, filter or opacity on an ancestor traps the child — no number escapes that.', '<p>You set <code>z-index: 9999</code> and the element still hides behind a sibling with <code>z-index: 1</code>. The number is not the problem. z-index obeys two rules most developers only half remember, and both must be satisfied at once. Nine times out of ten the fix is deleting something, not adding a bigger number.</p><h2>Direct Answer</h2><p>First, z-index only applies to positioned elements (<code>relative</code>, <code>absolute</code>, <code>fixed</code>, <code>sticky</code>) and to flex or grid children — on a static element it is silently ignored. Second, z-index only competes within its stacking context. If an ancestor has <code>transform</code>, <code>filter</code>, <code>opacity</code> below 1, or <code>isolation: isolate</code>, that ancestor forms a new context, and your 9999 is competing only against its siblings inside it. The header with z-index 1 outside the context still paints above everything within it. Both rules fail silently — the browser never warns — which is why this bug eats afternoons.</p><h2>Full Code Example</h2><pre><code>/* Broken: z-index on a static element does nothing at all */ .tooltip { z-index: 9999; } /* Fixed: give it a position */ .tooltip { position: absolute; z-index: 9999; } /* Broken: the parent traps the child''s z-index in a new context */ .card { transform: translateY(0); } /* creates a stacking context */ .card .dropdown { position: absolute; z-index: 9999; } /* still under the header */ /* Fixed: remove the transform, or move the dropdown out of .card entirely */ .card { transform: none; } /* Overlay pattern that always wins: render at the body level */ .modal { position: fixed; inset: 0; z-index: 50; }</code></pre><h2>Why This Works</h2><p>Paint order is resolved per stacking context, like nested zip files: the browser compares z-index values only between siblings in the same context, then composites whole contexts against each other. A child can never escape its context, no matter the number — this is why "just add more nines" fails. The reliable patterns are: keep overlays as direct children of <code>body</code>, and never put <code>transform</code>, <code>filter</code> or <code>will-change</code> on ancestors of anything that needs to float above other content. Assign z-index to the top-level layers once — header 40, overlay 50, toast 60 — in a tokens file, and the arms race ends permanently.</p><h2>Common Mistakes</h2><ul><li>Adding z-index without a position — nothing changes, and no error appears.</li><li>Raising the number instead of finding the context — 999999 loses to 1 across a context boundary.</li><li>A leftover <code>transform: translateY(0)</code> from a refactor, quietly creating a context.</li><li>An <code>overflow: hidden</code> ancestor clipping the dropdown, which looks identical to a z-index bug.</li></ul><h2>Browser Support / Caveats</h2><p>The stacking rules are ancient and identical in every browser — no caveats. The debugging shortcut: inspect ancestors for transform, filter or opacity, or open the Layers panel in DevTools, and the offending context shows itself in seconds. One genuine browser difference: Safari has historically been flakier with <code>will-change</code>-created contexts, so prefer <code>transform</code> or <code>isolation: isolate</code> where you control the trigger.</p><h2>Related Resources</h2><p>The full anatomy of transform-created contexts is in <a href="/blog/transform-creates-containing-block">this article</a>, and working overlay components live in the <a href="/components">component library</a>.</p>', 'Isaya Masika', 'published', '2027-01-04');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-debounce-search-input', 'How Do I Debounce a Search Input in React?', 'react-debounce-search-input', 'React', 'Keep the input controlled and instant. Debounce a copy of the value with useEffect plus setTimeout and a cleanup, then fetch off the debounced value. 300ms is the right default.', '<p>Every keystroke firing a network request is how a search box takes down its own API. Debouncing waits until the user pauses, then fires once. Done wrong it makes the input feel broken; done right it is invisible. The pattern below is the one running this site''s own search box, unchanged for two years.</p><h2>Direct Answer</h2><p>Keep the input controlled and instant — never debounce the keystroke itself. Debounce a copy of the value with a <code>useEffect</code> plus <code>setTimeout</code>, returning a cleanup that clears the timer on every keystroke. Fire the request off the debounced value. Three hundred milliseconds is the right default: fast enough to feel live, slow enough to collapse a whole word into one request. Below 200ms the savings vanish; above 500ms users start hammering Enter because they assume it broke.</p><h2>Full Code Example</h2><pre><code>function useDebouncedValue(value, delay = 300) { const [debounced, setDebounced] = useState(value); useEffect(() =&gt; { const id = setTimeout(() =&gt; setDebounced(value), delay); return () =&gt; clearTimeout(id); // cancels the pending timer on every keystroke }, [value, delay]); return debounced; } function Search() { const [query, setQuery] = useState(""); const [results, setResults] = useState([]); const debouncedQuery = useDebouncedValue(query); useEffect(() =&gt; { if (!debouncedQuery.trim()) { setResults([]); return; } const ctrl = new AbortController(); fetch("/api/search?q=" + encodeURIComponent(debouncedQuery), { signal: ctrl.signal }) .then((r) =&gt; r.json()) .then(setResults) .catch((e) =&gt; { if (e.name !== "AbortError") console.error(e); }); return () =&gt; ctrl.abort(); }, [debouncedQuery]); return &lt;input value={query} onChange={(e) =&gt; setQuery(e.target.value)} placeholder="Search" /&gt;; }</code></pre><h2>Why This Works</h2><p>The cleanup function is the mechanism. On every render where <code>query</code> changed, React runs the previous cleanup first — clearing the pending timer before a new one is set. Type five characters inside 300ms and four timers die before firing; only the last survives. The <code>AbortController</code> handles the remaining race: even debounced requests can resolve out of order when the user edits after a pause, so each effect run cancels its predecessor''s fetch. The hook shape matters too: keeping the timer inside a reusable hook means the debounce logic is written once and never re-copied with subtle mutations.</p><h2>Common Mistakes</h2><ul><li>Debouncing <code>onChange</code> itself — the input now lags 300ms behind every keystroke and feels dead.</li><li>Creating the debounced function inline in render — a new function every render defeats the memoisation — wrap it in <code>useMemo</code> or use the hook form above.</li><li>Forgetting the cleanup, so the stale timer fires after the value has already moved on.</li><li>Debouncing but skipping the abort — two requests in flight, and the slower one wins.</li></ul><h2>Browser Support / Caveats</h2><p>Nothing browser-specific here; this is pure React. For expensive rendering rather than network calls, React 18''s <code>useDeferredValue</code> is the better tool — it keeps the input snappy while the result list catches up, with no timer involved at all. One edge case worth handling either way: clear the results when the query is emptied, or the last result set lingers under an empty box.</p><h2>Related Resources</h2><p>The race-condition half of this pattern is covered in <a href="/blog/fetch-race-conditions-abortcontroller">Fetch Race Conditions</a>, and a production search box lives in the <a href="/components">component library</a>.</p>', 'Isaya Masika', 'published', '2027-01-05');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('css-transition-display-none', 'Why Doesn''t My CSS Transition Work With display: none?', 'css-transition-display-none', 'CSS', 'display is discrete — no intermediate states exist to interpolate. Transition opacity plus visibility instead, or use transition-behavior: allow-discrete with @starting-style in modern browsers.', '<p>You transition opacity, flip <code>display: none</code> to <code>display: block</code>, and the element pops in instantly. The transition is not broken — <code>display</code> was never animatable, and an unrendered element has no box to transition from. Every developer hits this within their first year of CSS, usually on a dropdown menu.</p><h2>Direct Answer</h2><p><code>display</code> is a discrete property: an element is either rendered or not, with no intermediate states for the browser to interpolate. The classic fix is to transition <code>opacity</code> and gate interaction with <code>visibility</code>, which is animatable when paired with a delay. The modern fix — now in all evergreen browsers — is listing <code>display</code> in the transition with <code>allow-discrete</code>, plus <code>@starting-style</code> to supply the entry frame. Visibility has a bonus property of its own: it interpolates discretely, which is exactly what makes the delay trick below legal.</p><h2>Full Code Example</h2><pre><code>/* Classic: fade works in both directions, element stays in the layout */ .panel { opacity: 1; visibility: visible; transition: opacity 200ms ease; } .panel.hidden { opacity: 0; visibility: hidden; transition: opacity 200ms ease, visibility 0s linear 200ms; } /* Modern: a real display: none, still animated */ .popover { display: block; opacity: 1; transition: opacity 200ms ease, display 200ms ease allow-discrete; } .popover.closed { display: none; opacity: 0; } /* Entry animation needs a starting frame, since none existed before */ @starting-style { .popover { opacity: 0; } }</code></pre><h2>Why This Works</h2><p>In the classic pattern the element never leaves the layout — <code>visibility: hidden</code> removes it from hit-testing and paint while keeping the box, so opacity has something to animate. The delay trick (<code>visibility 0s 200ms</code>) holds the visible state until the fade finishes on the way out, and switches instantly on the way in. <code>allow-discrete</code> tells the browser to flip <code>display</code> at the end of the transition instead of refusing to start it, and <code>@starting-style</code> supplies the "from" values for an element that was rendered in the same frame. The grid-rows height trick follows the same philosophy: animate a track from <code>0fr</code> to <code>1fr</code> instead of begging <code>height: auto</code> to interpolate.</p><h2>Common Mistakes</h2><ul><li>Setting <code>display: none</code> and <code>opacity: 0</code> in the same frame — the browser batches them and no transition ever starts.</li><li>Forgetting the visibility delay, so the fading element still catches clicks on the way out.</li><li>Animating <code>height: auto</code> as the "fix" — a different discrete-value trap with its own workaround (grid-template-rows 0fr to 1fr).</li><li>Re-adding the same class mid-transition and expecting a restart; the computed value never changed, so nothing runs.</li></ul><h2>Browser Support / Caveats</h2><p><code>allow-discrete</code> and <code>@starting-style</code> landed across Chrome, Firefox and Safari through 2024 and 2025; ship the classic pattern as the baseline and layer the modern one behind <code>@supports</code>. Users with reduced motion enabled should get instant state changes — wrap the transitions accordingly. Worth knowing: the native <code>popover</code> attribute and <code>&lt;details&gt;</code> elements get discrete-animation handling for free in current browsers.</p><h2>Related Resources</h2><p>The full list of which properties transition cleanly is in <a href="/blog/css-transition-properties-list">CSS Transition Properties</a>, and animated disclosure components live in the <a href="/components">component library</a>.</p>', 'Isaya Masika', 'published', '2027-01-06');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-fetch-post-json', 'How Do I POST JSON With fetch in React?', 'react-fetch-post-json', 'React', 'method POST, a Content-Type: application/json header, and JSON.stringify on the body. Then check res.ok, because fetch only rejects on network failure — a 500 resolves successfully.', '<p>GET requests are copy-paste simple, which is why the first POST trips people up: the body needs serialising, the header needs declaring, and fetch''s definition of "error" is not what you expect.</p><h2>Direct Answer</h2><p>Three things make a JSON POST work: <code>method: "POST"</code>, a <code>Content-Type: application/json</code> header, and <code>JSON.stringify</code> on the body. Then one more thing makes it correct: checking <code>res.ok</code>, because fetch only rejects on network failure — a 500 with an HTML error page resolves "successfully" and will poison your <code>res.json()</code> call if you skip the check.</p><h2>Full Code Example</h2><pre><code>function RegisterForm() { const [state, setState] = useState({ loading: false, error: null }); async function handleSubmit(e) { e.preventDefault(); if (state.loading) return; // guard against double submit const form = new FormData(e.currentTarget); setState({ loading: true, error: null }); try { const res = await fetch("/api/register", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ email: form.get("email"), password: form.get("password"), }), }); const data = await res.json().catch(() =&gt; null); // covers non-JSON error pages if (!res.ok) throw new Error(data?.error || "Request failed: " + res.status); setState({ loading: false, error: null }); // success: redirect or update UI here } catch (err) { setState({ loading: false, error: err.message }); } } return ( &lt;form onSubmit={handleSubmit}&gt; &lt;input name="email" type="email" required /&gt; &lt;input name="password" type="password" required /&gt; &lt;button disabled={state.loading}&gt;{state.loading ? "Saving..." : "Register"}&lt;/button&gt; {state.error &amp;&amp; &lt;p role="alert"&gt;{state.error}&lt;/p&gt;} &lt;/form&gt; ); }</code></pre><h2>Why This Works</h2><p><code>JSON.stringify</code> turns the object into a string body; without it fetch sends the literal text <code>[object Object]</code> and the server rejects it or, worse, silently stores garbage. The <code>Content-Type</code> header tells the server which parser to reach for — without it, frameworks read the body as raw text and the parsed body stays empty. The <code>res.ok</code> check exists because fetch''s promise rejects only when the request never completes; HTTP errors are normal responses and must be handled as data. The <code>.catch(() =&gt; null)</code> on <code>res.json()</code> covers the 502-from-a-proxy case where the body is HTML. Reading the payload via <code>FormData</code> is deliberate too: it captures the DOM once at submit time, so the inputs can stay uncontrolled and cheap.</p><h2>Common Mistakes</h2><ul><li>Sending the raw object as <code>body</code> — it arrives as the string <code>[object Object]</code>.</li><li>Declaring JSON but passing an already-serialised string, so the server receives double-encoded data.</li><li>Trusting <code>.catch</code> to catch 400s and 500s — it will not; check <code>res.ok</code>.</li><li>No double-submit guard, so a slow network creates two records — disabling the button is not optional polish.</li></ul><h2>Browser Support / Caveats</h2><p>If the endpoint is session-authenticated, add <code>credentials: "include"</code> or the cookies never leave the browser. Cross-origin POSTs with a JSON content type trigger a CORS preflight — the server must answer the OPTIONS request with the right headers before the real request is sent. For file uploads, skip JSON entirely: pass the <code>FormData</code> object as <code>body</code> and let fetch set the multipart boundary itself — manually adding a Content-Type there breaks the boundary.</p><h2>Related Resources</h2><p>The cookie detail is covered in <a href="/blog/fetch-credentials-include-cookies">fetch and credentials</a>, and the generalised version of this pattern is <a href="/blog/custom-fetch-hook">the useFetch hook</a>. Ready-made form components live in the <a href="/components">component library</a>.</p>', 'Isaya Masika', 'published', '2027-01-07');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('css-scroll-snap-carousel', 'How Do I Build a Carousel With CSS Scroll Snap?', 'css-scroll-snap-carousel', 'CSS', 'overflow-x: auto plus scroll-snap-type: x mandatory on the track, flex: 0 0 100% and scroll-snap-align: center on slides. Five lines of JS for the buttons; no library.', '<p>Carousel libraries ship hundreds of kilobytes to do what the browser has done natively since 2019: snap a scroll container to slide boundaries. For a straightforward image carousel, CSS scroll-snap plus five lines of JavaScript for the buttons is the whole implementation. Skip the library until you need infinite looping or autoplay — the two features scroll-snap genuinely cannot do. The result also survives hydration frameworks untouched, because the browser owns the behaviour end to end.</p><h2>Direct Answer</h2><p>Make the track a flex row with <code>overflow-x: auto</code> and <code>scroll-snap-type: x mandatory</code>. Size each slide to <code>flex: 0 0 100%</code> with <code>scroll-snap-align: center</code> (or <code>start</code> for partial-width slides). Scrolling — touch, wheel, trackpad or keyboard — now lands cleanly on one slide at a time, with momentum physics you did not have to write or polyfill. Hiding the scrollbar is optional but conventional for carousels; keep it for anything form-adjacent.</p><h2>Full Code Example</h2><pre><code>&lt;div class="carousel" id="track"&gt; &lt;div class="slide"&gt;&lt;img src="/a.webp" alt=""&gt;&lt;/div&gt; &lt;div class="slide"&gt;&lt;img src="/b.webp" alt=""&gt;&lt;/div&gt; &lt;div class="slide"&gt;&lt;img src="/c.webp" alt=""&gt;&lt;/div&gt; &lt;/div&gt; &lt;button id="prev"&gt;Previous&lt;/button&gt; &lt;button id="next"&gt;Next&lt;/button&gt; .carousel { display: flex; gap: 0; overflow-x: auto; scroll-snap-type: x mandatory; scroll-behavior: smooth; scrollbar-width: none; } .carousel::-webkit-scrollbar { display: none; } .slide { flex: 0 0 100%; scroll-snap-align: center; aspect-ratio: 16 / 9; } .slide img { width: 100%; height: 100%; object-fit: cover; } const track = document.getElementById("track"); document.getElementById("next").onclick = () =&gt; track.scrollBy({ left: track.clientWidth, behavior: "smooth" }); document.getElementById("prev").onclick = () =&gt; track.scrollBy({ left: -track.clientWidth, behavior: "smooth" });</code></pre><h2>Why This Works</h2><p><code>scroll-snap-type: x mandatory</code> tells the browser that after any scroll gesture ends, the container must settle on a snap point — the deceleration and rubber-banding stay native, which is why it feels right on iOS where JavaScript-driven carousels feel wrong. <code>flex: 0 0 100%</code> makes every slide exactly one viewport of the track, and the buttons just scroll by one track width; the snap points do the rest. Nothing here observes, measures or animates in JavaScript, so there is no jank to optimise. The <code>scroll-behavior: smooth</code> line is what makes the buttons glide rather than jump; gesture scrolling was already smooth natively.</p><h2>Common Mistakes</h2><ul><li>Margins on slides instead of <code>gap</code> — snap points land inside the margin and clip the content.</li><li><code>mandatory</code> on a desktop drag interface with partial-width slides; use <code>proximity</code> there so short drags do not fight the user.</li><li>Forgetting <code>flex: 0 0 100%</code>, so slides shrink, the track never overflows, and nothing scrolls or snaps.</li><li>Lazy-rendered slides changing width mid-scroll; reserve the space with <code>aspect-ratio</code>.</li></ul><h2>Browser Support / Caveats</h2><p>Scroll-snap is universal. A scrollbar hidden with <code>scrollbar-width: none</code> still scrolls via keyboard and Shift+wheel — keep the buttons visible for accessibility, and add dot indicators only if you also track scroll position, which is exactly where the JavaScript starts creeping back in. If you do need the active index, an IntersectionObserver on the slides is the cheapest reliable source — scroll-event arithmetic breaks under zoom and pixel rounding.</p><h2>Related Resources</h2><p>The same mechanism applied to navigation strips is in <a href="/blog/horizontal-scroll-strip-css">Horizontal Scroll Strips</a>, and the arrow icons for the buttons are in the <a href="/icons">icon library</a>.</p>', 'Isaya Masika', 'published', '2027-01-08');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('css-100vh-mobile-dvh', 'Why Is 100vh Taller Than the Screen on Mobile?', 'css-100vh-mobile-dvh', 'CSS', 'Mobile browsers size 100vh as if the URL bar were already hidden, so content sits under it. Use 100dvh with a 100vh fallback above it; use svh for anything pinned to the bottom.', '<p>Your hero section is exactly <code>100vh</code> tall, and on your phone the bottom button sits under the browser''s URL bar, unreachable. This is not your bug — <code>vh</code> on mobile deliberately includes the chrome that hides on scroll. The bug report always reads the same: works on desktop, cut off on my phone. The two-line fix below is what ships on this site.</p><h2>Direct Answer</h2><p>Mobile Safari and Chrome size <code>100vh</code> to the viewport as if the URL bar were already hidden, so content at the bottom lands underneath it. The fix shipped years ago: dynamic viewport units. Write the old value first as a fallback, then the new one — browsers that understand <code>dvh</code> take the second declaration, and the rest keep the first. For anything pinned to the bottom edge, use <code>svh</code> instead so the layout never moves while scrolling. No detection, no polyfill, no JavaScript.</p><h2>Full Code Example</h2><pre><code>.hero { min-height: 100vh; /* fallback for older browsers */ min-height: 100dvh; /* tracks the visible viewport as the URL bar hides */ } /* App shells with sticky bars: svh never changes, so nothing jumps */ .app { min-height: 100vh; min-height: 100svh; } /* Large viewport: the maximum space, URL bar assumed hidden (the old vh) */ .splash { min-height: 100lvh; }</code></pre><h2>Why This Works</h2><p>Three units, three behaviours. <code>lvh</code> (large) is the old <code>vh</code>: maximum space, assuming the chrome is hidden. <code>svh</code> (small) is the guaranteed-visible area with all chrome showing — it never changes as the user scrolls, so a footer pinned to it does not bounce. <code>dvh</code> (dynamic) tracks whichever is currently true, which is what a full-screen hero almost always wants. The fallback order matters: an old browser discards the declaration it cannot parse and keeps the valid one above it, so the legacy value must come first. A subtlety worth knowing: <code>dvh</code> recalculates during scroll, so an element sized in <code>dvh</code> grows smoothly as the bar collapses — usually desirable, occasionally a repaint cost on very long pages. Desktop never changes, because its chrome never hides.</p><h2>Common Mistakes</h2><ul><li>Writing <code>100dvh</code> without the <code>100vh</code> fallback — older browsers get no height at all.</li><li>Using <code>dvh</code> for a bottom-pinned toolbar; it resizes on every scroll and the bar bounces. Use <code>svh</code>.</li><li>Polyfilling with <code>window.innerHeight</code> in JavaScript — resize listeners, SSR mismatches and an extra repaint, all to avoid one line of CSS.</li><li>Setting <code>height</code> instead of <code>min-height</code>, so taller content overflows the hero instead of stretching it.</li></ul><h2>Browser Support / Caveats</h2><p>Dynamic viewport units need Safari 15.4, Chrome 108 or Firefox 101 — effectively universal by now, but the two-line fallback costs nothing. Desktop browsers treat all viewport units identically, so nothing changes there either way. Android Chrome and iOS Safari behave identically here, so there is no platform split to test — one rule covers both.</p><h2>Related Resources</h2><p>The same edge-of-screen thinking applied to notched phones is in <a href="/blog/safe-area-inset-css-notch">Safe Area Insets</a>, and full-height hero sections live in the <a href="/components">component library</a>.</p>', 'Isaya Masika', 'published', '2027-01-09');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-useeffect-runs-twice', 'Why Does My useEffect Run Twice in React 18?', 'react-useeffect-runs-twice', 'React', 'StrictMode double-invokes effects in development to surface missing cleanups. Production is unaffected. Fix the cleanup; never fix it by removing StrictMode.', '<p>You add a <code>console.log</code> inside an effect, watch it fire twice, and spend an hour hunting a duplicate render that does not exist. This is React 18''s StrictMode doing exactly what it was designed to do — and it only happens in development. It is the most reported "bug" against React 18, and it is entirely intentional.</p><h2>Direct Answer</h2><p>In development, StrictMode mounts every component, immediately unmounts it, and mounts it again — running each effect, its cleanup, and the effect once more. The point is to surface effects that break when they run twice: missing cleanups, subscriptions that accumulate, requests that double-fire. Production builds are unaffected. The fix is never to delete StrictMode; it is to write the cleanup the effect always needed. Think of the double-run as a unit test React executes for free on every effect you ship.</p><h2>Full Code Example</h2><pre><code>// Broken under StrictMode: the listener is added twice, removed never useEffect(() =&gt; { window.addEventListener("resize", onResize); }, []); // Fixed: the cleanup runs between the two dev invocations useEffect(() =&gt; { window.addEventListener("resize", onResize); return () =&gt; window.removeEventListener("resize", onResize); }, []); // Broken: two identical requests fire, the handler runs twice useEffect(() =&gt; { fetch("/api/user").then((r) =&gt; r.json()).then(setUser); }, []); // Fixed: the first invocation''s request is aborted before it resolves useEffect(() =&gt; { const ctrl = new AbortController(); fetch("/api/user", { signal: ctrl.signal }) .then((r) =&gt; r.json()) .then(setUser) .catch((e) =&gt; { if (e.name !== "AbortError") console.error(e); }); return () =&gt; ctrl.abort(); }, []);</code></pre><h2>Why This Works</h2><p>StrictMode''s double-invoke is a rehearsal for a real feature: React can unmount and remount a component while preserving its state — for offscreen rendering and for navigation that caches screens. An effect with a correct cleanup is indifferent to how many times it runs: mount adds the listener, cleanup removes it, remount adds it again, net effect one listener. An effect without a cleanup leaks on every cycle, and the development double-run makes that leak visible today instead of in production next year. Render bodies and reducers are double-invoked for the same reason — an impurity there corrupts output silently, and the second pass exposes it.</p><h2>Common Mistakes</h2><ul><li>Removing <code>&lt;StrictMode&gt;</code> from the root to stop the noise — you have disabled the smoke detector.</li><li>Adding a guard ref (<code>if (ran.current) return</code>) so the effect runs once; that breaks exactly the remount scenario StrictMode is rehearsing.</li><li>Treating the double fetch as noise to hide rather than a missing abort to add.</li><li>Assuming production behaves the same — it does not, so verify fixes against a production build before celebrating — a dev-only fix is not a fix.</li></ul><h2>Browser Support / Caveats</h2><p>Double-invocation applies to effects, render bodies and state updater functions, in development only, React 18 and later. If a third-party library breaks under StrictMode, the bug is in the library; wrap it behind a boundary effect with proper cleanup rather than opting the whole app out. React 19 kept the behaviour unchanged, so this is not going away.</p><h2>Related Resources</h2><p>The dependency rules that pair with this are in <a href="/blog/useeffect-dependencies">useEffect Dependencies</a> and <a href="/blog/useeffect-stale-closure-fix">Stale Closures</a>; cleanup-correct components live in the <a href="/components">component library</a>.</p>', 'Isaya Masika', 'published', '2027-01-10');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-accessible-modal-dialog', 'How to Build an Accessible Modal Dialog in React', 'react-accessible-modal-dialog', 'React', 'Use the native dialog element with showModal(): focus trapping, Escape handling and an inert background come free. Add a ref, aria-labelledby and a labelled close button — skip the hand-rolled focus trap.', '<p>Most hand-built React modals are one accessibility bug wearing three costumes: focus never enters the dialog, Tab walks out of it into the page behind, and Escape does nothing because nobody wired a keydown listener. All three come free if you stop rebuilding what the browser already ships.</p><h2>Direct Answer</h2><p>Render a native <code>&lt;dialog&gt;</code> element and open it with <code>showModal()</code>. That single call puts the dialog in the top layer, makes the rest of the page inert, traps focus inside, and wires Escape to close it. Your job shrinks to three things: hold a ref, label the dialog with <code>aria-labelledby</code>, and give the close button a real accessible name.</p><h2>Full Code Example</h2><pre><code>function Modal({ open, title, onClose, children }) {
  const ref = useRef(null);

  useEffect(() =&gt; {
    const el = ref.current;
    if (!el) return;
    if (open &amp;&amp; !el.open) el.showModal();
    if (!open &amp;&amp; el.open) el.close();
  }, [open]);

  return (
    &lt;dialog
      ref={ref}
      aria-labelledby="modal-title"
      onClose={onClose}
      onClick={(e) =&gt; {
        // Click on the backdrop targets the dialog itself, not its content
        if (e.target === ref.current) onClose();
      }}
    &gt;
      &lt;h2 id="modal-title"&gt;{title}&lt;/h2&gt;
      {children}
      &lt;button type="button" aria-label="Close dialog" onClick={onClose}&gt;
        ×
      &lt;/button&gt;
    &lt;/dialog&gt;
  );
}</code></pre><h2>Why This Works</h2><p><code>showModal()</code> is the difference between a dialog and a decorated div. In the top layer, the element paints above every z-index in the document, so no stacking-context fight is needed. Inertness is handled by the browser: elements behind the dialog stop receiving clicks and are removed from the accessibility tree, which is why the classic "focus escapes the modal" bug simply does not occur. Escape is a native cancel event, so you get keyboard dismissal without a listener.</p><h3>Focus return</h3><p>The browser stores the element that had focus before <code>showModal()</code> and restores it on close. That is the "return focus to the trigger" rule that every accessibility checklist asks for, already implemented. Do not steal focus on close yourself or you will fight it.</p><h3>Why aria-labelledby and not aria-label</h3><p>A screen reader announces the dialog''s name on open. Pointing at the visible heading keeps the announced name and the on-screen name in sync, so they cannot drift apart during edits.</p><h2>Packaging It as a Reusable Hook</h2><p>Once the pattern works, the next step is to stop repeating the effect. Pull the ref, the showModal and close calls, and the backdrop click into a small hook that returns the ref and the props the dialog needs. Every modal in the app then shares one behaviour, and there is a single place to add scroll locking.</p><h3>Scroll locking, the missing piece</h3><p>The top layer makes the page inert but does not stop it from scrolling. Set <code>overflow: hidden</code> on <code>document.documentElement</code> while the dialog is open, and restore the previous value on close. Store the old value rather than clearing it, because the page may already have a deliberate overflow rule.</p><h3>Testing checklist</h3><ul><li>Tab past the last focusable element: focus cycles to the first, never to the page behind.</li><li>Press Escape: the dialog closes and focus returns to the trigger.</li><li>Click the backdrop: it closes, but a click inside the panel does not.</li><li>Open with a screen reader: the dialog name is announced from the visible heading.</li><li>Zoom to 200 percent: the panel scrolls internally instead of pushing the page.</li></ul><h3>When not to use a modal</h3><p>A dialog interrupts. If the task can happen inline — expanding a row, revealing a form under a button — do that instead. Reserve modals for decisions that genuinely block the next step: confirming a destructive action, completing a checkout, or presenting a focused editor.</p><h3>Sizing and scrolling</h3><p>Give the dialog <code>max-width: min(92vw, 560px)</code> and <code>max-height: 85vh</code> with <code>overflow: auto</code> on the panel. Without a height cap a long form pushes the dialog past the viewport, and the close button becomes unreachable on a laptop with a short screen.</p><h2>Common Mistakes</h2><ul><li>Rendering a div with <code>role="dialog"</code> and calling it accessible. Without inertness and a focus trap it is a visual lie.</li><li>Using <code>display: none</code> toggling instead of <code>showModal()</code>. The dialog renders, but nothing else changes.</li><li>Mounting the dialog inside an ancestor with <code>overflow: hidden</code> and assuming it will clip. The top layer ignores that — but only with <code>showModal()</code>, not with the <code>open</code> attribute.</li><li>Forgetting to return focus when closing programmatically, so keyboard users land back at the top of the document.</li></ul><h2>Browser Support / Caveats</h2><p><code>&lt;dialog&gt;</code> is supported in Chrome 37+, Firefox 98+ and Safari 15.4+, which covers essentially all production traffic. On older Safari the element exists but <code>showModal()</code> is missing; feature-detect it and fall back to rendering the dialog inline with a manual focus trap. One styling note: the backdrop is a <code>::backdrop</code> pseudo-element, not a sibling div, so target it there rather than adding an overlay element.</p><h2>Related Resources</h2><p>For a real modal in production, open the <a href="/products/payment-checkout-modal">checkout modal component</a>. The keyboard-focus half of this problem is covered in <a href="/blog/css-focus-visible-hover-states">this article on focus states</a>, and the element''s full behaviour is documented on <a href="https://developer.mozilla.org/en-US/docs/Web/HTML/Element/dialog" rel="nofollow noopener" target="_blank">MDN</a>.</p><p><strong>Try it on SteaCode:</strong> a production-ready checkout dialog with focus handling is free to copy in the <a href="/products/payment-checkout-modal">component library</a>.</p>', 'Isaya Masika', 'published', '2027-01-11');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-toast-notification-component', 'How to Build a React Toast Notification Component', 'react-toast-notification-component', 'React', 'Keep a queue in a provider, render each toast in a portal on body, announce with role=status, and clear every timer on unmount. Toasts belong outside the component tree that triggered them.', '<p>Toasts look trivial until the first one renders behind a sticky header, gets clipped by an overflow container, or never disappears because its timer was orphaned on unmount. The fix is architecture, not styling: a queue that lives above the app, rendered through a portal.</p><h2>Direct Answer</h2><p>Create a provider that owns an array of toasts. A <code>useToast()</code> hook pushes new entries into it. Render the stack through <code>createPortal</code> into <code>document.body</code>, give the container <code>role="status"</code> with <code>aria-live="polite"</code>, and run one auto-dismiss timer per toast with cleanup. Every toast needs a stable id — a counter, not an index.</p><h2>Full Code Example</h2><pre><code>let nextId = 0;

export function ToastProvider({ children }) {
  const [toasts, setToasts] = useState([]);

  const dismiss = useCallback((id) =&gt; {
    setToasts((list) =&gt; list.filter((t) =&gt; t.id !== id));
  }, []);

  const push = useCallback((message, duration = 4000) =&gt; {
    const id = nextId++;
    setToasts((list) =&gt; [...list, { id, message }]);
    setTimeout(() =&gt; dismiss(id), duration);
    return id;
  }, [dismiss]);

  return (
    &lt;ToastContext.Provider value={{ push, dismiss }}&gt;
      {children}
      {createPortal(
        &lt;div className="toast-stack" role="status" aria-live="polite"&gt;
          {toasts.map((t) =&gt; (
            &lt;div key={t.id} className="toast"&gt;
              {t.message}
              &lt;button type="button" aria-label="Dismiss" onClick={() =&gt; dismiss(t.id)}&gt;×&lt;/button&gt;
            &lt;/div&gt;
          ))}
        &lt;/div&gt;,
        document.body
      )}
    &lt;/ToastContext.Provider&gt;
  );
}</code></pre><h2>Why This Works</h2><p>The portal is what makes toasts behave. Rendering into <code>body</code> means no ancestor can clip them with <code>overflow: hidden</code>, and no transform-created stacking context can bury them — the two bugs that account for most "my toast is invisible" reports. The queue lives in a provider so any component can raise a toast without prop drilling or a global variable.</p><h3>Live regions and timing</h3><p><code>role="status"</code> implies <code>aria-live="polite"</code>, so screen readers announce the message without interrupting the user''s current task. Reserve <code>assertive</code> for genuine errors. Announcements only fire when content changes inside an existing live region, so the container must be present in the DOM from the start — which this pattern guarantees, since it renders empty.</p><h3>Timers</h3><p>One timer per toast, keyed by id, means dismissing a toast manually cannot cancel somebody else''s timer. The classic alternative — a single interval comparing timestamps — desynchronises the moment a user closes one early.</p><h2>Queue Discipline: Duplicates, Stacking and Durations</h2><p>A working toast system is mostly policy. Without rules, an error loop fills the screen with forty identical messages and the user cannot see the page underneath. Decide four things before the first toast ships.</p><h3>Deduplicate by content</h3><p>If a toast with the same message is already visible, reset its timer instead of appending a second copy. Use the message as the key rather than the id, because the id exists only to satisfy React.</p><h3>Cap the stack</h3><p>Three visible toasts is the practical maximum. Push the oldest out when a fourth arrives, and keep the array bounded so a runaway loop cannot grow memory without limit.</p><h3>Durations by severity</h3><ul><li>Success: 3000 to 4000 milliseconds. Nothing needs action.</li><li>Informational: 5000 milliseconds. Longer to read, still dismisses itself.</li><li>Error: requires dismissal. Auto-dismissing an error hides the only explanation of what went wrong.</li></ul><h3>Position and safe areas</h3><p>Fix the stack to a corner with a high z-index, and add <code>env(safe-area-inset-bottom)</code> padding on mobile so the last toast is not under the home indicator. On a layout with a sticky footer, the stack must sit above the footer, not behind it.</p><h3>Errors should not auto-dismiss</h3><p>A success message can disappear because the user already knows what happened. An error cannot: it is the only record of the failure, and dismissing it after four seconds guarantees the user loses the reason. Errors stay until dismissed, and a retry action belongs inside the toast rather than in a console. If errors can repeat, deduplicate by message so a failed poll does not bury the page in identical red boxes. Pair the retry with the same id so the whole group clears in one click.</p><h2>Common Mistakes</h2><ul><li>Rendering the toast next to the triggering button. It inherits every clipping and stacking rule of that subtree.</li><li><code>aria-live="assertive"</code> on a success message; it interrupts whatever the user was reading.</li><li>Storing timers in state, so clearing them on unmount becomes guesswork and streams of orphaned callbacks fire into a dead component.</li><li>Using the array index as the React key. Dismissing toast one re-keys the rest and restarts their transitions.</li></ul><h2>Browser Support / Caveats</h2><p>Portals and live regions are universally supported; nothing here is version-sensitive. Do respect <code>prefers-reduced-motion</code> — a slide-in toast is decorative, and the message is the point. Keep simultaneous toasts to three or fewer; beyond that the stack becomes a wall the user cannot dismiss fast enough.</p><h2>Related Resources</h2><p>An alert component using the same announcement pattern is free in the library: <a href="/products/dark-error-alert">dark error alert</a>. The timer-cleanup discipline is the same one in <a href="/blog/react-async-setstate-after-unmount">avoiding setState after unmount</a>, and portals are documented at <a href="https://react.dev/reference/react-dom/createPortal" rel="nofollow noopener" target="_blank">react.dev</a>.</p><p><strong>Try it on SteaCode:</strong> copy a ready-made alert surface at <a href="/products/dark-error-alert">dark error alert</a> and drop the provider around your app.</p>', 'Isaya Masika', 'published', '2027-01-12');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('accessible-react-tabs-with-aria', 'Building an Accessible Tabs Component in React with ARIA', 'accessible-react-tabs-with-aria', 'React', 'One tab in the tab order, arrow keys move between tabs, role=tablist/tab/tabpanel, aria-selected plus aria-controls. A div with onClick gives keyboard users nothing.', '<p>Tabs are the most commonly broken interactive pattern on the web. Sighted mouse users see working tabs; keyboard users see a row of text that does nothing, and screen reader users hear three unlabelled buttons with no relationship to the panel underneath. The ARIA tabs pattern fixes all of it with about twenty lines.</p><h2>Direct Answer</h2><p>Give the list <code>role="tablist"</code>, each button <code>role="tab"</code>, and each panel <code>role="tabpanel"</code>. Only the selected tab carries <code>tabIndex={0}</code> — every other tab is <code>-1</code>, the roving tabindex pattern. Arrow keys move both selection and focus; Home and End jump to the ends. Each tab sets <code>aria-selected</code> and points at its panel with <code>aria-controls</code>, and each panel is labelled by its tab with <code>aria-labelledby</code>.</p><h2>Full Code Example</h2><pre><code>function Tabs({ items }) {
  const [active, setActive] = useState(0);
  const refs = useRef([]);

  function onKeyDown(e, index) {
    const last = items.length - 1;
    let next = null;
    if (e.key === "ArrowRight") next = index === last ? 0 : index + 1;
    if (e.key === "ArrowLeft") next = index === 0 ? last : index - 1;
    if (e.key === "Home") next = 0;
    if (e.key === "End") next = last;
    if (next === null) return;
    e.preventDefault();
    setActive(next);
    refs.current[next].focus();
  }

  return (
    &lt;&gt;
      &lt;div role="tablist" aria-label="Sections"&gt;
        {items.map((item, i) =&gt; (
          &lt;button
            key={item.id}
            ref={(el) =&gt; (refs.current[i] = el)}
            role="tab"
            id={"tab-" + item.id}
            aria-selected={active === i}
            aria-controls={"panel-" + item.id}
            tabIndex={active === i ? 0 : -1}
            onClick={() =&gt; setActive(i)}
            onKeyDown={(e) =&gt; onKeyDown(e, i)}
          &gt;
            {item.label}
          &lt;/button&gt;
        ))}
      &lt;/div&gt;
      {items.map((item, i) =&gt; (
        &lt;div
          key={item.id}
          role="tabpanel"
          id={"panel-" + item.id}
          aria-labelledby={"tab-" + item.id}
          hidden={active !== i}
        &gt;
          {item.content}
        &lt;/div&gt;
      ))}
    &lt;/&gt;
  );
}</code></pre><h2>Why This Works</h2><p>The roving tabindex is the key idea. With every tab focusable, Tab walks through all of them and a keyboard user must press it four times to leave a tab strip — and the strip competes for tab stops with real content. With one focusable tab, Tab enters the strip once, arrow keys move within it, and Tab exits to the panel. That is the interaction every native tab widget has had for decades.</p><h3>Wiring with ids, not proximity</h3><p><code>aria-controls</code> and <code>aria-labelledby</code> create the tab-panel relationship explicitly, so screen readers announce the panel as belonging to the selected tab. Ordering alone is not a relationship and is not announced.</p><h3>Hiding panels correctly</h3><p>The <code>hidden</code> attribute removes inactive panels from both the layout and the accessibility tree in one step. CSS-only hiding that leaves the panel technically rendered keeps it announceable, which confuses screen reader users navigating by region.</p><h2>Vertical Tabs, Disabled Tabs and Dynamic Panels</h2><p>The horizontal example covers most cases. Three variations need explicit treatment, and each has one rule that is easy to miss.</p><h3>Vertical orientation</h3><p>Add <code>aria-orientation="vertical"</code> to the tablist and map ArrowUp and ArrowDown instead of Left and Right. Without the attribute, screen readers describe the widget as horizontal and announce the wrong keys.</p><h3>Disabled tabs</h3><p>Use <code>aria-disabled="true"</code> and keep the tab focusable rather than the <code>disabled</code> attribute. A disabled element leaves the tab order, so keyboard users cannot discover why the section is unavailable. Announce the reason through an inline note, and skip disabled tabs when moving with arrows.</p><h3>Dynamic panel content</h3><p>Panels that load data should stay mounted with a loading state, not unmount on every switch. Remounting cancels in-flight requests and resets scroll position, which reads as a bug. If a panel is genuinely expensive, mount it on first activation and keep it afterwards.</p><h3>A quick visual check</h3><ul><li>Selection follows arrow keys and focus moves with it.</li><li>Tab leaves the strip in a single press.</li><li>The active panel is the only one exposed to assistive technology.</li></ul><h3>Styling the selected tab without breaking semantics</h3><p>Style from <code>aria-selected</code>, not from a separate <code>is-active</code> class. One state, one attribute, and the visual and the announced state cannot disagree. The underline can be a pseudo-element that scales on the same attribute.</p><h2>Common Mistakes</h2><ul><li>Starting from divs with <code>onClick</code>: not focusable, not announced, no keyboard path.</li><li>Leaving every tab tabbable, so navigating past the strip costs one Tab press per tab.</li><li>Selection without focus. Arrow keys must move focus and selection together, or screen reader users lose their place.</li><li>Missing ids, leaving <code>aria-controls</code> pointing at nothing — silently broken, never reported.</li></ul><h2>Browser Support / Caveats</h2><p>ARIA roles and roving tabindex work everywhere. Use buttons for tabs rather than links, since these change state rather than navigate. If a tab triggers a network fetch, remember it is a state change — keep the panel mounted with a loading state instead of remounting on every switch.</p><h2>Related Resources</h2><p>The segmented-control look is already available as a component: <a href="/products/light-dark-theme-switch">light / dark theme switch</a>. Focus styling is covered in <a href="/blog/css-focus-visible-hover-states">this article</a>, and the full pattern is specified in the <a href="https://www.w3.org/WAI/ARIA/apg/patterns/tabs/" rel="nofollow noopener" target="_blank">WAI-ARIA Authoring Practices</a>.</p><p><strong>Try it on SteaCode:</strong> a segmented toggle built on the same keyboard model is free at <a href="/products/light-dark-theme-switch">light / dark theme switch</a>.</p>', 'Isaya Masika', 'published', '2027-01-13');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-usememo-vs-usecallback', 'useMemo vs useCallback: Which One Do You Actually Need?', 'react-usememo-vs-usecallback', 'React', 'useMemo caches a computed value; useCallback caches a function''s identity. They are the same primitive — useCallback(fn, deps) equals useMemo(() => fn, deps) — and neither makes rendering faster on its own.', '<p>These two hooks get wrapped around everything in codebases that have been told "memoization is performance", then the app is still slow. They solve a narrower problem than their names suggest, and knowing exactly which problem saves you from sprinkling them everywhere.</p><h2>Direct Answer</h2><p>Use <code>useMemo</code> when you want to avoid re-running an expensive computation and keep the same result object when the inputs have not changed. Use <code>useCallback</code> when you want the same function reference across renders, usually because a child is memoized with <code>React.memo</code> or a function is an effect dependency. They are the same mechanism: <code>useCallback(fn, deps)</code> is exactly <code>useMemo(() =&gt; fn, deps)</code>. If neither referential stability nor computation cost applies, you need neither.</p><h2>Full Code Example</h2><pre><code>// useMemo: skip an expensive derivation
const sorted = useMemo(
  () =&gt; rows.slice().sort((a, b) =&gt; a.price - b.price),
  [rows]
);

// useCallback: stable handler for a memoized child
const onSelect = useCallback((id) =&gt; setSelected(id), []);

const RowList = React.memo(function RowList({ rows, onSelect }) {
  return rows.map((r) =&gt; (
    &lt;button key={r.id} onClick={() =&gt; onSelect(r.id)}&gt;{r.name}&lt;/button&gt;
  ));
});

// Not every handler needs this. A plain inline arrow is fine:
&lt;button onClick={() =&gt; setOpen(true)}&gt;Open&lt;/button&gt;</code></pre><h2>Why This Works</h2><p>React compares values with <code>Object.is</code>. An inline arrow function is a new object every render, so a <code>React.memo</code> child receives a "changed" prop and re-renders even when nothing meaningful changed. Wrapping the handler in <code>useCallback</code> preserves the reference across renders, and the memo boundary finally does its job. <code>useMemo</code> plays the same trick for objects and arrays, which are also compared by reference.</p><h3>What memoization actually costs</h3><p>Every memo hook allocates a dependency array, compares entries on each render, and keeps a cached value alive. On a cheap computation — summing eight numbers, building a string — that overhead can exceed the work saved. Memoize when the work is measurable or when identity is load-bearing.</p><h3>The dependency trap</h3><p>Memoization is only as stable as its dependencies. Pass <code>[{ id }]</code> as a dep and the cached value is thrown away every render, because a fresh object literal is a new reference. Depend on primitives (<code>[id]</code>) or hoist the object out of the component.</p><h2>Measure Before You Memoise</h2><p>Memoisation is an optimisation, and optimisations need a number. A three-step workflow keeps the codebase honest, and skipping the first step is why teams end up with a maze of hooks that changed nothing.</p><h3>Step one: find the slow render</h3><p>The React DevTools profiler ranks components by self time. If the component you are about to memoise is not near the top, the hook is cosmetic. Open the flame graph, sort by time, and confirm the work is real.</p><h3>Step two: check what re-renders</h3><p>Take a render that should not have happened. If the child renders because its parent does, <code>React.memo</code> on the child is the fix. If it renders because a prop object is new, stabilise that object. Only then consider <code>useCallback</code> on the handler the child receives.</p><h3>Step three: verify the improvement</h3><p>Measure the same interaction again. A memo that shaves two milliseconds is noise; one that removes a 30 millisecond sort from every keystroke is worth the indirection. Record the before and after in the pull request so the next reader knows why the hook exists.</p><h3>Where memoisation genuinely pays</h3><ul><li>Sorting or filtering lists of a few hundred rows on every render.</li><li>Chart data transformed into series objects.</li><li>Handlers passed into a virtualised list that re-renders per scroll frame.</li><li>Context values that would otherwise force every consumer to update.</li></ul><h3>The one-line rule</h3><p>If you cannot name what the memo avoids — a sort, a map, a new object identity — do not add it. A hook whose purpose cannot be stated in one sentence is dead weight that every future reader has to reason about. Delete it and measure again; usually nothing changes. Memoisation that survives refactors is the one with a comment explaining the measurement that justified it.</p><h2>Common Mistakes</h2><ul><li>Wrapping every function in <code>useCallback</code> with no memoized consumer. The reference is stable, but nothing is watching it.</li><li>Memoizing cheap work and calling it an optimisation.</li><li>Inline object or array dependencies, defeating the cache invisibly.</li><li>Using <code>useMemo</code> to avoid a re-render. It caches a value; it does not stop renders.</li></ul><h2>Browser Support / Caveats</h2><p>Pure React, no compatibility concerns. Since React 19 the compiler can insert memoization automatically, which changes the calculus: write the straightforward code and let the compiler do it, keeping manual <code>useMemo</code> only for genuinely expensive work. Until you are on that version, the rule of thumb holds — measure first, then memoize.</p><h2>Related Resources</h2><p>A component where per-frame computation genuinely matters: <a href="/products/countup-animated-number">animated count-up</a>. The freshness problem behind most stale memo values is explained in <a href="/blog/react-usestate-not-updating-immediately">useState not updating immediately</a>, and the API is specified at <a href="https://react.dev/reference/react/useMemo" rel="nofollow noopener" target="_blank">react.dev</a>.</p><p><strong>Try it on SteaCode:</strong> the <a href="/products/countup-animated-number">animated count-up component</a> memoises its frame work — free to copy.</p>', 'Isaya Masika', 'published', '2027-01-14');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('tailwind-dark-mode-class-strategy', 'Tailwind Dark Mode: The Class Strategy Done Right', 'tailwind-dark-mode-class-strategy', 'Tailwind', 'Set darkMode: ''class'', toggle the class on html with an inline script before paint, and pair it with color-scheme. Without the config change, dark: variants follow the OS and users cannot override them.', '<p>Tailwind dark mode fails in one of two ways: the <code>dark:</code> variants ignore the toggle entirely, or they work but the page flashes white for a frame on every load. Both are config problems, and both are fixed in under ten lines.</p><h2>Direct Answer</h2><p>Set <code>darkMode: "class"</code> in the Tailwind config. Toggle a <code>dark</code> class on <code>html</code>, not on a wrapper div, so it applies to portals and the document background alike. Add a small inline script in the document head that reads the stored preference and applies the class before the first paint. Also set <code>color-scheme</code> so form controls, scrollbars and the canvas match the theme.</p><h2>Full Code Example</h2><pre><code>// tailwind.config.js
module.exports = {
  darkMode: "class",
  content: ["./index.html", "./src/**/*.{js,jsx,ts,tsx}"],
};

// index.html — runs before paint, so no flash
&lt;script&gt;
  (function () {
    var stored = localStorage.getItem("theme");
    var dark = stored ? stored === "dark"
      : window.matchMedia("(prefers-color-scheme: dark)").matches;
    if (dark) document.documentElement.classList.add("dark");
    document.documentElement.style.colorScheme = dark ? "dark" : "light";
  })();
&lt;/script&gt;

// A component using the variant
&lt;section class="bg-white text-gray-900 dark:bg-gray-950 dark:text-gray-100"&gt;
  &lt;h2 class="text-lg font-semibold"&gt;Dashboard&lt;/h2&gt;
&lt;/section&gt;</code></pre><h2>Why This Works</h2><p>The <code>class</code> strategy compiles <code>dark:*</code> utilities into <code>.dark &amp; { ... }</code>, so a single class on the root element flips every variant at once. The default <code>media</code> strategy compiles to <code>@media (prefers-color-scheme: dark)</code>, which follows the operating system and leaves the user no in-page control — that is why "my dark mode toggle does nothing" is almost always a missing config line.</p><h3>Why the inline script, not a React effect</h3><p>A React effect runs after hydration, which is after the first paint. On a slow connection the user sees a white page, then a dark one. The inline script runs synchronously in the head, before any content is painted, so the correct theme exists from frame one. It is also the only place that can read <code>localStorage</code> safely before React mounts.</p><h3>color-scheme, the finishing touch</h3><p>Setting <code>color-scheme</code> instructs the browser to render native UI in the matching theme: scrollbars, default form controls, the overscroll background. Without it you get a dark page with a bright white scrollbar and glaring autofill fields.</p><h2>A Three-State Toggle That Survives Navigation</h2><p>Two states, light and dark, sound simpler than they are, because they drop the user''s actual preference: following the operating system. The durable model has three values, and the difference shows up the moment the OS changes at sunset.</p><h3>Storing system as a first-class value</h3><p>Store <code>light</code>, <code>dark</code> or <code>system</code> under one key. When the stored value is <code>system</code>, read <code>prefers-color-scheme</code> each time the theme is applied instead of freezing the answer at the moment of selection. A user who chose system expects the page to follow the OS later.</p><h3>Reacting to an OS change live</h3><p>Subscribe to the media query with <code>matchMedia</code> and re-apply the theme when it flips. This is rare in practice but jarring when missing: the page stays light at night until a reload.</p><h3>Multi-tab consistency</h3><p>Two tabs, two toggles, one stored value. Listen for the <code>storage</code> event and re-read the preference so a change in one tab updates the others. Without it the second tab silently reverts on the next navigation.</p><h3>Keeping portals in sync</h3><p>Because the class lives on <code>html</code>, a dialog or toast rendered into <code>body</code> inherits the theme with no extra wiring. That is the practical reason for the root-element rule, beyond the simpler one: the document background must change too.</p><h3>Route changes and the flash</h3><p>In a single-page app the theme survives navigation because the class lives on <code>html</code>. The flash only returns if a route remounts the document, which it should not. On a full reload the inline script runs again, so the stored value must be readable synchronously and never behind an async call.</p><h2>Common Mistakes</h2><ul><li>Forgetting <code>darkMode: "class"</code>, then blaming the markup when variants track the OS.</li><li>Putting the class on <code>&lt;body&gt;</code> or a wrapper: portals rendered into body escape it and stay light.</li><li>Toggling from a React effect, producing a one-frame flash on every navigation.</li><li>Hard-coding greys in both themes instead of one semantic pair per surface, so every new component needs two more classes.</li></ul><h2>Browser Support / Caveats</h2><p><code>prefers-color-scheme</code> and <code>color-scheme</code> are broadly available; Safari needed 13+ for the media feature and 16.4+ for full <code>color-scheme</code> behaviour. In Tailwind 4 the config moves into CSS with <code>@custom-variant dark</code>, but the class-on-html mechanics are unchanged. Store the preference as <code>"dark" | "light" | "system"</code> and let <code>"system"</code> fall back to the media query.</p><h2>Related Resources</h2><p>A themed surface built this way is free at <a href="/products/dark-login-form">dark login form</a>. The three-state toggle mechanics live in <a href="/blog/dark-mode-triple-state-toggle">light / dark / system toggle</a>, and the config option is documented at <a href="https://tailwindcss.com/docs/dark-mode" rel="nofollow noopener" target="_blank">tailwindcss.com</a>.</p><p><strong>Try it on SteaCode:</strong> a dark-first form that pairs cleanly with the class strategy is free at <a href="/products/dark-login-form">dark login form</a>.</p>', 'Isaya Masika', 'published', '2027-01-15');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('tailwind-group-and-peer-modifiers', 'How to Use Tailwind group and peer Modifiers', 'tailwind-group-and-peer-modifiers', 'Tailwind', 'group styles a child from an ancestor''s state; peer styles a later sibling from an earlier sibling''s state. Peer must come first in the DOM — that ordering rule catches everyone once.', '<p>Hovering a card and lighting up its title, or checking a checkbox and revealing a panel, normally means writing custom CSS for a parent-child or sibling relationship. Tailwind ships both relationships as modifiers, and the only real trap is a DOM-ordering rule that fails silently.</p><h2>Direct Answer</h2><p><code>group</code> goes on an ancestor; children use <code>group-hover:</code>, <code>group-focus:</code>, <code>group-data-*:</code> and friends to react to that ancestor''s state. <code>peer</code> goes on an earlier sibling; later siblings style themselves with <code>peer-checked:</code>, <code>peer-focus:</code>, <code>peer-invalid:</code> or <code>peer-placeholder-shown:</code>. Both use plain CSS combinators under the hood — descendant for group, general sibling for peer — so no JavaScript is involved.</p><h2>Full Code Example</h2><pre><code>&lt;!-- group: the whole card responds to hover --&gt;
&lt;a class="group block rounded-xl border p-5 hover:border-amber-400"&gt;
  &lt;h3 class="font-semibold text-gray-900 group-hover:text-amber-600"&gt;Docs&lt;/h3&gt;
  &lt;span class="text-gray-500 group-hover:translate-x-1 transition"&gt;→&lt;/span&gt;
&lt;/a&gt;

&lt;!-- peer: sibling-based toggle. Input MUST come first. --&gt;
&lt;div class="space-y-2"&gt;
  &lt;input id="terms" type="checkbox" class="peer sr-only" /&gt;
  &lt;label for="terms"
    class="inline-flex rounded-lg border px-4 py-2 peer-checked:bg-amber-500 peer-checked:text-white"
  &gt;
    Accept terms
  &lt;/label&gt;
  &lt;p class="hidden peer-checked:block text-sm text-gray-600"&gt;
    Thanks — you can continue.
  &lt;/p&gt;
&lt;/div&gt;

&lt;!-- Named groups when several nest --&gt;
&lt;div class="group/card ..."&gt;
  &lt;div class="group/row ..."&gt;
    &lt;span class="group-hover/row:underline group-hover/card:opacity-100"&gt;·&lt;/span&gt;
  &lt;/div&gt;
&lt;/div&gt;</code></pre><h2>Why This Works</h2><p>The <code>group</code> variant compiles to <code>.group:hover &amp; .child</code>, a descendant selector, so any depth below the group matches. The <code>peer</code> variant compiles to <code>.peer:checked ~ &amp;.sibling</code>, the general sibling combinator, which only matches elements later in the same parent. That single character of CSS is why a checkbox has to precede the thing it styles.</p><h3>Named groups</h3><p><code>group/card</code> plus <code>group-hover/card:</code> scopes the state to a specific ancestor. Without names, nested groups all match the nearest unnamed group, and an outer hover accidentally triggers inner styles. Names are the fix for nested interactive surfaces.</p><h3>Why not JavaScript</h3><p>Because these are state selectors the browser already tracks: hover, focus, checked, disabled, invalid, placeholder visibility. A React state flag re-implements the same information one render later and costs a re-render.</p><h2>Compound States and Accessibility-Driven Variants</h2><p>These modifiers get more useful once you combine them with state that comes from ARIA rather than CSS pseudo-classes. Tailwind supports both, and mixing them produces patterns plain hover utilities cannot express.</p><h3>Stacking variants</h3><p>A single class can chain conditions: <code>md:group-hover:text-amber-600</code> restricts the effect to a breakpoint. Tailwind composes them into one media query wrapping one state selector, so the output stays small.</p><h3>ARIA and data variants</h3><p><code>aria-expanded:</code> and <code>data-open:</code> let the CSS follow the same attribute the accessibility tree exposes. An accordion that sets <code>aria-expanded</code> on its trigger can style the chevron with <code>aria-expanded:rotate-180</code> — one source of truth for screen readers and sighted users.</p><h3>Group with a form field</h3><p>A labelled input wrapper can react to its child''s focus and validity: <code>group</code> on the wrapper, then <code>group-focus-within:border-amber-400</code> or <code>group-has-[input:invalid]:ring-red-300</code>. The <code>:has()</code> selector is broadly available now and removes the need for a focus handler in React.</p><h3>The one ordering rule to remember</h3><p>Peer selectors only look forward. If a checkbox controls content above it in the DOM, no Tailwind class will reach it. Restructure the markup, or use React state. That constraint is the whole reason the pattern is documented with input first.</p><h3>Debugging a modifier that does nothing</h3><p>Four causes cover it. The <code>group</code> class is on a descendant instead of an ancestor. The peer element comes after its target. The variant is applied to something outside the same parent. Or a framework serialises your class into a wrapper you did not expect. Inspect the generated selector in DevTools: if it is not <code>.group:hover .child</code> or <code>.peer:checked ~ .sibling</code>, the markup is wrong, not the utility. Check also that the base class exists in the output CSS, because a class assembled from a string at runtime is invisible to the scanner and silently missing.</p><p>One last gotcha: groups cannot be nested without names, and a named group is invisible unless the child spells out the same name. Audit nested cards by hovering the outer one and confirming the inner styles stay untouched.</p><h2>Common Mistakes</h2><ul><li>Putting <code>peer</code> on the element after the one it should style. The sibling combinator only looks forward.</li><li>Applying <code>peer-*</code> to a descendant. Peers are siblings only — use a group for descendants.</li><li>Nesting unnamed groups, so hovering anything lights up everything.</li><li>Using <code>group-hover</code> on touch devices, where hover is either absent or sticky. Pair it with a focus state.</li></ul><h2>Browser Support / Caveats</h2><p>Both modifiers ship as ordinary selectors and need nothing beyond CSS support. The one requirement is that <code>:focus-visible</code>, <code>:placeholder-shown</code> and <code>:checked</code> are supported — universal in current browsers. On touch devices prefer <code>group-active:</code> or an <code>aria-checked</code>-driven <code>data-*</code> attribute, which survives both mouse and keyboard activation.</p><h2>Related Resources</h2><p>A switch built entirely on <code>peer-checked</code> is free at <a href="/products/animated-toggle-switch">animated toggle switch</a>. The keyboard-focus side of interactive states is covered in <a href="/blog/css-focus-visible-hover-states">this article</a>, and the modifier list lives at <a href="https://tailwindcss.com/docs/hover-focus-and-other-states" rel="nofollow noopener" target="_blank">tailwindcss.com</a>.</p><p><strong>Try it on SteaCode:</strong> copy the <a href="/products/animated-toggle-switch">animated toggle switch</a> — it is a peer-checked pattern with no JavaScript.</p>', 'Isaya Masika', 'published', '2027-01-16');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('tailwind-arbitrary-values', 'Tailwind Arbitrary Values: When to Use Them and When Not To', 'tailwind-arbitrary-values', 'Tailwind', 'Square brackets inject any value: w-[317px], bg-[#1a1a1a], grid-cols-[160px_1fr_300px]. Underscores replace spaces. They are an escape hatch, not a design system — overuse is how a codebase loses consistency.', '<p>Tailwind''s scale is the product. The moment you need a value that is not on the scale — a grid template from a design mock, an exact hex from a brand guide — the bracket syntax gets you there without writing custom CSS. The skill is knowing how often to reach for it.</p><h2>Direct Answer</h2><p>Wrap the value in square brackets: <code>w-[317px]</code>, <code>bg-[#1a1a1a]</code>, <code>grid-cols-[160px_1fr_300px]</code>, <code>top-[calc(100%-8px)]</code>. Replace spaces with underscores, because spaces terminate the class name. Prefix with a type hint when the value is ambiguous, as in <code>text-[length:15px]</code> or <code>bg-[image:url(...)]</code>. If a value repeats across three or more components, it belongs in the theme, not in brackets.</p><h2>Full Code Example</h2><pre><code>&lt;!-- Exact track widths from a layout spec --&gt;
&lt;div class="grid grid-cols-[160px_1fr_300px] gap-8"&gt;...&lt;/div&gt;

&lt;!-- Brand colour that is not in the palette --&gt;
&lt;a class="bg-[#0b1020] text-[#f5b400] hover:bg-[#161c33]"&gt;Link&lt;/a&gt;

&lt;!-- Values Tailwind has no utility for --&gt;
&lt;div class="max-h-[calc(100vh-4rem)] overflow-y-auto"&gt;...&lt;/div&gt;
&lt;div class="[mask-image:linear-gradient(to_bottom,black,transparent)]"&gt;...&lt;/div&gt;

&lt;!-- Type hint: an arbitrary property that is ambiguous --&gt;
&lt;span class="text-[length:clamp(1rem,2.5vw,1.5rem)]"&gt;Fluid&lt;/span&gt;</code></pre><h2>Why This Works</h2><p>Tailwind parses a class containing brackets as literal CSS, generating exactly what you typed — no scale lookup, no guessing. That is why <code>grid-cols-[160px_1fr_300px]</code> works even though the numeric scale stops at twelve: the generator emits <code>grid-template-columns: 160px 1fr 300px</code> directly. Underscores exist because whitespace cannot survive in a class name, so Tailwind converts them back to spaces before emitting the declaration.</p><h3>The hidden cost</h3><p>Every arbitrary value is a one-off utility. Twenty <code>bg-[#...]</code> values across a codebase is a palette that only exists in text search. Tailwind''s scale is what makes an interface feel like one product; arbitrary values are what makes it feel assembled. Use them for structural specs and genuine edge cases, and promote anything repeated into <code>@theme</code> or the config.</p><h3>Arbitrary properties</h3><p>Bracket syntax works for properties too: <code>[mask-image:...]</code>, <code>[scrollbar-width:none]</code>. This is the answer for CSS features Tailwind does not wrap, and it keeps the value in the class list where a designer will find it.</p><h2>Promoting a Value Into the Theme</h2><p>The healthy lifecycle of an arbitrary value is short: it appears in one component, gets copied into a second, and by the third occurrence it should be a token. Promoting deliberately is what keeps a Tailwind codebase from turning into a pile of hex codes.</p><h3>Tailwind 4: @theme</h3><p>Declare the value once in CSS and every utility built on that scale picks it up: <code>@theme { --color-ink: #0b1020; --spacing-brutal: 13px; }</code> produces <code>bg-ink</code> and <code>p-brutal</code>. The classes stay short, the value has one definition, and a redesign becomes a single edit.</p><h3>Tailwind 3: the config</h3><p>Extend the relevant scale in the config instead — <code>colors</code>, <code>spacing</code>, <code>gridTemplateColumns</code>. The effect is the same: one named value, used everywhere, changeable in one place.</p><h3>A quick audit</h3><ul><li>Search the codebase for <code>bg-[#</code>: every hit is a colour that exists only in markup.</li><li>Search for <code>px-[</code> and <code>py-[</code>: repeated pixel values reveal a spacing scale nobody documented.</li><li>Any hit appearing three or more times is a promotion candidate, not a style choice.</li></ul><h3>When brackets are genuinely right</h3><p>Layout specs from a design file — a three-column shell with a 300px sidebar — rarely belong in the theme, because they are used once. The test is reuse, not taste: one-off structure stays in brackets, repeated decisions become tokens.</p><h3>Type hints in practice</h3><p>Most bracket values infer their property from the utility prefix: <code>w-[...]</code> is a width, <code>bg-[...]</code> is a colour or an image. Ambiguity appears when one prefix maps to several properties, which is where <code>text-[length:...]</code> or <code>text-[color:...]</code> earns its keep. The hint costs nothing and removes a class of silent misparse. If a value refuses to compile, check the hint before rewriting the value.</p><h2>Common Mistakes</h2><ul><li>Using spaces instead of underscores inside the brackets; the class split happens at whitespace and half the value is dropped.</li><li>Arbitrary values for the whole spacing scale — <code>p-[13px]</code> repeated forty times is a scale nobody agreed on.</li><li>Missing type hints on ambiguous values, producing wrong property types in some contexts.</li><li>Using brackets to bypass a token you dislike instead of fixing the token.</li></ul><h2>Browser Support / Caveats</h2><p>Arbitrary values compile to plain CSS, so support is whatever the underlying property supports — for <code>mask-image</code>, check the prefix situation in Safari. Tailwind''s scanner must be able to see the literal string, so never build these dynamically by concatenating variables; write the full class or map from a finite set of complete strings.</p><h2>Related Resources</h2><p>An input that uses bracketed values for its brutalist borders is free at <a href="/products/3d-brutalist-username-field">3D brutalist username field</a>. Fluid sizing with <code>clamp()</code> is covered in <a href="/blog/css-clamp-fluid-type">this article</a>, and the syntax is documented at <a href="https://tailwindcss.com/docs/adding-custom-styles" rel="nofollow noopener" target="_blank">tailwindcss.com</a>.</p><p><strong>Try it on SteaCode:</strong> see arbitrary values in a real component at <a href="/products/3d-brutalist-username-field">3D brutalist username field</a>.</p>', 'Isaya Masika', 'published', '2027-01-17');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('tailwind-responsive-card-grid', 'Build a Responsive Card Grid in Tailwind CSS', 'tailwind-responsive-card-grid', 'Tailwind', 'Either step columns at breakpoints (grid-cols-1 sm:grid-cols-2 lg:grid-cols-3) or use auto-fit with a minmax floor and let the grid wrap itself. Always ship a gap.', '<p>A card grid is the single most reused layout on any marketplace, dashboard or blog. Tailwind has two genuinely good answers and one cliché — fixed pixel widths with media queries — that breaks the moment a card grows a longer title.</p><h2>Direct Answer</h2><p>Stepped approach: <code>grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6</code>. Self-wrapping approach: <code>grid gap-6 grid-cols-[repeat(auto-fit,minmax(260px,1fr))]</code>, which fills the row with as many 260px-or-wider columns as fit and stretches them evenly — no breakpoints at all. Use the stepped version when the design must have exactly two columns at tablet width; use auto-fit when content volume varies.</p><h2>Full Code Example</h2><pre><code>&lt;!-- Stepped: precise control per breakpoint --&gt;
&lt;div class="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4"&gt;
  &lt;article class="rounded-2xl border bg-white p-5 shadow-sm"&gt;Card&lt;/article&gt;
&lt;/div&gt;

&lt;!-- Self-wrapping: no breakpoints, cards never narrower than 260px --&gt;
&lt;div class="grid gap-6 grid-cols-[repeat(auto-fit,minmax(260px,1fr))]"&gt;
  &lt;article class="rounded-2xl border bg-white p-5 shadow-sm"&gt;Card&lt;/article&gt;
&lt;/div&gt;

&lt;!-- Equal heights without flex hacks: grid items stretch by default --&gt;
&lt;div class="grid grid-cols-1 gap-6 sm:grid-cols-2 items-stretch"&gt;
  &lt;article class="flex h-full flex-col justify-between rounded-2xl border p-5"&gt;
    &lt;h3 class="font-semibold"&gt;Title&lt;/h3&gt;
    &lt;button class="mt-4 self-start rounded-lg bg-gray-900 px-4 py-2 text-white"&gt;Open&lt;/button&gt;
  &lt;/article&gt;
&lt;/div&gt;</code></pre><h2>Why This Works</h2><p>Grid items stretch to fill their row by default, which is why equal-height cards need no flex hacks per row — every card in a row is as tall as the tallest, and the footer aligns because each card is a flex column with a bottom-aligned action. <code>auto-fit</code> collapses empty tracks, while <code>auto-fill</code> keeps them, leaving a grid that fits the container; pair <code>auto-fit</code> with <code>minmax(260px,1fr)</code> and the browser does the responsive maths the media queries would have done.</p><h3>Why gap, not margins</h3><p><code>gap</code> only appears between tracks, so there is no outer margin to cancel and no last-child exception. Margin-based gutters need negative margins on the container and produce 1px seams at fractional zoom levels — <code>gap</code> has neither problem.</p><h3>Why the min width matters</h3><p>260px is not arbitrary: below roughly 240px a title wraps to three lines and every card becomes a different height. Pick the floor from the content''s real minimum width, not from a nice round number.</p><h2>Container Queries and Card Content Discipline</h2><p>A breakpoint grid answers how wide the browser is, but a card in a sidebar and the same card in a hero need different layouts at the same viewport width. Container queries move the decision to the slot, and Tailwind exposes them directly.</p><h3>The same card, two slots</h3><p>Mark the wrapper <code>@container</code>, then style the card with <code>@md:grid-cols-[120px_1fr]</code>. In a 280px sidebar the card stays stacked; in a 700px hero it becomes horizontal. No media query and no duplicated component.</p><h3>Content that scales with the slot</h3><p>Let the title wrap to two lines and cap it with <code>line-clamp-2</code>. Cards in a grid look ragged when one has a paragraph and the next has a sentence, so clamp the body copy instead of letting content define the row height and then complaining about alignment.</p><h3>Images that behave</h3><p>Give every card image an <code>aspect-ratio</code> and <code>object-fit: cover</code> so the grid keeps its rhythm while files load. Without a reserved box, the first paint is a stack of empty cards that jump when the images arrive. CLS in a grid is almost always this.</p><h3>Choosing the approach</h3><ul><li>Fixed number of columns per breakpoint: stepped media queries.</li><li>Cards that should fill the row evenly: <code>auto-fit</code> with a <code>minmax</code> floor.</li><li>One component used in slots of different widths: container queries.</li></ul><h3>Card density at ultra-wide widths</h3><p>A stepped grid that stops at four columns leaves a 2560px monitor with four very wide cards, which looks broken rather than generous. Add one more step at 2xl, or switch the track definition to <code>auto-fit</code> so the row keeps filling as space appears. Set a maximum width on the container as well: a card grid stretched to the full window is rarely the design anyone signed off. A max-width around 1280px with centred margins keeps card proportions stable on large screens.</p><p>Test the grid at 320px, 768px and 1440px with real copy. Placeholder text hides the two failures that matter: a title wrapping to three lines, and an action button pushed out of the card.</p><h2>Common Mistakes</h2><ul><li>Grid without <code>gap</code>, producing cards fused into a wall.</li><li>Fixed <code>w-[300px]</code> cards, which overflow a 320px phone.</li><li><code>grid-cols-3</code> at all widths, which is unreadable on mobile.</li><li><code>items-start</code> on a grid that needs equal-height cards, leaving ragged bottoms.</li></ul><h2>Browser Support / Caveats</h2><p>CSS Grid is universal. The arbitrary <code>repeat(auto-fit, minmax(...))</code> form compiles to native CSS and needs no polyfill. One Tailwind 4 note: the same utilities exist, but arbitrary grid templates must be written as complete strings so the scanner can see them.</p><h2>Related Resources</h2><p>A full bento layout built on these patterns is free at <a href="/products/bento-grid-designer-portfolio">bento grid portfolio</a>. Choosing between the two layout models is covered in <a href="/blog/css-grid-vs-flexbox">Grid vs Flexbox</a>, and the utility list is at <a href="https://tailwindcss.com/docs/grid-template-columns" rel="nofollow noopener" target="_blank">tailwindcss.com</a>.</p><p><strong>Try it on SteaCode:</strong> the <a href="/products/bento-grid-designer-portfolio">bento grid portfolio</a> ships this exact self-wrapping maths.</p>', 'Isaya Masika', 'published', '2027-01-18');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('tailwind-animate-on-scroll', 'How to Animate Elements on Scroll in Tailwind CSS', 'tailwind-animate-on-scroll', 'Tailwind', 'Tailwind has no scroll animation utility. Combine an IntersectionObserver with transition and translate classes: toggle one class per element, let CSS do the animation, and respect reduced motion.', '<p>Every landing page wants the fade-up-on-scroll effect and almost every implementation listens to <code>scroll</code>, reads layout, and janks. The correct version does no work during scrolling at all — it observes, flips a class, and lets the compositor run the animation.</p><h2>Direct Answer</h2><p>Use an <code>IntersectionObserver</code> per element, or one shared observer, with a threshold around 0.15. When an element intersects, add a class that swaps <code>opacity-0 translate-y-6</code> for <code>opacity-100 translate-y-0</code>, and put <code>transition-all duration-500 ease-out</code> on the element. Unobserve after the first reveal so the animation never replays. Under <code>motion-reduce:</code>, skip the transform entirely.</p><h2>Full Code Example</h2><pre><code>function useReveal() {
  const ref = useRef(null);
  useEffect(() =&gt; {
    const el = ref.current;
    if (!el) return;
    if (!("IntersectionObserver" in window)) { el.dataset.reveal = "in"; return; }
    const io = new IntersectionObserver(
      ([entry]) =&gt; {
        if (entry.isIntersecting) {
          el.dataset.reveal = "in";
          io.unobserve(el);
        }
      },
      { threshold: 0.15, rootMargin: "0px 0px -40px 0px" }
    );
    io.observe(el);
    return () =&gt; io.disconnect();
  }, []);
  return ref;
}

&lt;!-- Tailwind handles the animation; data-reveal is the switch --&gt;
&lt;div
  ref={ref}
  class="opacity-0 translate-y-6 transition-all duration-500 ease-out
         data-[reveal=in]:opacity-100 data-[reveal=in]:translate-y-0
         motion-reduce:translate-y-0 motion-reduce:opacity-100"
&gt;
  Content
&lt;/div&gt;</code></pre><h2>Why This Works</h2><p>The observer reports intersection changes off the main thread''s scroll path — the browser computes visibility internally and hands you a boolean, so there is no <code>getBoundingClientRect</code> and no layout read per frame. The animation itself is <code>opacity</code> and <code>transform</code>, both compositor properties, so mid-animation frames never trigger layout or paint.</p><h3>Why data attributes instead of a className swap</h3><p>A data attribute keeps the state machine in HTML and lets Tailwind''s <code>data-[...]</code> variant handle the styles. There is no string concatenation of class names, which is where half of these implementations lose their base classes.</p><h3>The rootMargin trick</h3><p>A negative bottom margin delays the trigger until the element is a little way into the viewport, so the animation fires when the user is actually looking at it rather than the instant a pixel appears at the edge.</p><h2>One Observer for Many Elements and Staggered Reveals</h2><p>Creating an observer per element works, but a page with forty reveal targets creates forty observers and forty callbacks. A single shared observer that looks up the target by data attribute is cheaper and easier to reason about.</p><h3>The shared observer</h3><p>Observe every <code>[data-reveal]</code> element from one instance, and inside the callback read the entry''s target to flip its attribute. Unobserve per element as it reveals, so the observer shrinks as the user scrolls and nothing replays on the way back up.</p><h3>Staggering children</h3><p>Reveal the parent once and let children transition with an index-based delay. Cap the delay: ten items at 60 milliseconds each is half a second, and beyond that the last item feels late rather than choreographed.</p><h3>Content that must never hide</h3><p>Never start text at zero opacity unless the observer is guaranteed to run. If JavaScript fails, a blocked observer or a hydration error leaves a blank page. The safe pattern applies the hidden state from JavaScript itself, so a no-JS render is fully visible.</p><h3>Checking the result</h3><ul><li>Scroll slowly: each element animates once, and scrolling back up does not replay it.</li><li>Enable reduced motion: content is visible immediately with no transform.</li><li>Throttle the network: the page is readable before scripts finish.</li><li>Check the Performance panel: no long tasks during scroll.</li></ul><h3>Reveal animations and search engines</h3><p>Content hidden at zero opacity is still in the HTML, so crawlers see it, but a reader with JavaScript disabled sees nothing. The script-applied hidden state avoids both problems: the markup is visible by default and only becomes hidden once the observer is ready. Keep the reveal under 600 milliseconds, and never delay the first section of the page, because the fold should be visible immediately. Reveal effects are polish; shipping them on every section makes scrolling feel like work.</p><p>Finally, verify the reveal with JavaScript disabled. If any section is blank, the hidden state is in the markup rather than applied by script.</p><h2>Common Mistakes</h2><ul><li>Animating <code>height</code>, <code>top</code> or <code>margin</code>: every frame costs layout.</li><li>Re-observing so elements re-hide when scrolled back up — a page that strobes.</li><li>Starting visible and animating in, which causes a flash of content before the observer fires.</li><li>Ignoring <code>motion-reduce:</code>, which some users set for vestibular safety, not taste.</li></ul><h2>Browser Support / Caveats</h2><p><code>IntersectionObserver</code> is supported everywhere and degrades cleanly — the snippet above reveals immediately when it is missing. Set the initial hidden state in CSS, not in an effect, so the content is never painted in its final position first. For lists, observe one container and stagger children with <code>transition-delay</code> rather than creating hundreds of observers.</p><h2>Related Resources</h2><p>A production reveal animation is free at <a href="/products/splittext-character-stagger-reveal">split-text stagger reveal</a>. The accessibility side of animation is covered in <a href="/blog/prefers-reduced-motion-css">prefers-reduced-motion</a>, and the observer API is documented at <a href="https://developer.mozilla.org/en-US/docs/Web/API/IntersectionObserver" rel="nofollow noopener" target="_blank">MDN</a>.</p><p><strong>Try it on SteaCode:</strong> copy the <a href="/products/splittext-character-stagger-reveal">split-text stagger reveal</a> for a scroll-triggered headline.</p>', 'Isaya Masika', 'published', '2027-01-19');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('tailwind-custom-plugin', 'Writing a Custom Tailwind CSS Plugin', 'tailwind-custom-plugin', 'Tailwind', 'A plugin is the right home for utilities you use on every project: declare them once, get every variant for free, and keep the markup readable. Use theme() inside, never hard-coded colours.', '<p>The moment three projects need the same <code>text-balance</code> utility or the same card shell, copy-pasted arbitrary values stop being acceptable. A Tailwind plugin turns that snippet into a first-class utility with hover, focus, responsive and dark variants generated automatically.</p><h2>Direct Answer</h2><p>Write a plugin with <code>plugin(({ addUtilities, addComponents, addBase, matchUtilities, theme }) =&gt; { ... })</code> and register it in the config''s <code>plugins</code> array. Use <code>addUtilities</code> for single-property helpers, <code>addComponents</code> for multi-property class shells, <code>matchUtilities</code> for utilities that take a value, and <code>addBase</code> for element defaults. Read design tokens through <code>theme()</code> so the plugin follows the palette instead of forking it.</p><h2>Full Code Example</h2><pre><code>const plugin = require("tailwindcss/plugin");

module.exports = {
  plugins: [
    plugin(function ({ addUtilities, addComponents, matchUtilities, theme }) {
      // 1. Single-purpose utilities
      addUtilities({
        ".text-balance": { textWrap: "balance" },
        ".content-auto": { contentVisibility: "auto" },
      });

      // 2. A component shell, styled from the theme
      addComponents({
        ".card-shell": {
          borderRadius: theme("borderRadius.2xl"),
          backgroundColor: theme("colors.white"),
          border: "1px solid " + theme("colors.gray.200"),
          padding: theme("spacing.5"),
          boxShadow: theme("boxShadow.sm"),
        },
      });

      // 3. Value-taking utility: inset-[...] style helpers
      matchUtilities(
        { "avoid-": (value) =&gt; ({ overflowAnchor: value }) },
        { values: { none: "none", auto: "auto" } }
      );
    }),
  ],
};</code></pre><h2>Why This Works</h2><p>Plugins run inside Tailwind''s own generation pass, which means every class you emit goes through the same variant engine. <code>addUtilities</code> produces classes that answer to <code>hover:</code>, <code>md:</code>, <code>dark:</code> and <code>group-hover:</code> without you registering any of them. That is the payoff over a plain CSS file where each state is hand-written.</p><h3>Why theme() and not hex codes</h3><p><code>theme("colors.gray.200")</code> resolves at build time to the current palette. Change the palette and the plugin follows; hard-code <code>#e5e7eb</code> and the component drifts out of the design system on the next rebrand.</p><h3>Utilities vs components</h3><p>Utilities describe one decision and compose. Components bundle several. Reach for <code>addComponents</code> only when the bundle is genuinely atomic — a card shell, a prose block — and keep the escape hatch of overriding with utilities afterwards.</p><h2>Packaging, Testing and the Tailwind 4 Migration</h2><p>A plugin that only works inside one repository is a snippet with extra steps. Treat it as a package from the start and it can be shared across projects without a rewrite.</p><h3>Structure and options</h3><p>A plugin is a function that receives the API; options arrive through <code>plugin.withOptions</code>. Keep the default export a factory so consumers can pass a prefix or a list of extra values without forking the code.</p><h3>Testing what it emits</h3><p>The reliable test is a build fixture: a tiny HTML file containing every class the plugin should generate, compiled with the plugin, then asserted against the output CSS. Snapshot the emitted declarations rather than the class names, because the classes are the contract and the declarations are the result.</p><h3>Tailwind 4 and @utility</h3><p>Version 4 moves configuration into CSS. Single-property helpers become <code>@utility</code> blocks, which is simpler and still gives you the variant engine. Multi-property component shells read better as a JS plugin registered through <code>@plugin</code>, so a mixed approach is normal during the transition.</p><h3>Release checklist</h3><ul><li>Peer-depend on the Tailwind version range you actually tested.</li><li>Export the plugin as both ESM and CJS, since configs still load both.</li><li>Document every class the plugin emits in the README.</li><li>Keep the emitted CSS small: a plugin that doubles the stylesheet is a bug report waiting to happen.</li></ul><h3>When a plugin is the wrong tool</h3><p>If the class is used once, write the utilities inline instead of formalising a plugin. If the bundle of styles varies per instance, a component is the better home. A plugin earns its place when the same atomic decision appears across projects and must answer to every variant, which is the specific thing it does better than a stylesheet.</p><p>Finally, version the plugin against the Tailwind version it targets. A plugin pinned to an old major silently stops generating classes after an upgrade, which is a broken build disguised as a dependency bump.</p><h2>Common Mistakes</h2><ul><li>Using <code>addComponents</code> for things that should compose as utilities, producing classes users cannot extend.</li><li>Hard-coding colours instead of reading the theme, so the plugin ignores dark mode tokens.</li><li>Dumping raw <code>@layer</code> CSS into a plugin body — if you are not emitting classes, a stylesheet is the better tool.</li><li>Forgetting Tailwind 4: plugins move to <code>@plugin</code> in CSS, but the same JS API works via a compatibility path.</li></ul><h2>Browser Support / Caveats</h2><p>The plugin API is build-time; runtime support depends on the CSS you emit. <code>text-wrap: balance</code> needs Chrome 114+, Safari 17.5+, Firefox 121+ and is harmless where absent. In Tailwind 4, prefer <code>@utility</code> for simple single-property helpers and keep a JS plugin for component bundles.</p><h2>Related Resources</h2><p>A layered gradient surface built from tokens is free at <a href="/products/gradientwaves-layered-horizon">gradient waves horizon</a>. Token architecture is explained in <a href="/blog/design-tokens-two-layer-architecture">design tokens, two layers</a>, and the plugin API is documented at <a href="https://tailwindcss.com/docs/plugins" rel="nofollow noopener" target="_blank">tailwindcss.com</a>.</p><p><strong>Try it on SteaCode:</strong> the <a href="/products/gradientwaves-layered-horizon">gradient waves horizon</a> component is styled entirely through theme tokens.</p>', 'Isaya Masika', 'published', '2027-01-20');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('tailwind-gradient-text', 'Gradient Text in Tailwind CSS', 'tailwind-gradient-text', 'Tailwind', 'bg-clip-text text-transparent plus a gradient: paint the gradient on the element, then clip it to the glyphs. Forget text-transparent and you just get a gradient box.', '<p>Gradient headlines are the cheapest way to make a hero feel designed, and they fail in a predictable way: you add the gradient classes and the text disappears behind a coloured rectangle. Two of the three required classes are missing, and the third is easy to forget.</p><h2>Direct Answer</h2><p>Three decisions together: a gradient background (<code>bg-gradient-to-r from-amber-400 to-orange-600</code>), <code>bg-clip-text</code> to clip that background to the glyph shapes, and <code>text-transparent</code> to make the glyph fill let the background show through. Omit any one and you get either normal text or a gradient block. Add <code>bg-clip-text</code> only to inline or inline-block elements with a bounded width.</p><h2>Full Code Example</h2><pre><code>&lt;!-- The working trio --&gt;
&lt;h1 class="bg-gradient-to-r from-amber-400 via-yellow-300 to-orange-600
           bg-clip-text text-transparent"&gt;
  Ship faster on SteaCode
&lt;/h1&gt;

&lt;!-- Multi-line headlines: constrain the width so the gradient spans lines --&gt;
&lt;p class="max-w-[18ch] bg-gradient-to-br from-sky-400 to-indigo-600
          bg-clip-text text-transparent text-4xl font-extrabold"&gt;
  Copy-paste UI, honestly free
&lt;/p&gt;

&lt;!-- Animated sweep: the gradient moves, the text is still clipped --&gt;
&lt;span class="bg-[length:200%_100%] bg-gradient-to-r from-gray-900 via-gray-400 to-gray-900
             bg-clip-text text-transparent animate-[shine_3s_linear_infinite]"&gt;
  Loading headline
&lt;/span&gt;</code></pre><h2>Why This Works</h2><p>The text colour must be transparent because the browser paints a gradient background behind the text, then clips it to the glyph outlines. If the text is opaque, its fill covers the clipped gradient. If clipping is missing, the full element rectangle shows the gradient. All three properties describe one paint: background → clip → see through the letters.</p><h3>Contrast and selection</h3><p>Gradient text is the easiest way to fail a contrast audit: the WCAG ratio is measured against the lightest point of the gradient, not the average. Keep the two stops within a similar luminance range, or use a solid colour for any text under 24px. Selection highlighting also looks muddy behind transparent text; set a solid <code>::selection</code> colour.</p><h3>Where it breaks</h3><p><code>bg-clip-text</code> needs a box to clip against. On a purely inline element whose gradient is defined relative to its own width, an inline box that wraps inherits the gradient per line fragment in some engines. Use <code>inline-block</code> or a constrained block, and the gradient spans the sentence properly.</p><h2>Fallbacks, Selection and Performance</h2><p>Gradient text touches three things that break quietly: browsers without clipping support, users selecting the headline, and the paint cost of an animated background. Each has a cheap fix.</p><h3>A fallback that is not invisible</h3><p>Never rely on an inline style that makes text transparent. Keep the transparency in Tailwind''s class so a browser without <code>background-clip: text</code> simply paints normal text — the design degrades to a solid headline rather than an empty gap. If you must support very old engines, wrap the transparent rule in an <code>@supports</code> guard.</p><h3>Selection and caret</h3><p>Transparent text makes the native selection highlight look like a coloured block with no letters. Set a solid <code>::selection</code> background and a normal text colour inside it, so copying the headline is legible. The same applies to a caret if the gradient is ever applied to editable text, which it should not be.</p><h3>Animated gradients cost paint</h3><p>Moving <code>background-position</code> across a large headline repaints the glyphs every frame. Keep the element small, use a two-stop gradient, and pause the animation when the tab is hidden. On a hero that is always visible, a slow sweep still looks smooth, but the battery cost is real on mobile.</p><h3>Where gradient text should stop</h3><ul><li>Headlines and wordmarks: yes, provided contrast is checked at the lightest stop.</li><li>Buttons: risky, since the label must stay readable in every state.</li><li>Body copy: no. Gradient text below 24px fails both contrast and legibility.</li></ul><h3>Testing contrast programmatically</h3><p>Sample both gradient stops, compute the ratio against the background behind the text, then take the worst result. A tool that checks only the first colour passes a headline that is unreadable at its lightest end. When the lightest stop falls below 4.5 to 1, darken it rather than adding a text shadow, because shadows on clipped text are invisible.</p><h2>Common Mistakes</h2><ul><li>Missing <code>text-transparent</code>, leaving a gradient rectangle where the headline should be.</li><li>Reverse order thinking: adding <code>text-transparent</code> without a gradient leaves invisible text — a genuine outage, not a styling bug.</li><li>Using gradient text for body copy, which is unreadable at 16px and fails contrast.</li><li>Animating <code>background-position</code> on huge elements, causing a full repaint each frame.</li></ul><h2>Browser Support / Caveats</h2><p><code>background-clip: text</code> is supported in current Chrome, Safari, Firefox and Edge; Tailwind emits the <code>-webkit-</code> prefix automatically. Where support is missing the text renders in its normal colour — a graceful fallback, provided you did not also make it transparent via a fallback-less inline style. Add <code>motion-reduce:animate-none</code> to the animated variant.</p><h2>Related Resources</h2><p>A gradient wordmark component is free at <a href="/products/warptext-glass-refraction-headline">glass refraction headline</a>. The glass treatment it pairs with is covered in <a href="/blog/glassmorphism-button">glassmorphism buttons</a>, and the property is documented at <a href="https://developer.mozilla.org/en-US/docs/Web/CSS/background-clip" rel="nofollow noopener" target="_blank">MDN</a>.</p><p><strong>Try it on SteaCode:</strong> copy the <a href="/products/warptext-glass-refraction-headline">glass refraction headline</a> for a gradient hero that ships with its contrast checked.</p>', 'Isaya Masika', 'published', '2027-01-21');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('reduce-cumulative-layout-shift', 'How to Reduce Cumulative Layout Shift (CLS)', 'reduce-cumulative-layout-shift', 'Performance', 'CLS is unexpected movement after paint. Reserve space for every media element, ad slot and late-loading font — with dimensions, aspect-ratio or min-height — and nothing shifts when it arrives.', '<p>CLS is the metric that measures how much the page moves under the user''s cursor after it has already been painted. It is not about how fast something loads; it is about whether an element that was already rendered relocates. That distinction is why a 300ms image load scores well and a 30ms banner insertion scores terribly.</p><h2>Direct Answer</h2><p>Reserve space before the content exists. Give every <code>&lt;img&gt;</code> a width and height (or an <code>aspect-ratio</code> box) so the browser allocates the right area on first layout. Give ad slots a <code>min-height</code> matched to the creative size. Give text containers a fallback font with matched metrics, or accept a <code>size-adjust</code> override. Never insert a banner, cookie bar or notification above content that is already painted — that is the single largest CLS source in the wild.</p><h2>Full Code Example</h2><pre><code>/* 1. Media: reserve the exact box before the file arrives */
.hero-image {
  aspect-ratio: 16 / 9;
  width: 100%;
  height: auto;
  object-fit: cover;
  background: #e5e7eb; /* visible placeholder while loading */
}

/* 2. Ad slot: fixed reservation, not min-height that grows */
.ad-slot {
  width: 100%;
  height: 250px;        /* matches the creative, so arrival shifts nothing */
  contain: layout size; /* isolates the slot from the rest of the page */
  overflow: hidden;
}

/* 3. Fonts: match the fallback''s metrics to the web font */
@font-face {
  font-family: "Inter Fallback";
  src: local("Arial");
  size-adjust: 107%;
  ascent-override: 90%;
  descent-override: 22%;
  line-gap-override: 0%;
}
body { font-family: Inter, "Inter Fallback", sans-serif; }</code></pre><h2>Why This Works</h2><p>The browser lays out once with the information it has. If an image has no dimensions, it gets zero height, and every sibling below starts too high; when the image arrives, everything jumps. Declaring <code>aspect-ratio</code> gives the layout engine the final box up front, so the arrival is a paint change, not a layout change.</p><h3>What never counts toward CLS</h3><p>Shifts caused by user interaction within 500ms do not count — opening a menu is not the page''s fault. Animations using <code>transform</code> do not count, because the element''s layout position is unchanged; this is why entrances should always be transform/opacity, never height or margin.</p><h3>The font problem</h3><p>A web font with different metrics re-flows every line when it swaps in. <code>size-adjust</code> and the ascent/descent overrides reshape the fallback to occupy the same space, so the swap happens with no line reflow at all. It is the only reliable fix for text-driven CLS.</p><h2>Finding CLS Sources in the Field</h2><p>Laboratory tools show a single synthetic load; field data shows what real users experienced on real connections. The two disagree often, and the field number is the one that counts.</p><h3>Read the attribution, not just the score</h3><p>CrUX and the Web Vitals extension report which element moved and how far. Start there rather than guessing: the largest shift is almost always an image without dimensions, an injected banner, or a late-loading font. Fixing the second-largest first wastes a release.</p><h3>A triage order that works</h3><ul><li>Inventory every above-the-fold media element and confirm each has dimensions or an <code>aspect-ratio</code> box.</li><li>Audit third-party insertions: ads, consent bars, chat widgets, promo strips. Any inserted above painted content is a shift.</li><li>Check the font swap path: a fallback with mismatched metrics reflows every line on swap.</li><li>Look for accordions or tabs animating <code>height</code>, which shift everything below on each frame.</li></ul><h3>Why the score differs between tools</h3><p>Lighthouse simulates a fast connection and a single viewport, so a shift that only appears on a slow phone is invisible. Field data aggregates the 75th percentile, where the slowest quarter of sessions live. When the lab score is green and the field score is not, trust the field and instrument the slow path.</p><h3>Reserving space for ads specifically</h3><p>Ad slots are the hardest case because the creative size is decided by a network, not by you. Reserve the largest size the slot may serve, centre the creative inside it, and never let the slot grow after fill. A fixed <code>min-height</code> is not enough: the container must be a hard box with <code>contain: layout size</code> so its contents cannot resize its ancestors.</p><h2>Common Mistakes</h2><ul><li>Images without dimensions, the most common single cause.</li><li>Ad slots with <code>min-height</code> that grow when the creative loads — the slot must be a fixed, reserved size.</li><li>Injecting a consent banner or promo above the fold after paint.</li><li>Animating <code>height: auto</code> for accordions, which shifts everything below on every frame.</li></ul><h2>Browser Support / Caveats</h2><p><code>aspect-ratio</code> is universal in current browsers; older Safari needs the padding-top fallback. <code>size-adjust</code> requires Chrome 92+, Firefox 91+ and Safari 17+. CLS is measured in the field, so verify with the CrUX dashboard rather than a single Lighthouse run — one slow third-party script can dominate the 75th percentile.</p><h2>Related Resources</h2><p>A hero section that reserves its media box is free at <a href="/products/premium-website-hero">premium website hero</a>. Font-loading strategy is covered in <a href="/blog/font-display-swap-preload">font-display and preload</a>, and the metric is defined on <a href="https://web.dev/articles/cls" rel="nofollow noopener" target="_blank">web.dev</a>.</p>', 'Isaya Masika', 'published', '2027-01-22');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('interaction-to-next-paint-inp', 'Improving Interaction to Next Paint (INP)', 'interaction-to-next-paint-inp', 'Performance', 'INP is the time from a tap or keypress to the next painted frame. Most bad INP is one long task blocking the main thread — split the work, defer the heavy part, and keep handlers off the critical path.', '<p>INP replaced First Input Delay as a Core Web Vital because FID only measured the queue delay before a handler started. INP measures the whole thing: input arrives, the main thread is busy, the handler runs, the browser paints the result. A page that feels laggy on a mid-range Android is failing INP even if every individual task looks short.</p><h2>Direct Answer</h2><p>Keep the main thread free at the moment of interaction. Break long tasks into chunks under 50ms, defer non-visual work with <code>scheduler.postTask</code> or <code>setTimeout</code>, and keep event handlers to state changes plus a paint. If a handler must do heavy computation, compute after the paint with <code>requestAnimationFrame</code> then a deferred callback, or move it to a worker.</p><h2>Full Code Example</h2><pre><code>// Bad: one 300ms task inside the click handler
function onClick() {
  const rows = buildRows(data);   // 300ms of work before the user sees anything
  setRows(rows);
}

// Better: paint the acknowledgement first, then do the work
function onClick() {
  setBusy(true);                                    // immediate visual feedback
  requestAnimationFrame(() =&gt; {
    setTimeout(() =&gt; {
      const rows = buildRows(data);
      setRows(rows);
      setBusy(false);
    }, 0);
  });
}

// Best when available: prioritised scheduling
async function onClick() {
  setBusy(true);
  await scheduler.postTask(() =&gt; buildRows(data), { priority: "background" })
    .then((rows) =&gt; { setRows(rows); setBusy(false); });
}

// Chunk a long loop so the browser can paint between slices
async function processItems(items) {
  for (let i = 0; i &lt; items.length; i += 50) {
    doWork(items.slice(i, i + 50));
    await new Promise((r) =&gt; setTimeout(r, 0)); // yield to the event loop
  }
}</code></pre><h2>Why This Works</h2><p>A long task blocks everything: input events queue behind it, and the browser cannot paint until it ends. Yielding returns control to the event loop, letting input handling and paint interleave with your work. The visible result is that the first frame after a tap reflects the tap immediately, even if the expensive result arrives a moment later.</p><h3>Three parts of INP</h3><p>Input delay (waiting for the main thread), processing time (your handlers and React work), and presentation delay (style, layout, paint). Optimising only processing gets you partway; shipping a 200KB script that runs on load delays every later interaction too.</p><h3>What to look for in the field</h3><p>INP is measured at the 75th percentile of interactions, so a single pathological case — a heavy chart re-render on every keystroke — defines the score. Look at the interaction with the worst value, not the average, and fix that one.</p><h2>Diagnosing INP with the Performance Panel</h2><p>INP is easy to state and hard to locate, because the slow interaction is usually not the one you are testing. The Performance panel turns the metric into a timeline you can read.</p><h3>Record the real interaction</h3><p>Start a recording, then perform the interaction slowly and deliberately: type into the search field, open the menu, change a filter. The panel marks the input, the task it triggered, and the frame that finally painted. That gap is the number you are optimising.</p><h3>Read the three segments</h3><ul><li><strong>Input delay</strong>: a long task was already running when the input arrived. Fix the work that runs before the interaction, not the handler itself.</li><li><strong>Processing</strong>: your handler and the React render. Fix by narrowing state updates so one keystroke does not re-render the tree.</li><li><strong>Presentation</strong>: style, layout and paint. Fix by avoiding layout reads in handlers and keeping the visual change small.</li></ul><h3>A common React pattern that fails</h3><p>A controlled input whose <code>onChange</code> filters a thousand rows synchronously will fail INP on mid-range hardware even though the code looks ordinary. Debounce the filter, or move it into a transition so the keystroke paints immediately and the list updates behind it.</p><h3>Measure after every fix</h3><p>INP moves in small increments. Re-record the same interaction and compare the three segments; a change that improves processing but worsens presentation has simply moved the cost.</p><h3>The interaction budget</h3><p>Aim for the frame after a tap to arrive within 100 milliseconds. Anything above that is perceptible as lag; above 300 milliseconds it feels broken. Budget the main thread per interaction rather than per page load, and treat every third-party script as a competitor for that budget.</p><h2>Common Mistakes</h2><ul><li>Huge synchronous state updates in <code>onChange</code>, making every keystroke a long task.</li><li>Third-party scripts executing on the main thread at the moment of interaction.</li><li>Reading layout in a loop (<code>offsetHeight</code> then write, repeatedly), causing forced reflow.</li><li>Hydrating a large tree while the user is already tapping, so early interactions queue behind hydration.</li></ul><h2>Browser Support / Caveats</h2><p><code>scheduler.postTask</code> is Chromium-only; feature-detect it and fall back to <code>setTimeout</code>, as above. INP is available in the field through CrUX and locally via the <code>PerformanceObserver</code> <code>event</code> entry type — the same observer shape used for LCP.</p><h2>Related Resources</h2><p>A pointer-driven component where frame cost matters is free at <a href="/products/glow-cursor">glow cursor</a>. Measuring in the browser is covered in <a href="/blog/measure-lcp-performanceobserver">PerformanceObserver for LCP</a>, and the metric is defined on <a href="https://web.dev/articles/inp" rel="nofollow noopener" target="_blank">web.dev</a>.</p>', 'Isaya Masika', 'published', '2027-01-23');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('css-3d-tilt-card-perspective', 'Build a 3D Tilt Card Effect with CSS perspective', 'css-3d-tilt-card-perspective', 'CSS', 'Perspective goes on the parent, rotation on the child. Feed pointer position into rotateX and rotateY, keep transitions on transform only, and reset the card on pointer leave.', '<p>The tilt card is the effect everyone associates with premium product pages: the surface leans toward the cursor as if it had depth. It is about forty lines, and the one mistake that ruins it — putting <code>perspective</code> on the element that rotates — is invisible until you compare against a reference.</p><h2>Direct Answer</h2><p>Put <code>perspective</code> on the parent wrapper, and <code>transform: rotateX() rotateY()</code> on the card. Track <code>pointermove</code> over the card, map the cursor''s position to a small angle range (about ±10 degrees), and write the rotation into a CSS custom property. On <code>pointerleave</code>, reset both angles to zero so the card settles. Use <code>transform-style: preserve-3d</code> only if children should pop out in depth.</p><h2>Full Code Example</h2><pre><code>.tilt-scene {
  perspective: 900px;      /* depth of field — belongs on the parent */
}

.tilt-card {
  transform:
    rotateX(var(--rx, 0deg))
    rotateY(var(--ry, 0deg));
  transition: transform 200ms ease-out;
  will-change: transform;
  transform-style: preserve-3d;
}

.tilt-card:hover { transition-duration: 60ms; } /* tighter follow while tracking */

/* script */
const card = document.querySelector(".tilt-card");
card.addEventListener("pointermove", (e) =&gt; {
  const r = card.getBoundingClientRect();
  const px = (e.clientX - r.left) / r.width;   // 0 → 1
  const py = (e.clientY - r.top) / r.height;   // 0 → 1
  card.style.setProperty("--ry", `${(px - 0.5) * 20}deg`);
  card.style.setProperty("--rx", `${(0.5 - py) * 20}deg`);
});
card.addEventListener("pointerleave", () =&gt; {
  card.style.setProperty("--rx", "0deg");
  card.style.setProperty("--ry", "0deg");
});</code></pre><h2>Why This Works</h2><p><code>perspective</code> establishes the vanishing point for the children''s 3D transforms. On the rotating element itself it applies to that element''s own children, not to its rotation, so the card looks flat and slightly skewed instead of receding. One level up, the rotation reads as genuine depth.</p><h3>Why custom properties rather than inline transforms</h3><p>Writing a whole <code>transform</code> string on every pointer event overwrites anything else that uses transform on the card — a hover lift, an entrance animation. Two custom properties let the base transform stay in CSS and the animation engine interpolate the angles.</p><h3>Performance and restraint</h3><p>Only <code>transform</code> changes, so this runs on the compositor. Ten degrees is enough; twenty looks broken. And on touch devices there is no hover, so gate the effect behind <code>@media (hover: hover)</code> or it will never fire.</p><h2>Touch, Keyboard and Reduced Motion</h2><p>The pointer version is the easy half. A tilt shipped without fallbacks is a card that is broken on a phone, unusable from a keyboard, and uncomfortable for anyone who has asked their system for less motion.</p><h3>Touch devices</h3><p>There is no hover on touch, and pointer events fire during a scroll gesture, producing a card that jumps while the user is trying to scroll. Gate the listener behind <code>@media (hover: hover) and (pointer: fine)</code>, or check <code>matchMedia</code> before attaching. A tap should do whatever the card does; tilt is not an interaction on its own.</p><h3>Keyboard parity</h3><p>If the card is focusable, give it a static lift on <code>:focus-visible</code> so keyboard users get equivalent feedback. Do not simulate tilt with arrow keys; that is an interaction cost paid for a decoration.</p><h3>Reduced motion</h3><p>Wrap the transition in <code>@media (prefers-reduced-motion: reduce)</code> and set the transform to none. This is not optional polish: a surface that moves with the cursor can cause genuine discomfort for people with vestibular disorders.</p><h3>Cost control</h3><ul><li>Listen with <code>pointermove</code>, not <code>mousemove</code> plus touch handlers.</li><li>Write custom properties only, never a full transform string.</li><li>Cache the rect on <code>pointerenter</code> instead of calling <code>getBoundingClientRect</code> inside the move handler.</li><li>Remove the listener entirely when the card leaves the viewport.</li></ul><h3>A cheaper alternative</h3><p>If the tilt is decorative, a static layered shadow and a two-pixel hover lift read almost as well and cost nothing at runtime. Reserve the pointer-driven version for a hero card the user is meant to inspect, not for every card in a grid. On a page with thirty cards, thirty pointer listeners is a measurable scroll cost on a low-end phone.</p><p>Finally, test with a trackpad and with a mouse. Trackpads fire many more pointer events per second, and an effect that looks smooth with a mouse can feel jittery when the pointer moves in small increments.</p><h2>Common Mistakes</h2><ul><li><code>perspective</code> on the card instead of its parent.</li><li>Moving the card with <code>top</code>/<code>left</code> for the tilt, causing layout on every frame.</li><li>No reset on <code>pointerleave</code>, leaving the card permanently skewed.</li><li>No <code>motion-reduce</code> guard — for some users, a moving surface is nausea, not delight.</li></ul><h2>Browser Support / Caveats</h2><p>3D transforms are universal. <code>transform-style: preserve-3d</code> combined with <code>overflow: hidden</code> and <code>filter</code> on ancestors creates a flattening bug in some engines — keep the card''s ancestors free of filters. On iOS, pointer events fire for touch, but the effect is pointless without a persistent cursor, so restrict it to hover-capable devices.</p><h2>Related Resources</h2><p>A full 3D flip built on these same transforms is free at <a href="/products/3d-flip-login-sign-up">3D flip login</a>. The stacking-context side effect of transforms is covered in <a href="/blog/transform-creates-containing-block">transform creates a containing block</a>, and the property is documented at <a href="https://developer.mozilla.org/en-US/docs/Web/CSS/perspective" rel="nofollow noopener" target="_blank">MDN</a>.</p>', 'Isaya Masika', 'published', '2027-01-24');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('css-animated-gradient-border', 'Animated Gradient Border in CSS', 'css-animated-gradient-border', 'CSS', 'border-image cannot animate smoothly. Use a pseudo-element with a gradient background and background-clip, or register an angle with @property so conic gradients interpolate.', '<p>An animated gradient border looks like a one-line CSS trick and is actually two separate techniques: a cheap one that works everywhere and an elegant one that needs <code>@property</code>. Knowing which is which saves you from an animation that runs at four frames a second.</p><h2>Direct Answer</h2><p>Cheapest reliable method: give the element a gradient background and a transparent border, then place a pseudo-element with the element''s own background colour inset by the border width — the gradient shows only through the gap. Smoothly rotating version: register a custom property with <code>@property</code> as a <code>&lt;angle&gt;</code> and animate a <code>conic-gradient</code> from it. Do not try to animate <code>border-image</code>; it does not interpolate.</p><h2>Full Code Example</h2><pre><code>/* A. Pseudo-element border — works everywhere */
.gradient-border {
  position: relative;
  border-radius: 16px;
  padding: 2px;                       /* border thickness */
  background: linear-gradient(135deg, #f5b400, #d97706);
}
.gradient-border::before {
  content: "";
  position: absolute;
  inset: 2px;
  border-radius: 14px;
  background: #fffdf7;                 /* inner surface */
}

/* B. Rotating conic border — Chromium + Safari 16.4 + Firefox 128 */
@property --angle {
  syntax: "&lt;angle&gt;";
  initial-value: 0deg;
  inherits: false;
}
.spin-border {
  border-radius: 16px;
  padding: 2px;
  background: conic-gradient(from var(--angle), #f5b400, #d97706, #f5b400);
  animation: spin 4s linear infinite;
}
@keyframes spin {
  to { --angle: 360deg; }
}
@media (prefers-reduced-motion: reduce) {
  .spin-border { animation: none; }
}</code></pre><h2>Why This Works</h2><p>The padding trick is a geometry hack: the outer box paints a gradient, the inner pseudo-element paints the surface, and the two-pixel difference between them reads as a border. Because both layers are plain backgrounds, the whole thing composites cheaply and animating the gradient''s position costs one repaint of a small area.</p><h3>Why @property is required for smooth rotation</h3><p>Unregistered custom properties are strings, and strings do not interpolate — the browser jumps from <code>0deg</code> to <code>360deg</code> at the end of the animation. <code>@property</code> declares the type as <code>&lt;angle&gt;</code>, which makes it animatable, so the conic gradient sweeps smoothly.</p><h3>Why not border-image</h3><p><code>border-image</code> accepts a gradient but treats it as a static slice; changing the angle requires changing the image, which is not an interpolatable value. Every attempt to animate it either snaps or forces a full re-decode.</p><h2>Choosing Between the Techniques</h2><p>Three plausible implementations exist and they differ by what animates, not by how they look. Picking the wrong one is why some gradient borders stutter on a mid-range phone while an identical-looking neighbour is smooth.</p><h3>Static gradient border</h3><p>The padding and pseudo-element method paints two backgrounds. It is the cheapest and works everywhere, but nothing moves. Use it when the border is a brand accent rather than a motion piece.</p><h3>Rotating conic gradient</h3><p>Registering an angle with <code>@property</code> and animating the conic gradient is smooth on current Chromium and Safari, and degrades to a static ring elsewhere. Keep the element small: repainting a full-width panel at 60 frames per second is visible on low-end hardware.</p><h3>Rotating a pseudo-element instead</h3><p>The alternative that needs no <code>@property</code>: paint a large pseudo-element with a static conic gradient and rotate it with a <code>transform</code>. Because transform is compositor-only, this holds frame rate even on old devices, at the cost of a little more markup and an <code>overflow: hidden</code> wrapper. For big surfaces, this is usually the better trade.</p><h3>Decision summary</h3><ul><li>Static accent: pseudo-element background.</li><li>Small element, modern browsers: <code>@property</code> angle.</li><li>Large surface or older hardware: rotating pseudo-element.</li></ul><h3>The mask technique</h3><p>A fourth option uses <code>mask-composite</code> to punch a hole in a gradient layer, producing a border of any radius without a second pseudo-element. It is elegant and needs care: <code>mask-composite: exclude</code> is prefixed in Safari, and the mask must match the element''s border radius. For a one-off hero panel it is the cleanest implementation; for a reusable component the padding trick is more portable.</p><p>Finally, decide the fallback before shipping: without <code>@property</code> support the ring should be a plainly visible static gradient, never an invisible border. Test by disabling the animation and confirming the border still reads as a border. A ring that disappears silently looks like a layout bug, not a graceful degradation.</p><h2>Common Mistakes</h2><ul><li>Animating <code>border-image</code> and concluding CSS can''t do it.</li><li>Forgetting that the pseudo-element needs the same radius, less the border width, or corners bulge.</li><li>Animating <code>background-position</code> over a viewport-sized gradient, repainting megabytes each frame.</li><li>Shipping the conic version with no static fallback, so unsupported browsers show a solid block.</li></ul><h2>Browser Support / Caveats</h2><p>The pseudo-element method is universal. <code>@property</code> needs Chrome 85+, Safari 16.4+ and Firefox 128+; below that, the border renders as a static gradient, which is an acceptable fallback if the gradient itself is the design. Keep the animated element small — a 40px button, not a full-width panel.</p><h2>Related Resources</h2><p>A gradient-ringed pill button is free at <a href="/products/gradient-glow-pill-button-join-on-github">gradient glow pill button</a>. Transition safety is covered in <a href="/blog/css-transition-properties-list">never transition all</a>, and <code>@property</code> is documented at <a href="https://developer.mozilla.org/en-US/docs/Web/CSS/@property" rel="nofollow noopener" target="_blank">MDN</a>.</p>', 'Isaya Masika', 'published', '2027-01-25');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('css-skeleton-shimmer-loading', 'CSS Skeleton Screens with a Shimmer Effect', 'css-skeleton-shimmer-loading', 'CSS', 'A skeleton is a reservation, not decoration: match the real content''s dimensions exactly, then animate a gradient''s background-position. Mismatched sizes cause the layout shift the skeleton was meant to prevent.', '<p>Skeletons exist for two reasons — perceived speed and a reserved layout — and most implementations achieve only the first. If the skeleton is 120px tall and the loaded card is 180px, you have built an animation that guarantees the very jump you were trying to avoid.</p><h2>Direct Answer</h2><p>Build grey blocks with the exact height, radius and spacing of the real content. Animate a diagonal gradient across them with <code>background-position</code>, or better, move a pseudo-element with <code>transform</code>. Cap the count at what actually fits, and stop the animation under <code>prefers-reduced-motion</code> — a pulsing page is genuinely unpleasant for some users.</p><h2>Full Code Example</h2><pre><code>.skeleton {
  background: #eef0f3;
  border-radius: 8px;
  position: relative;
  overflow: hidden;
}

/* Sweep via transform: compositor-friendly, no repaint */
.skeleton::after {
  content: "";
  position: absolute;
  inset: 0;
  transform: translateX(-100%);
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.6),
    transparent
  );
  animation: shimmer 1.4s ease-in-out infinite;
}
@keyframes shimmer {
  to { transform: translateX(100%); }
}

/* Match the real components'' dimensions exactly */
.skeleton--card { height: 220px; border-radius: 16px; }
.skeleton--title { height: 18px; width: 60%; margin: 16px 0 10px; }
.skeleton--line  { height: 12px; width: 90%; margin-bottom: 8px; }

@media (prefers-reduced-motion: reduce) {
  .skeleton::after { animation: none; }
}</code></pre><h2>Why This Works</h2><p>Translating a pseudo-element is a compositor operation: no layout, no paint, just a texture movement. The alternative — animating <code>background-position</code> on the skeleton itself — repaints the whole block every frame, which on a grid of twelve cards is measurable on low-end hardware.</p><h3>The reservation rule</h3><p>A skeleton that exactly matches the loaded component''s box means the swap causes zero shift, which is the entire point. Derive the skeleton''s dimensions from the component''s CSS, not from an eyeballed screenshot, and the two stay in sync through refactors.</p><h3>When not to show a skeleton</h3><p>Under roughly 200ms, a skeleton flashes and feels slower than nothing. Prefer a static placeholder or nothing at all for fast responses, and reserve skeletons for genuine waits.</p><h2>Deriving Skeletons From the Real Component</h2><p>The skeleton''s job is to be dimensionally identical to the content that replaces it. That is a design constraint, not a styling preference, and it is easiest to satisfy when the skeleton comes from the same component rather than being drawn by eye.</p><h3>One layout, two fillings</h3><p>Render the real card component with placeholder children: same padding, same border, same grid, same image box. Only the inner text nodes become grey bars. The swap then changes colour, not geometry, and the shift is exactly zero.</p><h3>Bars that mimic line lengths</h3><p>A title bar at sixty percent width and two body lines at ninety and seventy percent read as text, while uniform full-width bars read as a table. Vary the widths in a fixed pattern so loading and loaded states feel like the same layout.</p><h3>Counting what fits</h3><p>Render only what the viewport can show: the first screenful plus one row. Drawing twenty skeleton cards that never enter view is work for nothing and inflates first paint with elements the user will never see.</p><h3>Timing thresholds</h3><ul><li>Under 200 milliseconds: show nothing. A flash is worse than a pause.</li><li>200 milliseconds to 1 second: static grey placeholder, no shimmer.</li><li>Over 1 second: shimmer, because the wait is now perceptible.</li><li>Over 10 seconds: add copy and a retry path, since a skeleton alone stops communicating progress.</li></ul><h3>Loading states and assistive technology</h3><p>A skeleton is visual only. Screen readers announce nothing, so every loading region needs a live status: a visually hidden element with <code>role="status"</code> reading "Loading products", removed when the content arrives. Do not mark the skeleton <code>aria-hidden</code> and forget the status, because that leaves the region silent for the entire wait.</p><p>Keep the transition calm as well. A grid of twelve shimmering cards is a lot of simultaneous motion, so stagger the animation start slightly or animate only the first row. Under reduced motion, render a static placeholder with the text status, which communicates the same thing without movement.</p><p>Finally, put the skeleton behind a test that asserts its measured height equals the loaded card''s height. That single assertion is the difference between a skeleton that prevents shift and one that causes it.</p><h2>Common Mistakes</h2><ul><li>Skeleton dimensions that differ from the real content, guaranteeing the shift.</li><li>Animating <code>background-position</code> on large blocks — full repaint per frame.</li><li>Infinite shimmer with no reduced-motion guard.</li><li>One skeleton per row when the request returns twenty; you have drawn a fake grid.</li></ul><h2>Browser Support / Caveats</h2><p>Everything here is widely supported. <code>prefers-reduced-motion</code> is honoured on all current platforms. Keep each skeleton''s animation count low — dozens of simultaneous infinite animations cost battery on mobile even when they are compositor-only.</p><h2>Related Resources</h2><p>A loader built on the same shimmer idea is free at <a href="/products/spectrum-loader-animated-loading-text">spectrum animated loader</a>. Motion accessibility is covered in <a href="/blog/prefers-reduced-motion-css">prefers-reduced-motion</a>, and the animation approach is documented at <a href="https://developer.mozilla.org/en-US/docs/Web/CSS/background-position" rel="nofollow noopener" target="_blank">MDN</a>.</p>', 'Isaya Masika', 'published', '2027-01-26');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('best-free-react-ui-component-libraries', 'The Best Free React UI Component Libraries in 2026', 'best-free-react-ui-component-libraries', 'Design Systems', 'Choose by how much you intend to restyle: headless primitives for full control, unstyled-plus-copy libraries for speed, and styled kits for internal tools. Licence and bundle size decide the rest.', '<p>There are three genuinely different things called "a UI library", and comparing them is the reason teams end up with a 400KB dependency for six buttons. The useful question is not which library is best — it is how much of the design you intend to own.</p><h2>Direct Answer</h2><p>Headless primitives (behaviour and accessibility, zero styling) suit products with a real design system. Copy-in component collections (source code you own, unstyled by default) suit teams that want speed without lock-in. Styled kits with a full theme suit internal tools where brand differentiation is irrelevant. Check the licence first: MIT is safe, and anything with a revenue or seat clause needs a legal read.</p><h2>Full Code Example</h2><pre><code>/* A decision matrix you can commit to a repo */

Headless primitives
  owns: behaviour, focus management, ARIA
  you own: every visual decision
  cost: wiring CSS yourself
  best for: design-system-led products

Copy-in components
  owns: component source, sensible defaults
  you own: the fork, and all upgrades
  cost: maintenance of vendored code
  best for: teams shipping fast on Tailwind

Styled kits
  owns: visuals, layout primitives, theming
  you own: theme overrides only
  cost: bundle size, opinionated markup
  best for: admin panels and internal tools</code></pre><h2>Why This Works</h2><p>The trade is always the same: control against speed. Headless libraries give you the hard part — focus traps, keyboard navigation, screen reader semantics — while leaving the easy-to-differentiate part to you. Styled kits invert this: you get a coherent look immediately and inherit its opinions forever.</p><h3>Licence and exit cost</h3><p>A library you cannot fork is a dependency with a cliff. MIT-licensed source means the worst case is maintaining a fork. Copy-in libraries make that the default, which is freedom and obligation at once: you own every security fix.</p><h3>Bundle reality</h3><p>Tree-shaking only helps if you import leaf modules. A single barrel import can pull an entire design system into the bundle. Measure with a bundle analyser before adopting, not after the Lighthouse score drops.</p><h2>Evaluating a Library in an Afternoon</h2><p>Marketing pages list components; a real evaluation answers five questions in about four hours. Skipping them is how a team discovers a licensing problem three months into a build.</p><h3>One: boot a two-page prototype</h3><p>Install it in a throwaway Vite app and build a list with search, a modal and a form. Twelve minutes of real use exposes the shape of the API better than any documentation page. If the prototype fights you, production will be worse.</p><h3>Two: count the bytes</h3><p>Build the prototype and open the bundle analyser. Compare the cost of importing three components to the cost of the whole package. A library that cannot be tree-shaken is a permanent tax on every page.</p><h3>Three: test the accessibility surface</h3><ul><li>Keyboard: can you complete every interaction without a mouse?</li><li>Focus: does the modal restore focus when it closes?</li><li>Screen reader: are names announced, or is everything a generic button?</li><li>Zoom: does the layout survive 200 percent?</li></ul><h3>Four: read the licence clause</h3><p>MIT and Apache are safe. Anything with a revenue threshold, a seat count or a commercial-use carve-out needs a legal read before adoption, not after a launch.</p><h3>Five: check the exit path</h3><p>Can you fork it? Is the source readable? How often do breaking changes ship? A library is a relationship, and the question is what leaving costs, not whether you will leave.</p><h3>Mixing two systems</h3><p>It is tempting to take primitives from one library and visuals from another, and the result usually has two focus rings, two spacing scales and two ideas of what a disabled state looks like. If you must mix, pick one owner of interaction behaviour and one owner of colour, and write the boundary down. Teams that skip that sentence end up debugging a focus outline that belongs to the other system.</p><p>Finally, write the decision down. One paragraph in the repository explaining which library owns behaviour, which owns colour, and what would trigger a migration saves every future contributor an afternoon of archaeology. The paragraph is cheap; the archaeology is not.</p><h2>Common Mistakes</h2><ul><li>Mixing two systems in one app, producing two focus styles, two spacing scales and inconsistent radii.</li><li>Adopting a 300-component kit to use four of them.</li><li>Ignoring bundle cost because "it''s tree-shakeable" without verifying the import path.</li><li>Choosing on screenshots rather than on accessibility behaviour, which is the part you cannot easily rebuild.</li></ul><h2>Browser Support / Caveats</h2><p>All credible libraries target current evergreen browsers. The differentiators are React version support (some still assume React 17), styling system coupling (Tailwind vs CSS-in-JS vs plain CSS), and whether components render into portals — which matters if you have transforms on ancestors.</p><h2>Related Resources</h2><p>A navigation bar that demonstrates a complete design-system surface is free at <a href="/products/premium-glassmorphic-navigation-bar">premium glassmorphic navigation</a>. Component composition rules are discussed in <a href="/blog/react-error-boundaries">error boundaries</a>, and the ecosystem is listed at <a href="https://react.dev/community" rel="nofollow noopener" target="_blank">react.dev</a>.</p>', 'Isaya Masika', 'published', '2027-01-27');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('svg-sprite-vs-inline-icons', 'SVG Sprites vs Inline Icons: Which Should You Ship?', 'svg-sprite-vs-inline-icons', 'SVG', 'A sprite is one cached request referenced by use href; inline icons cost zero requests but bloat the HTML and lose caching. Choose by count and reuse, not by preference.', '<p>Two icons: inline them and move on. Two hundred: inlining is megabytes of HTML that cannot be cached separately from your page. The decision is arithmetic, and the implementation has two traps that make icons render as invisible nothing.</p><h2>Direct Answer</h2><p>Use a sprite when you ship many icons and repeat them across pages: one file, one cached request, and <code>&lt;use href="#id"&gt;</code> per usage. Inline the SVG when the icon is used once, needs per-instance styling of internal paths, or must paint immediately in the critical path. Both inherit <code>currentColor</code>, so colour theming works either way.</p><h2>Full Code Example</h2><pre><code>&lt;!-- The sprite: symbols, loaded once and cached --&gt;
&lt;svg aria-hidden="true" style="display:none"&gt;
  &lt;symbol id="i-arrow" viewBox="0 0 24 24"&gt;
    &lt;path d="M5 12h14M13 6l6 6-6 6" /&gt;
  &lt;/symbol&gt;
&lt;/svg&gt;

&lt;!-- Usage: the viewBox lives on the symbol, not on the instance --&gt;
&lt;svg class="h-5 w-5 text-gray-700"&gt;
  &lt;use href="#i-arrow" /&gt;
&lt;/svg&gt;

&lt;!-- External sprite (separate file, independently cacheable) --&gt;
&lt;svg class="h-5 w-5"&gt;
  &lt;use href="/icons/sprite.svg#i-arrow" /&gt;
&lt;/svg&gt;

&lt;!-- Inline: one-off icon that needs paint-critical timing --&gt;
&lt;svg viewBox="0 0 24 24" class="h-5 w-5" role="img" aria-label="Search"&gt;
  &lt;path d="M11 4a7 7 0 100 14 7 7 0 000-14z" fill="currentColor"/&gt;
&lt;/svg&gt;</code></pre><h2>Why This Works</h2><p><code>&lt;use&gt;</code> instantiates the referenced symbol in place, giving you the full benefit of one definition and many instances. Because the sprite file is a static asset, the browser caches it across pages — the second page costs a cache hit instead of kilobytes of HTML. Inline SVGs live inside the document, so they ship with every navigation and cannot be cached on their own.</p><h3>The viewBox trap</h3><p>Put <code>viewBox</code> on the <code>symbol</code>, and leave it off the instance. A <code>&lt;use&gt;</code> with no viewBox on its target renders at intrinsic size inside the instance''s box — usually invisible. This is the number one reason sprites "don''t work".</p><h3>Styling reach</h3><p>With a sprite you cannot target individual paths from page CSS — the shadow tree is isolated. If a design needs two different path colours inside one icon, inline it. Inheriting via <code>currentColor</code> is the supported path for everything else.</p><h2>Building the Sprite in Your Pipeline</h2><p>Hand-maintaining a sprite is a chore that stops happening in month two. The durable approach generates it from individual icon files during the build, so adding an icon means adding a file.</p><h3>One file per icon</h3><p>Keep a directory of SVGs named for their ids: <code>arrow-right.svg</code> becomes <code>#i-arrow-right</code>. Stripping the outer <code>svg</code> wrapper and normalising the <code>viewBox</code> is the whole transformation, and it is scriptable in a dozen lines.</p><h3>Emitting the sprite</h3><p>Write the concatenated <code>symbol</code> set into a static file at build time, then reference it with <code>&lt;use href="/sprite.svg#id"&gt;</code>. The file gets a content hash in its name, so it caches forever and updates only when an icon changes.</p><h3>Keeping ids stable</h3><p>The id is the public API of the sprite. Renaming <code>arrow</code> to <code>arrow-right</code> silently breaks every usage, and nothing fails loudly: the icon simply disappears. Generate a manifest alongside the sprite, and let the build fail when a referenced id is missing.</p><h3>Inline alternatives</h3><ul><li>Critical above-the-fold icons: inline, to avoid a request.</li><li>Everything repeated across pages: sprite.</li><li>Icons that need per-path theming: inline, or a dedicated component.</li><li>Icons that appear on one page only: inline, since the sprite would not be cached anyway.</li></ul><h3>Symbols versus separate files</h3><p>A sprite is not the only caching strategy. Individual SVG files with hashed names cache just as well and let the browser fetch only the icons a page uses. The sprite wins when a page uses twenty icons; separate files win when it uses two. Measure actual usage per page before committing to one file, because sprites solve a problem small sites do not have. React icon packages that ship every icon as a module are a third path, letting the bundler drop unused icons with no runtime request at all.</p><p>Finally, check the sprite under a strict content security policy. External <code>use</code> references are blocked when the asset is served from a disallowed origin, and the icons fail without an obvious error.</p><h2>Common Mistakes</h2><ul><li>Missing <code>viewBox</code> on the symbol, producing zero-size icons.</li><li>External <code>&lt;use href&gt;</code> to another origin, which browsers block for security.</li><li>Inlining two hundred icons into a component tree, inflating the HTML and the render time.</li><li>Hard-coding <code>fill</code> on paths, which defeats <code>currentColor</code> theming in both approaches.</li></ul><h2>Browser Support / Caveats</h2><p><code>&lt;use&gt;</code> with same-origin external references works in all current browsers; older Safari had regressions with external sprites and needed the inline-sprite variant. Keep the sprite under a few hundred kilobytes and preload it only if icons are above the fold — otherwise let it load lazily.</p><h2>Related Resources</h2><p>Browse the full icon set at <a href="/icons">the SteaCode icon gallery</a>. The loading-priority side of this decision is covered in <a href="/blog/fetchpriority-hero-image">fetchpriority for hero images</a>, and <code>&lt;use&gt;</code> is documented at <a href="https://developer.mozilla.org/en-US/docs/Web/SVG/Element/use" rel="nofollow noopener" target="_blank">MDN</a>.</p>', 'Isaya Masika', 'published', '2027-01-28');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('accessible-svg-icons-aria-label', 'Making SVG Icons Accessible', 'accessible-svg-icons-aria-label', 'SVG', 'Decorative icons take aria-hidden and focusable=false. Meaningful icons need role=img plus a real name — usually from the button they sit in. Never let a bare path be the only label.', '<p>An icon-only button is the most common accessibility failure in modern interfaces: sighted users see a floppy disk, screen reader users hear "button". The fix is one attribute, chosen by whether the icon carries information or decorates something that already has text.</p><h2>Direct Answer</h2><p>If the icon repeats text next to it, hide it: <code>aria-hidden="true"</code> and <code>focusable="false"</code>. If the icon is the only content — an icon button, a status glyph — give the interactive element an accessible name with <code>aria-label</code>, and mark the SVG itself <code>aria-hidden</code> so it is not announced twice. Only give the SVG <code>role="img"</code> plus <code>aria-label</code> when the icon stands alone as an image.</p><h2>Full Code Example</h2><pre><code>&lt;!-- 1. Decorative: the label is already in text --&gt;
&lt;a href="/docs"&gt;
  &lt;svg aria-hidden="true" focusable="false" viewBox="0 0 24 24" class="h-4 w-4"&gt;
    &lt;path d="M5 12h14M13 6l6 6-6 6" /&gt;
  &lt;/svg&gt;
  Read the docs
&lt;/a&gt;

&lt;!-- 2. Icon-only button: the NAME goes on the button --&gt;
&lt;button type="button" aria-label="Save changes"&gt;
  &lt;svg aria-hidden="true" focusable="false" viewBox="0 0 24 24" class="h-5 w-5"&gt;
    &lt;path d="M5 5h11l3 3v11H5z" /&gt;
  &lt;/svg&gt;
&lt;/button&gt;

&lt;!-- 3. Standalone meaningful image --&gt;
&lt;svg role="img" aria-label="Warning: expiring soon" viewBox="0 0 24 24"&gt;
  &lt;path d="M12 3l9 16H3z" fill="currentColor" /&gt;
&lt;/svg&gt;

&lt;!-- 4. Visible tooltip that must ALSO be announced --&gt;
&lt;button aria-describedby="tip-1"&gt;
  &lt;svg aria-hidden="true" viewBox="0 0 24 24"&gt;...&lt;/svg&gt;
&lt;/button&gt;
&lt;span id="tip-1" class="sr-only"&gt;Deletes the selected draft&lt;/span&gt;</code></pre><h2>Why This Works</h2><p>SVG participates in the accessibility tree. Without <code>aria-hidden</code>, a decorative icon is still a node that may be announced as "graphic" — noise between two words of a link. With <code>aria-hidden</code> it disappears from the tree entirely while remaining visible on screen.</p><h3>One name, not two</h3><p>The accessible name belongs on the interactive element. Labelling both the button and the SVG produces "Save changes, Save changes" — a double announcement, and a common over-correction. Pick one owner.</p><h3>Why focusable="false"</h3><p>Legacy Edge and some embedded browsers put SVG in the tab order, so an icon inside a link could become an extra tab stop. The attribute costs nothing and removes that class of bug.</p><h2>A Five-Minute Screen Reader Test</h2><p>Accessibility claims are easy to make and cheap to verify. Three checks cover almost every icon bug, and none of them require a formal audit.</p><h3>One: walk the tab order</h3><p>Load the page and press Tab repeatedly. Every interactive element should announce a name, and decorative icons should not appear as stops at all. If you hear a graphic announced between two words of a link, an <code>aria-hidden</code> is missing.</p><h3>Two: confirm one name per control</h3><p>On an icon-only button the accessible name should be the action, not the glyph. Labelling both the button and the SVG produces a doubled announcement, while labelling only the SVG produces a nameless button in some reading modes. One owner, always the interactive element.</p><h3>Three: test with images disabled</h3><p>An icon that carries meaning with no text fallback becomes nothing when assets are blocked. That is exactly what a screen reader experiences. Status indicators need an <code>aria-label</code> or adjacent text, not just a coloured shape.</p><h3>Common repairs ranked by impact</h3><ul><li>Add a name to every icon-only button: the highest-value fix by far.</li><li>Remove <code>aria-label</code> from decorative icons beside text.</li><li>Replace colour-only meaning with text or a shape difference.</li><li>Add <code>focusable="false"</code> to legacy-proof the tab order.</li></ul><h3>Tooling that actually helps</h3><p>axe DevTools catches missing names and invalid ARIA in seconds, but it cannot tell you whether the name makes sense. Run it, fix the mechanical findings, then read the page with a screen reader for a minute. NVDA on Windows and VoiceOver on macOS are free, and one pass on the primary flow finds more than a hundred automated checks. Add a lint rule that forbids <code>&lt;svg&gt;</code> without either <code>aria-hidden</code> or a name, so the next component cannot reintroduce the bug. Rules in CI outlast intentions in a style guide.</p><p>Finally, add the check to the pull request template. A one-line question — does every icon-only control have a name? — catches the regression before it ships.</p><h2>Common Mistakes</h2><ul><li>Icon-only buttons with no <code>aria-label</code>, announced as nothing meaningful.</li><li>Relying on the SVG <code>&lt;title&gt;</code> element as the only label — support is inconsistent, and it does not name the button.</li><li><code>aria-label</code> on a decorative icon next to visible text, causing duplication.</li><li>Meaning encoded only by colour — a red dot with no text — which no attribute can repair.</li></ul><h2>Browser Support / Caveats</h2><p>ARIA on SVG is well supported. <code>focusable="false"</code> is legacy-defensive rather than required today. Remember that <code>aria-hidden</code> on a focusable element is invalid, so never hide an icon that is the actual interactive target — hide it, and label its parent instead.</p><h2>Related Resources</h2><p>The complete icon set is browsable at <a href="/icons">the SteaCode icon gallery</a>. Focus visibility is covered in <a href="/blog/css-focus-visible-hover-states">focus-visible states</a>, and ARIA usage is documented at <a href="https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Attributes/aria-hidden" rel="nofollow noopener" target="_blank">MDN</a>.</p>', 'Isaya Masika', 'published', '2027-01-29');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('svg-icon-recolor-currentcolor', 'Recolor SVG Icons with currentColor', 'svg-icon-recolor-currentcolor', 'SVG', 'Set fill and stroke to currentColor and the icon inherits its parent''s text colour. One asset, every theme, hover state included — no duplicate coloured copies.', '<p>The moment you ship four coloured copies of the same icon, the palette has four sources of truth and a dark theme doubles them. <code>currentColor</code> collapses all of that: one icon, coloured by whatever text colour surrounds it.</p><h2>Direct Answer</h2><p>Write <code>fill="currentColor"</code> on shapes (or <code>stroke="currentColor"</code> for line icons), and set the colour with a normal text utility on the icon or its parent — <code>text-gray-700</code>, <code>hover:text-amber-600</code>, <code>dark:text-gray-100</code>. Never hard-code hex values in path fills. If a specific path must differ, set <code>fill="currentColor"</code> as the default and override that path with a class.</p><h2>Full Code Example</h2><pre><code>&lt;!-- One icon, themed by its surroundings --&gt;
&lt;button class="text-gray-700 hover:text-amber-600 dark:text-gray-100"&gt;
  &lt;svg viewBox="0 0 24 24" class="h-5 w-5" aria-hidden="true"&gt;
    &lt;path d="M5 12h14M13 6l6 6-6 6" fill="currentColor" /&gt;
  &lt;/svg&gt;
  Next
&lt;/button&gt;

&lt;!-- Line icons: currentColor on the stroke --&gt;
&lt;svg viewBox="0 0 24 24" class="h-5 w-5 text-sky-600"&gt;
  &lt;circle cx="12" cy="12" r="9" fill="none" stroke="currentColor" stroke-width="2" /&gt;
&lt;/svg&gt;

&lt;!-- Per-path override when one element must stand out --&gt;
&lt;svg viewBox="0 0 24 24" class="h-5 w-5 text-gray-600"&gt;
  &lt;path d="M4 6h16v12H4z" fill="currentColor" /&gt;
  &lt;circle cx="18" cy="6" r="3" fill="#ef4444" /&gt;
&lt;/svg&gt;</code></pre><h2>Why This Works</h2><p><code>currentColor</code> is a keyword that resolves to the computed <code>color</code> of the element it is applied to. Since <code>color</code> inherits, an icon placed inside any element picks up that element''s text colour automatically — including colours set by hover, dark mode, disabled states and user-agent defaults.</p><h3>Why it beats CSS fill rules</h3><p>A rule like <code>.icon path { fill: #374151 }</code> beats the presentation attribute, so hover states must override with equal specificity, then <code>!important</code> appears, then the whole thing becomes unmaintainable. <code>currentColor</code> has no such arms race: colour changes happen on the text colour, one property, one place.</p><h3>The gradient limit</h3><p><code>currentColor</code> is a single colour and cannot feed a gradient stop. An icon that genuinely needs a gradient must use an explicit <code>&lt;linearGradient&gt;</code>, and it will not follow the theme — accept that as a deliberate exception rather than the default.</p><h2>Theming a Whole Icon Set With One Token</h2><p>The payoff of <code>currentColor</code> is not one icon; it is an entire set that follows the theme without a second asset. Design it that way from the first icon and the system stays cheap.</p><h3>One semantic colour per context</h3><p>Set the colour on the container, not the icon: a nav item sets <code>text-gray-700</code>, a toolbar sets <code>text-gray-500</code>, an active state sets <code>text-amber-600</code>. Every icon inside follows, so a new icon needs no colour decision at all.</p><h3>Dark mode for free</h3><p>Because the icon reads the computed text colour, a semantic token swap in the theme recolours every icon with zero icon-specific rules. That is the practical argument for putting colour on contexts rather than on assets.</p><h3>Opacity instead of new hexes</h3><p>For quieter icons use <code>text-gray-700/60</code> rather than inventing a lighter grey. Opacity keeps one palette entry and stays consistent across light and dark surfaces, while a new hex value multiplies the palette.</p><h3>Exceptions, handled deliberately</h3><ul><li>Multi-colour logos: keep explicit fills and treat them as brand assets, not themeable icons.</li><li>Status semantics: green, amber and red need accessible names in text, because colour alone is not meaning.</li><li>Gradient glyphs: an explicit gradient, documented as a deliberate exception.</li></ul><p>Everything else — arrows, chevrons, play buttons, social marks — should be <code>currentColor</code> with no colour of its own.</p><h3>Forced colours and print</h3><p>Windows high-contrast mode and print stylesheets override author colours, and <code>currentColor</code> follows the override because it resolves to the computed colour rather than a fixed hex. That is another argument for it over hard-coded fills: an icon set built on <code>currentColor</code> stays legible in forced-colours mode with no extra rules, while an icon painted with explicit hex values can vanish against the forced background. Check once with forced-colours emulation enabled; it takes a minute and catches icons that disappear.</p><p>Finally, apply the token on the icon component itself, not at every call site. One default colour on the component, overridable per instance, keeps the set consistent and the markup short.</p><h2>Common Mistakes</h2><ul><li>Hard-coded <code>fill="#111827"</code> in the path, which silently ignores every theme.</li><li>Setting <code>fill</code> on the <code>&lt;svg&gt;</code> and then also on a path — the path wins and the parent looks broken.</li><li>Using CSS <code>fill</code> with <code>!important</code> to force colours, which breaks all future overrides.</li><li>Forgetting <code>stroke</code> on line icons, so only the first path recolours and the rest stay invisible or black.</li></ul><h2>Browser Support / Caveats</h2><p><code>currentColor</code> has been supported since SVG 1.1 in every browser. It works through <code>&lt;use&gt;</code> sprites and through React-rendered SVG alike. In a sprite, the instance''s inherited colour reaches the symbol''s shapes, which is exactly why sprites can serve every theme from one file.</p><h2>Related Resources</h2><p>An SVG-driven decorative component is free at <a href="/products/pulsing-neon-heart-particle-animation-2">pulsing neon heart</a>. Themed colour architecture is covered in <a href="/blog/dark-mode-semantic-tokens">semantic colour tokens</a>, and the keyword is documented at <a href="https://developer.mozilla.org/en-US/docs/Web/CSS/color_value" rel="nofollow noopener" target="_blank">MDN</a>.</p>', 'Isaya Masika', 'published', '2027-01-30');
